// ==========================================
// ★ K 의 방 — C등급 직업 갈림길 · 응시
// ==========================================
// 응시 — 무엇이 진짜 무엇인지 보는 눈. 약점, 저주, 씐 것. 기괴한 곳에서 사냥할 자리를 찾는다.
// scholar 학자 · hexer 주술사 · exorcist 퇴마사 · physiog 관상가 · detective 탐정

// ── 학자 (자원 없음)
kJob('scholar', 'C', [
  { at:'C1', t:'도축장 — 부위 도표',
    x:`벽에 도표가 붙어 있다. 소 한 마리를 선으로 나눠 놓은 그림이다.<br><br>
      목심, 등심, 갈비, 사태. 칸마다 이름이 있다. 학자라면 이런 도표는 한 번쯤 베껴 본다.<br>
      갈고리에 걸린 고기는 도표대로 잘려 있다. 잘린 자리마다 살이 다시 차오르는 중이다.<br><br>
      도표에 없는 칸이 하나 있다. 고기에는 있다.`,
    o:[
      { l:'① 도표에 없는 칸을 찾아 짚는다.', k:'gaze', dc:14,
        ok:`칸을 하나씩 맞춰 봤다. 목심은 목심이고 갈비는 갈비다.<br><br>등뼈 아래, 손바닥만 한 자리가 남는다. 도표에는 선이 없다. 고기에는 거기서부터 결이 사방으로 뻗었다. 다시 자라는 살은 다 그 자리에서 나온다.<br>일행이 칼을 그 자리에 넣어 도려냈다. 갈고리의 고기가 더는 차오르지 않는다.<br><br>도표는 틀리지 않았다. 다 적지 않았을 뿐이다. 적힌 것과 눈앞의 것을 겹쳐 보면 빈칸이 보인다. 빈칸을 찾는 눈이 조금 빨라졌다.`,
        ng:`맞춰 보는데 도표가 하나씩 어긋난다.<br><br>고기가 자라면서 칸이 밀렸다. 갈비가 사태 자리에 와 있다.<br>짚은 자리에 칼을 넣었다. 살이 칼을 물고 놓지 않았다. 빼내다 손목이 꺾였다.`,
        win:{ exp:20, dream:3 }, lose:{ hp:-14, mind:-6 }, wake:1 },
      { l:'② 냄새로 자라기 전의 고기를 고른다.', k:'sense', dc:13,
        ok:`갓 자란 살은 냄새가 없다. 피 냄새도 비린내도.<br><br>냄새가 나는 고기는 처음부터 있던 살이다. 짐승이 정말 죽어서 남긴 것이다.<br>갈고리 끝에서 한 덩이를 떼어 냈다. 아마 괜찮다.<br><br>아마.`,
        ng:`다 같은 냄새다. 코가 먼저 지쳤다.<br><br>집어 든 고기가 손안에서 따뜻해진다. 자라는 중이다.<br>내던졌다. 손바닥에 결 자국이 남았다.`,
        win:{ exp:14, item:'짐승 고기' }, lose:{ hp:-10, mind:-8 } }
    ] },

  { at:'C1', t:'도축장 — 작업 일지',
    x:`작업대 서랍에 일지가 있다. 반장 글씨다.<br><br>
      「오늘 마흔 마리.」 「오늘 마흔 마리.」 같은 줄이 몇 장이고 이어진다.<br>
      한 장에 하루다. 날짜는 매일 바뀌는데 숫자는 안 바뀐다.<br><br>
      뒤로 갈수록 날짜 옆에 시각이 붙는다. 종이 울린 시각이다.`,
    o:[
      { l:'① 종이 울린 시각을 맞춰 본다.', k:'gaze', dc:14,
        ok:`시각을 세로로 늘어놓았다. 여섯 시간마다 한 번. 한 번도 안 어긋났다.<br><br>종이 울리면 줄이 선다. 서는 동안 갈고리가 멈춘다. 일지 귀퉁이에 「쉼 — 백 번 셀 동안」이라고 적혀 있다.<br>다음 종을 기다렸다. 울렸다. 갈고리가 섰다.<br><br>백을 세는 동안 일행이 갈고리 줄 밑을 다 지났다. 아흔일곱에서 다시 움직였다. 반장은 셈이 조금 짰다.`,
        ng:`시각을 맞추다 한 장이 비었다. 그날은 종이 안 울렸다.<br><br>안 울린 날 다음 장은 숫자가 마흔하나다.<br>종을 기다리다 갈고리가 머리 위를 지났다. 머리카락이 한 줌 걸려 나갔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-10, mind:-8 } },
      { l:'② 서랍 안쪽을 뒤진다.', k:'luck', dc:13,
        ok:`일지 밑에 도시락 통이 있다. 반장 것이다.<br><br>안에 소금이 굳어 있다. 고기에 치려고 들고 다닌 것이다.<br>반장은 끝까지 셈하고 끝까지 간을 했다.<br><br>통째로 챙겼다.`,
        ng:`서랍 안쪽이 끈적하다. 손을 넣자 무언가 손가락을 감쌌다.<br><br>살이다. 서랍 안에서도 자란다.<br>빼냈다. 손가락 사이가 쓰리다.`,
        win:{ exp:12, item:'소금 덩이' }, lose:{ hp:-10, spirit:-6 } }
    ] },

  { at:'C1', t:'도축장 — 갈고리 번호',
    x:`천장 레일에 갈고리가 줄지어 매달렸다. 갈고리마다 쇠 표가 달려 있다.<br><br>
      1, 2, 3, 4. 번호가 순서대로 흘러간다. 셈하는 사람에게는 편한 줄이다.<br>
      어느 자리에서 번호가 하나 빠진다. 17 다음이 19다.<br><br>
      18번 표는 줄 밖에, 기둥 그림자 안에 걸려 있다.`,
    o:[
      { l:'① 18번이 무엇에 걸려 있는지 다가가 읽는다.', k:'gaze', dc:15,
        doom:{ title:'18번', what:'갈고리가 옷깃을 꿰어 끌고 갑니다', dc:14, sec:60,
          text:`그림자 안으로 한 걸음 들어갔다. 표에 숫자가 또렷하다. 18.<br><br>표가 걸린 건 갈고리가 아니다. 손가락이다. 길고 마디가 많다.<br>읽는 사이 그 손가락이 이쪽 옷깃을 꿰었다. 레일이 움직인다. 발이 바닥에서 뜬다.<br><br>갈고리 줄이 이쪽을 17과 19 사이로 데려간다. 빈자리가 채워지려 한다.`,
          dieText:`레일의 번호가 이제 빠짐없다.<br><br>17, 18, 19. 셈하는 사람에게는 편한 줄이다.<br>18번 표 밑에는 이제 아무 그림자도 없다.` },
        ok:`그림자 끝에서 멈췄다. 등불을 들이밀지 않았다. 표만 읽었다.<br><br>쇠 표 끝이 갈고리가 아니라 마디진 손가락에 감겨 있다. 레일에 매달린 것은 갈고리 사이에 숨어 있었다. 번호를 세어 줄 사람을 기다리면서.<br>일행에게 손가락으로 18을 그려 보였다. 다들 기둥에서 멀찍이 떨어져 지났다.<br><br>빠진 숫자는 늘 무언가 들어갈 자리다.`,
        win:{ exp:22, dream:3 } },
      { l:'② 레일 이음매의 핀을 뽑는다.', k:'break', dc:14,
        ok:`레일과 레일 사이에 쇠 핀이 박혀 있다. 이음매다.<br><br>쇠막대로 쳐서 뽑았다. 레일 한 칸이 기울었다. 갈고리들이 그 칸에서 미끄러져 바닥에 쏟아졌다.<br>기둥 그림자에서 무언가 같이 떨어졌다. 마디진 것이 바닥을 기어 달아났다.<br><br>줄이 끊기면 숨은 것도 내려온다.`,
        ng:`핀이 녹슬어 안 빠진다. 치는 소리가 레일을 타고 끝까지 갔다.<br><br>갈고리 줄 전체가 이쪽으로 흘러온다. 빨라진다.<br>엎드렸다. 등 위로 갈고리가 지났다. 하나가 등을 그었다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-6 } },
      { l:'③ 번호를 세지 않고 바닥만 보고 지난다.', k:'steady', dc:14,
        ok:`고개를 숙였다. 표도 갈고리도 안 봤다.<br><br>세지 않으면 빠진 걸 모른다. 모르면 다가가지 않는다.<br>바닥 배수구 줄을 따라 걸었다. 셈하고 싶은 손가락을 주먹 안에 쥐었다.<br><br>다 지나고 나서야 손을 폈다. 손바닥에 손톱자국이 넷.`,
        ng:`바닥만 보는데 머릿속이 저절로 센다. 갈고리 소리로.<br><br>열일곱. 열아홉. 고개가 들렸다.<br>기둥 그림자가 이쪽을 보고 있었다. 뒷걸음질하다 배수구에 발목이 빠졌다.`,
        win:{ exp:14, mind:6 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C2', t:'인형 공방 — 이 견본함',
    x:`작업대 옆에 서랍이 많은 장이 있다. 칸마다 이가 들어 있다.<br><br>
      칸 앞에 쪽지가 붙었다. 「여섯 살」 「열 살」 「어른」. 이 모양으로 나이를 가른 것이다.<br>
      선반 위 인형들이 입을 반쯤 벌리고 있다. 사기 입술 사이로 이가 보인다. 진짜 이다.<br><br>
      몇몇 인형은 이가 아직 덜 났다.`,
    o:[
      { l:'① 이 난 모양으로 인형의 나이를 가른다.', k:'gaze', dc:15,
        ok:`책에서 본 순서대로 셌다. 앞니, 송곳니, 어금니. 이는 나는 순서가 정해져 있다.<br><br>다 난 인형은 오래된 것이다. 사기가 누렇고 관절이 굳었다. 느리다.<br>덜 난 인형은 새것이다. 잇몸 자리가 아직 붉다. 이가 다 날 때까지 먹어야 한다.<br><br>일행에게 덜 난 것부터 깨게 했다. 배고픈 것부터. 견본 칸의 쪽지와 눈앞의 입을 겹쳐 보니 나이가 저절로 읽혔다. 표 하나를 통째로 머리에 넣고 다니는 법이 손에 익었다.`,
        ng:`세다가 셈이 꼬였다. 어금니가 앞에 난 인형이 있다. 순서에 없는 입이다.<br><br>그 인형이 입을 닫았다. 딱 소리가 났다.<br>선반 전체가 따라 닫았다. 이쪽 손가락 끝이 그 사이에 있었다.`,
        win:{ exp:20, dream:3 }, lose:{ hp:-14, mind:-6 }, wake:1 },
      { l:'② 견본함 맨 아래 칸을 연다.', k:'luck', dc:13,
        ok:`맨 아래 칸에는 이가 없다. 사탕 통이 있다.<br><br>공방 사람들이 본을 서는 아이에게 주던 것 같다. 뚜껑에 「입 벌리면 하나」.<br>안에 굳은 꿀이 남았다.<br><br>한 줌 덜었다. 선반 위 인형들이 일제히 입을 벌렸다. 안 줬다.`,
        ng:`맨 아래 칸이 무겁다. 당기자 칸째 쏟아졌다.<br><br>이가 바닥에 흩어졌다. 수백 개. 소리가 그치지 않는다.<br>선반 위 인형들이 고개를 돌렸다. 주우러 오는 것 같다. 물러나다 넘어졌다.`,
        win:{ exp:12, item:'꿀 한 줌' }, lose:{ hp:-10, spirit:-8 } }
    ] },

  { at:'C2', t:'인형 공방 — 조립 순서',
    x:`벽에 큰 종이가 붙어 있다. 관절 인형 그림이다. 마디마다 번호가 매겨졌다.<br><br>
      1번 발목, 2번 무릎, 3번 고관절. 마지막 번호는 목이다. 목 옆에만 붉은 글씨로 덧붙였다. 「다 끼우고 나서」.<br>
      설명서는 위에서부터 읽는 것이다. 이쪽은 늘 끝까지 읽는다.<br><br>
      선반에서 사기 인형 셋이 내려온다. 천장 실에 매달려 한 마디씩.`,
    o:[
      { l:'① 순서를 거꾸로 읽어 해체 순서를 세운다.', k:'gaze', dc:14,
        ok:`끼운 순서의 반대가 빼는 순서다. 목부터.<br><br>목 핀은 마지막에 끼운 것이라 제일 얕다. 일행에게 목덜미 뒤 핀만 노리게 했다.<br>하나가 빠지자 인형이 실에 매달린 채 늘어졌다. 둘째도. 셋째는 일행이 손으로 뽑았다.<br><br>설명서는 만드는 사람을 위해 쓴 것이다. 부수는 사람에게도 똑같이 친절하다.`,
        ng:`거꾸로 세다 번호를 하나 건너뛰었다.<br><br>목이 아니라 어깨를 노리게 했다. 어깨 핀이 빠지자 팔이 떨어져 나와 혼자 기어 왔다.<br>팔 하나가 발목을 물었다. 팔에도 이가 있다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
      { l:'② 그림을 찢어 일행에게 한 마디씩 외우게 한다.', k:'fix', dc:14,
        ok:`종이를 다섯 조각으로 찢었다. 한 사람에 한 마디씩.<br><br>자기 마디만 외우면 된다. 발목 맡은 사람은 발목만 본다.<br>인형이 내려올 때마다 각자 제 마디를 쳤다. 다섯이 한 인형을 나눠 부쉈다.<br><br>책 한 권을 다섯이 나눠 읽는 법과 같다.`,
        ng:`찢는 사이 인형이 다 내려왔다.<br><br>조각을 받은 사람들이 서로 제 마디를 찾느라 늦었다.<br>목 맡은 사람이 물렸다. 끌어내느라 다들 다쳤다.`,
        win:{ exp:14, spirit:6 }, lose:{ hp:-12, mind:-6 } }
    ] },

  { at:'C2', t:'인형 공방 — 발바닥의 이름',
    x:`인형 발바닥마다 글씨가 있다. 공방 낙관과 이름, 날짜.<br><br>
      이름은 사람 이름이다. 날짜는 만든 날이다.<br>
      벽에 걸린 직원 명부를 봤다. 같은 이름이 있다. 이름 옆에 줄이 그어졌다. 그은 날이 인형 날짜와 같다.<br><br>
      명부 맨 끝 이름에는 아직 줄이 없다.`,
    o:[
      { l:'① 명부와 인형을 하나씩 맞춰 본다.', k:'gaze', dc:14,
        ok:`하나씩 대조했다. 이름, 날짜, 키.<br><br>인형 키가 명부에 적힌 키와 같다. 한 치도 안 틀린다. 공방은 사람을 재서 만들었다.<br>맨 끝 이름의 키는 이 방 어느 인형과도 안 맞는다. 아직 안 만들어졌다. 그 사람은 아직 위층에 있다.<br><br>일행에게 말했다. 위층에 하나는 아직 사람이다. 칼을 그쪽으로 휘두르지 말라고.`,
        ng:`맞추다 보니 하나가 안 맞는다. 이름만 있고 인형이 없다.<br><br>찾으려고 둘러보는 사이 뒤에서 사기 발소리가 났다.<br>돌아보니 인형 하나가 이쪽 키만큼 서 있다. 발바닥이 비었다.`,
        win:{ exp:18, dream:2, spirit:5 }, lose:{ spirit:-12, mind:-6 } },
      { l:'② 인형 발바닥 이름을 긁어 지운다.', k:'break', dc:13,
        ok:`칼끝으로 이름을 긁었다. 하나씩.<br><br>이름을 잃은 인형은 실이 느슨해진다. 무엇을 흉내 내야 할지 잊는다.<br>선반 위에서 몇 개가 고개를 떨어뜨렸다.<br><br>기록을 지우는 건 내키지 않는 일이다. 오늘은 했다.`,
        ng:`긁는데 사기가 이쪽 칼끝을 문다. 발바닥에도 이가 있다.<br><br>칼을 놓쳤다. 인형이 칼을 쥐었다.<br>되찾는 데 손등을 내줬다.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 머리 위의 비문',
    x:`성당이 거꾸로 매달렸다. 발밑은 둥근 천장이고 머리 위 먼 데에 바닥이 있다.<br><br>
      의자들이 머리 위에 박힌 채 매달렸다. 바닥에 새긴 비문도 머리 위다. 거꾸로다.<br>
      거꾸로 된 글은 이쪽에게 어렵지 않다. 책을 뒤집어 읽는 버릇이 있었다.<br><br>
      비문 옆으로 종 같은 것들이 천천히 흔들린다. 종이 아니다. 숨을 쉰다.`,
    o:[
      { l:'① 고개를 젖히고 비문을 끝까지 읽는다.', k:'gaze', dc:15,
        ok:`종지기들의 이름이다. 이름마다 종 하나와 치는 순서가 붙어 있다.<br><br>「셋째 종은 둘째 다음에만. 먼저 치면 내려온다.」<br>종 같은 것들이 숨 쉬는 순서를 봤다. 비문 순서와 같다. 저것들은 아직 순서를 지킨다.<br><br>순서가 비는 틈에 일행을 건너게 했다. 거꾸로 읽고 바로 세우는 데 숨 한 번이면 됐다. 글이 어느 쪽으로 놓여 있든 이제 뜻이 먼저 온다.`,
        ng:`고개를 오래 젖혔더니 피가 머리로 몰렸다. 글자가 흔들린다.<br><br>셋째와 둘째를 바꿔 읽었다. 일행이 셋째 앞을 먼저 지났다.<br>종 같은 것이 내려왔다. 한 사람을 덮었다가 놓았다. 그 사람 귀에서 한참 소리가 났다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-12, mind:-8 }, wake:1 },
      { l:'② 종 그림자만 보고 건넌다.', k:'evade', dc:14,
        ok:`종 같은 것들의 그림자가 발밑 천장에 진다. 흔들리는 박자대로.<br><br>그림자가 멀어지는 틈마다 한 칸씩 건넜다.<br>머리 위는 안 봤다. 그림자만 봐도 된다.<br><br>마지막 칸에서 뒤를 봤다. 그림자 하나가 이쪽이 지난 자리에 오래 머물렀다.`,
        ng:`그림자 박자가 갑자기 바뀌었다.<br><br>멈췄는데 늦었다. 무언가 차갑고 둥근 것이 등을 쳤다.<br>천장 늑골 위로 굴렀다. 겨우 가장자리에서 멈췄다.`,
        win:{ exp:14, dream:2 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 성가 악보',
    x:`성가대석이 머리 위에 매달렸다. 악보대가 떨어지지 않고 붙어 있다.<br><br>
      노래가 들린다. 사람 목소리인데 너무 많다. 입 하나에 한 소리여야 하는데, 하나에서 서넛이 난다.<br>
      학자는 악보를 올려다봤다. 네 성부다. 지금 나는 소리는 열하나다.<br><br>
      노래가 이어지는 동안 일행이 한 걸음도 못 나간다. 귀에서 쇠 맛이 난다.`,
    o:[
      { l:'① 악보에서 쉼표를 찾는다.', k:'gaze', dc:14,
        ok:`네 성부를 한 줄씩 따라갔다. 노래는 길어도 숨은 쉬어야 한다.<br><br>스무째 마디에 네 성부가 한꺼번에 쉰다. 남는 일곱 소리도 그 자리에서는 쉰다. 남의 악보를 빌려 부르니 쉬는 데도 빌린다.<br>그 마디에 맞춰 일행을 뛰게 했다.<br><br>조용한 두 박이 그렇게 길 줄 몰랐다. 다 건넜다.`,
        ng:`쉼표를 찾았는데 넘기다 장이 하나 빠졌다.<br><br>엉뚱한 마디에 일행이 뛰었다. 노래 한복판이었다.<br>다들 귀를 감싸고 쓰러졌다. 일어나는 데 오래 걸렸다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-10, spirit:-8 } },
      { l:'② 악보에 없는 일곱 소리의 자리를 짚는다.', k:'sense', dc:15,
        ok:`악보에 없는 소리만 골라 들었다. 낮은 쪽, 오른쪽 끝.<br><br>성가대원 하나의 목 아래로 입이 줄지어 있다. 남는 소리가 다 거기서 난다.<br>일행이 그쪽으로 창을 올려 찔렀다. 노래가 일곱 줄었다.<br><br>남은 넷은 악보대로 불렀다. 듣기 나쁘지 않았다.`,
        ng:`소리를 가리다 이쪽 목에서도 소리가 났다.<br><br>안 불렀는데 따라 부른다. 다섯째 성부로.<br>입을 막았다. 손바닥 안에서 한참 노래가 멎지 않았다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-12, spirit:-8 } },
      { l:'③ 귀를 막고 늑골 사이에 엎드려 버틴다.', k:'steady', dc:13,
        ok:`천을 뭉쳐 귀를 막았다. 늑골 사이 홈에 엎드렸다.<br><br>노래는 오래 갔다. 그래도 끝은 났다. 모든 악보에는 마지막 마디가 있다.<br>끝나자마자 일어나 건넜다.<br><br>천을 빼니 귀가 먹먹하다. 먹먹한 게 낫다.`,
        ng:`귀를 막아도 노래가 뼈로 들어온다.<br><br>늑골이 같이 울린다. 이쪽 갈비도.<br>끝났을 때 코에서 피가 났다.`,
        win:{ exp:12, mind:5 }, lose:{ hp:-10, mind:-8 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 열셋째 늑골',
    x:`발밑 천장은 갈비뼈 같은 돌 줄로 나뉘어 있다. 늑골이라 부른다. 줄 사이는 얇은 판이다.<br><br>
      건물 책에서 읽었다. 무게는 늑골로 내려간다. 판은 밟으면 안 된다.<br>
      늑골은 열둘이다. 그림대로라면 열둘이어야 한다.<br><br>
      열셋이다. 하나가 조금 더 희고, 조금 더 따뜻해 보인다.`,
    o:[
      { l:'① 늑골의 결을 읽어 돌만 밟고 건넌다.', k:'gaze', dc:15,
        doom:{ title:'열셋째 늑골', what:'늑골이 몸을 감아 들어 올립니다', dc:15, sec:55,
          text:`결을 보며 걸었다. 돌은 결이 곧다. 열둘째까지 곧았다.<br><br>마지막 한 줄에서 결이 휘었다. 발을 올린 뒤였다.<br>늑골이 숨을 쉰다. 마디마다 굽는다. 이쪽 발목을, 무릎을 감는다.<br><br>그것은 성당을 받치는 시늉을 하며 오래 기다렸다. 이제 이쪽을 머리 위 어둠으로 들어 올린다.`,
          dieText:`늑골은 다시 열둘이다.<br><br>그림과 맞는다. 책과 맞는다.<br>머리 위 어둠에서 무언가 천천히 씹는 소리가 오래 났다.` },
        ok:`한 줄씩 결을 읽었다. 돌은 결이 곧고 차다.<br><br>희고 따뜻한 줄은 결이 없다. 마디가 있다. 그 줄만 건너뛰었다. 한 걸음을 크게.<br>뒤따르는 일행에게 디딜 자리를 하나하나 짚어 주었다.<br><br>다 건너고 돌아보니 열셋째 늑골이 조금 굽어 있었다. 아까는 곧았다.`,
        win:{ exp:22, dream:3 } },
      { l:'② 판 위를 빠르게 뛰어 건넌다.', k:'evade', dc:15,
        ok:`판은 밟으면 금이 간다. 금이 가기 전에 지나면 된다.<br><br>달렸다. 발밑에서 판이 쩍쩍 울었다. 마지막 판에서 뛰었다.<br>뒤에서 판 하나가 떨어져 나가 머리 위 어둠으로 떨어졌다. 아니, 올라갔다.<br><br>소리는 한참 뒤에야 났다.`,
        ng:`셋째 판에서 발이 빠졌다. 허벅지까지.<br><br>판 아래는 비었다. 비어 있는데 무언가 발끝을 만졌다.<br>일행이 끌어 올렸다. 정강이가 갈렸다.`,
        win:{ exp:14, dream:2 }, lose:{ hp:-16, spirit:-6 } }
    ] },

  { at:'C4', t:'포자 온실 — 화단 표찰',
    x:`온실 화단마다 작은 표찰이 꽂혀 있다. 식물 이름과 심은 날.<br><br>
      「쑥」 「박하」 「당귀」. 표찰은 그대로인데 화단에는 허연 버섯만 빽빽하다.<br>
      식물 도감은 몇 권이고 외웠다. 버섯은 이렇게 자라지 않는다. 줄을 맞춰서.<br><br>
      버섯들이 표찰 순서대로 서 있다. 심은 자리를 따라.`,
    o:[
      { l:'① 표찰로 원래 자리를 짚어 버섯 밑을 헤친다.', k:'gaze', dc:14,
        ok:`버섯은 심은 자리를 먹고 선다. 그러면 밑동 쪽에 원래 것이 남았을 수 있다.<br><br>「당귀」 표찰 아래를 손가락으로 헤쳤다. 버섯 밑동 아래 마른 뿌리가 있다. 아직 향이 난다.<br>버섯은 원래 것을 다 먹지 못했다. 쓴 것은 남겼다.<br><br>표찰 셋을 돌며 약초를 한 묶음 모았다. 장갑은 버렸다.`,
        ng:`헤치는데 버섯이 터졌다. 허연 가루가 얼굴을 덮었다.<br><br>숨을 참았는데 늦었다. 목 안이 간지럽다.<br>간지러운 것이 한참 안 가셨다.`,
        win:{ exp:16, item:'약초 뭉치' }, lose:{ hp:-10, mind:-8 } },
      { l:'② 표찰 없는 화단을 찾는다.', k:'luck', dc:13,
        ok:`맨 구석 화단에 표찰이 없다. 버섯도 없다.<br><br>무엇을 심었는지 적히지 않은 자리는 버섯이 따라 설 줄을 모른다.<br>거기 산나물이 제멋대로 자랐다. 아무도 이름을 안 붙인 것들이다.<br><br>한 아름 뜯었다. 이름이 없어서 살았다.`,
        ng:`표찰 없는 화단을 찾았는데 흙이 부풀어 있다.<br><br>손을 대자 흙이 숨을 쉰다. 아래에 무언가 누워 있다. 사람 크기다.<br>물러났다. 흙이 따라서 조금 일어났다가 가라앉았다.`,
        win:{ exp:12, item:'산나물' }, lose:{ spirit:-10, mind:-6 } }
    ] },

  { at:'C4', t:'포자 온실 — 정원사 일지',
    x:`도구 창고 선반에 정원사 일지가 있다.<br><br>
      처음엔 물 준 시각과 온도뿐이다. 중간부터 다른 줄이 끼어든다. 「목덜미가 가렵다.」 「숨이 달다.」 「기분이 좋다.」<br>
      글씨가 뒤로 갈수록 둥글어진다. 마지막 장은 먹 대신 허연 가루로 썼다.<br><br>
      창고 문 밖으로 정원사 옷을 입은 것이 셋 지나간다. 걸음이 같다.`,
    o:[
      { l:'① 증상이 적힌 순서를 따라 약한 데를 짚는다.', k:'gaze', dc:15,
        ok:`증상이 처음 적힌 자리부터 셌다. 목덜미가 먼저다. 다음이 숨, 다음이 기분.<br><br>들어온 자리가 제일 오래된 자리다. 오래된 자리는 굳어서 단단하거나, 다 먹혀서 비었거나. 일지 마지막 장이 답이다. 「목이 가볍다.」 비었다.<br>일행에게 정원사 옷의 목덜미만 노리게 했다. 첫째가 쓰러지고 옷 안에서 허연 것이 흘러나왔다.<br><br>일지 한 권이 증상의 순서가 되고, 순서가 약점이 되었다. 읽은 것을 차례로 세우면 칼 넣을 자리가 나온다. 이쪽은 이제 그걸 먼저 찾는다.`,
        ng:`순서를 세다 가루로 쓴 마지막 장을 만졌다.<br><br>손끝이 간지럽다. 목덜미도.<br>정원사 옷 셋이 창고 문 앞에서 멈췄다. 같은 걸음으로 돌아섰다. 다 같이 물러나느라 다쳤다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-12, mind:-8 }, wake:1 },
      { l:'② 젖은 천으로 일행의 입을 막게 한다.', k:'fix', dc:14,
        ok:`일지 앞쪽에 적혀 있었다. 「가루 날리는 날은 젖은 천」.<br><br>물통을 털어 천을 적셨다. 한 사람씩 입과 코를 감쌌다.<br>정원사들이 지나갈 때 가루가 날렸다. 천 안쪽으로는 안 들어왔다.<br><br>일지는 처음 쓴 사람을 살리지 못했다. 뒤에 온 사람은 살렸다.`,
        ng:`천이 모자랐다. 하나가 맨입이었다.<br><br>그 사람이 기침을 했다. 기침 끝에 웃었다.<br>웃음을 멈추게 하는 데 다들 진이 빠졌다.`,
        win:{ exp:14, spirit:6 }, lose:{ mind:-10, spirit:-8 } }
    ] },

  { at:'C4', t:'포자 온실 — 유리에 뻗은 실',
    x:`온실 유리에 허연 실이 퍼져 있다. 버섯 뿌리다. 균사라고 책에 나온다.<br><br>
      실은 갈라지고 또 갈라진다. 강이 바다로 갈 때 갈라지는 모양이다. 거꾸로 보면 모인다.<br>
      굵은 줄, 가는 줄. 가는 줄은 굵은 줄로 들어간다.<br><br>
      유리 너머 안쪽 어딘가가 맥을 치듯 희미하게 밝아졌다 어두워진다.`,
    o:[
      { l:'① 굵기를 따라 실이 모이는 곳을 짚는다.', k:'gaze', dc:14,
        ok:`가는 줄에서 굵은 줄로 거슬러 갔다. 손가락으로 유리 위를 짚으며.<br><br>모든 줄이 한 데로 간다. 온실 가운데, 물탱크 아래다. 밝아졌다 어두워지는 곳과 같다.<br>그 자리를 비켜 도는 길을 그렸다. 그리고 나중에 칠 자리로 표시해 두었다.<br><br>지도 없는 데서 지도를 찾았다. 버섯이 그려 준 지도다.`,
        ng:`거슬러 가다 줄 하나가 손가락을 따라왔다.<br><br>유리 안쪽에서. 이쪽 손가락이 가는 대로.<br>손을 떼자 그 줄이 유리를 두드렸다. 안쪽에서 무언가 깨어나는 소리가 났다. 뛰었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-10, spirit:-8 } },
      { l:'② 실이 안 닿은 귀퉁이의 물통을 찾는다.', k:'luck', dc:13,
        ok:`실은 유리를 다 덮었는데 한 귀퉁이만 비었다.<br><br>그 아래 빗물 통이 있다. 뚜껑이 쇠다. 버섯은 쇠를 싫어하는 것 같다.<br>뚜껑을 열었다. 물이 맑다. 냄새도 없다.<br><br>통을 다 비우진 않았다. 다음에 올 일행 몫을 두었다.`,
        ng:`귀퉁이 통을 열었는데 물 위에 허연 막이 떴다.<br><br>걷어 내려는데 막이 손가락에 감겼다. 물속까지 실이다.<br>떼어 냈다. 손가락이 하얗게 불었다.`,
        win:{ exp:12, item:'맑은 물' }, lose:{ hp:-8, mind:-8 } }
    ] },

  { at:'C', t:'방 — 꿰맨 짐승',
    x:`어둠 속에서 짐승 하나가 나왔다. 앞다리는 개, 뒷다리는 사슴, 목은 너무 길다.<br><br>
      솔기가 보인다. 굵은 실로 꿰맸다. 서툴지 않다. 해부도를 보고 꿰맨 솜씨다.<br>
      해부도라면 이쪽도 여러 장 외웠다. 무엇이 무엇에 붙어야 하는지.<br><br>
      일행이 칼을 뽑는다. 짐승이 이쪽 냄새를 맡는다.`,
    o:[
      { l:'① 해부도와 다른 자리를 찾아 일행에게 알린다.', k:'gaze', dc:15,
        ok:`다리 넷을 차례로 봤다. 개 다리는 개 어깨에, 사슴 다리는 사슴 엉덩이에. 맞다.<br><br>목이 틀렸다. 어느 짐승의 목도 저 자리에 안 붙는다. 꿰맨 이가 제일 나중에, 제일 서둘러 붙였다. 솔기가 얇다.<br>「목 밑 솔기.」 일행 칼이 그 자리로 갔다. 짐승이 두 덩어리가 되어 쓰러졌다. 각자 제 모양으로.<br><br>그림 여러 장을 머릿속에 한꺼번에 펴 놓고 겹치는 법. 한 장씩 넘기던 것을 이제 겹쳐서 본다.`,
        ng:`해부도와 다른 데가 너무 많다. 짚을 데를 못 정했다.<br><br>짐승이 먼저 왔다. 길쭉한 목이 휘어 이쪽 어깨를 물었다.<br>일행이 떼어 냈다. 물린 자리가 뜨겁다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 }, wake:1 },
      { l:'② 솔기를 노려 직접 벤다.', k:'break', dc:15,
        ok:`솔기 하나를 골라 칼을 넣었다. 실이 터졌다.<br><br>짐승의 앞다리가 몸에서 떨어져 나가 혼자 달아났다. 남은 몸이 기우뚱했다.<br>일행이 남은 몸을 끝냈다.<br><br>떨어진 다리는 어둠 속에서 한참 걸어 다녔다.`,
        ng:`솔기에 칼을 넣었는데 실이 칼을 감았다.<br><br>당기는 사이 짐승이 몸을 틀었다. 끌려가다 넘어졌다.<br>사슴 발굽에 옆구리를 채였다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-6 } },
      { l:'③ 바람을 등지지 않게 돌아 뒤를 잡는다.', k:'hide', dc:14,
        ok:`짐승은 냄새로 본다. 코가 개 코다. 바람을 등지면 안 된다.<br><br>바람이 오는 쪽으로 돌았다. 짐승이 두리번거렸다.<br>그 틈에 일행이 뒤에서 덮쳤다.<br><br>꿰맨 짐승은 꿰맨 자리만큼 둔하다.`,
        ng:`도는데 발밑의 뼈를 밟았다.<br><br>짐승의 긴 목이 소리 난 쪽으로 단번에 휘었다.<br>이쪽 코앞에서 멈췄다. 숨 냄새가 비리다. 물러나다 넘어졌다.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C', t:'방 — 앞서 온 사냥꾼들의 셈',
    x:`벽에 작대기가 그어져 있다. 다섯씩 묶었다. 사냥꾼들이 잡은 것을 세는 방식이다.<br><br>
      묶음 옆에 그림이 하나씩 있다. 다리 많은 것, 날개 있는 것, 아무 모양도 없는 것.<br>
      아래로 갈수록 작대기가 준다. 마지막 줄은 그림만 있고 작대기가 없다.<br><br>
      그림은 입만 있는 둥근 것이다.`,
    o:[
      { l:'① 그림 옆 작은 글씨까지 끝까지 읽는다.', k:'gaze', dc:14,
        ok:`그림마다 옆에 한 줄씩 있다. 「불 싫어함」 「물 싫어함」. 사냥꾼의 셈법이다.<br><br>둥근 것 옆에는 「소리 나면 옴. 소리 안 나면 못 봄.」<br>사냥꾼들은 그걸 적고 나서 소리를 냈다. 마지막 줄에 작대기가 없는 까닭이다.<br><br>일행에게 신을 벗게 했다. 맨발로 지났다. 둥근 것은 이쪽이 지나가는 내내 다른 데를 보고 있었다.`,
        ng:`작은 글씨가 닳아서 안 읽힌다.<br><br>손가락으로 더듬어 읽으려다 손톱이 벽을 긁었다. 끽 소리.<br>어둠 속에서 무언가 굴러왔다. 입부터.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
      { l:'② 사냥꾼들이 남긴 짐을 찾는다.', k:'luck', dc:13,
        ok:`셈 그린 벽 아래 바위틈에 짐이 있다. 사냥꾼 셋 몫이다.<br><br>말린 고기가 남았다. 한 사람 몫은 손도 안 댔다.<br>먹을 틈이 없었던 것이다.<br><br>챙겼다. 벽에 작대기를 하나 그었다. 받았다는 뜻으로.`,
        ng:`바위틈에 손을 넣자 안쪽이 축축하다.<br><br>짐이 아니라 둥근 것의 등이다. 숨을 쉰다.<br>손을 빼고 숨을 참았다. 한참을 그렇게 서 있었다.`,
        win:{ exp:12, item:'말린 고기' }, lose:{ spirit:-10, mind:-6 } }
    ] },

  { at:'C', t:'방 — 표본병',
    x:`선반에 유리병이 늘어서 있다. 안에 무언가 떠 있다. 하나같이 이 세상에 없는 모양이다.<br><br>
      병마다 손글씨 꼬리표가 붙었다. 이름, 잡은 날, 잡은 자리.<br>
      분류된 것을 보면 마음이 놓인다. 누가 이걸 읽을 수 있게 정리해 두었다.<br><br>
      맨 끝 병은 비었다. 꼬리표가 안쪽을 향해 붙어 있다.`,
    o:[
      { l:'① 선반 안쪽으로 들어가 마지막 꼬리표를 읽는다.', k:'gaze', dc:15,
        doom:{ title:'마지막 병', what:'선반 안쪽으로 끌려 들어갑니다', dc:14, sec:60,
          text:`선반 사이로 몸을 밀어 넣었다. 꼬리표까지 팔 하나 길이.<br><br>꼬리표를 돌렸다. 이름 칸이 비었다. 잡은 날은 오늘. 잡은 자리는 이 선반.<br>그때 선반 뒤 어둠에서 손이 나왔다. 손가락이 핀셋처럼 가늘다. 이쪽 뒷덜미를 집었다.<br><br>정리하는 이가 이쪽을 안쪽으로 당긴다. 분류하려고.`,
          dieText:`맨 끝 병에 이제 무언가 떠 있다.<br><br>꼬리표는 바깥을 향해 고쳐 붙었다. 이름 칸도 채워졌다.<br>읽을 수 있게 잘 정리되어 있다.` },
        ok:`선반 안쪽으로는 안 들어갔다. 옆 병의 유리에 비친 글씨를 읽었다. 거꾸로지만 읽힌다.<br><br>이름 칸이 비었다. 잡은 날은 오늘. 잡은 자리는 이 선반.<br>선반 뒤 어둠에서 가느다란 손가락이 기다리다 거둬 들어가는 게 유리에 비쳤다.<br><br>꼬리표를 읽은 것만으로 충분하다. 오늘 표본이 될 생각은 없다.`,
        win:{ exp:22, dream:3, spirit:5 } },
      { l:'② 꼬리표 아래 적힌 잡는 법을 옮겨 적는다.', k:'fix', dc:14,
        ok:`꼬리표 아래쪽에 작게 적혀 있다. 잡은 법이다. 「불로」 「소금으로」 「등 뒤에서」.<br><br>정리하는 이는 친절했다. 잡는 법까지 남겼다.<br>일행에게 하나씩 외우게 했다. 이 방에서 나올 것들의 목록이다.<br><br>나오면 이쪽도 안다.`,
        ng:`적는 동안 병 하나가 흔들렸다. 안에 뜬 것이 눈을 떴다.<br><br>유리를 두드린다. 꼬리표가 떨어졌다.<br>이름 없는 병이 둘이 되었다. 다들 서둘러 나왔다. 서두르다 다쳤다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-10, mind:-8 } }
    ] },

  { at:'C', t:'방 — 벗어 둔 허물',
    x:`통로 한가운데 허물이 벗겨져 있다. 사람보다 길다.<br><br>
      마디가 스물넷이다. 다리 자리도 마디마다 둘씩.<br>
      책에서 읽었다. 벗을 때마다 마디가 하나씩 는다. 벗은 직후엔 껍질이 무르다.<br><br>
      허물 안쪽이 아직 젖어 있다.`,
    o:[
      { l:'① 허물을 재서 지금의 크기와 굳기를 따진다.', k:'gaze', dc:15,
        ok:`손 뼘으로 마디를 쟀다. 스물넷. 벗었으니 지금은 스물다섯이다. 한 마디만큼 길어졌다.<br><br>안쪽이 젖어 있다. 벗은 지 한 시간이 안 됐다. 새 껍질은 아직 손톱으로 눌러도 들어간다. 한나절 뒤면 창도 튕긴다.<br>일행을 재촉했다. 지금 잡자고. 젖은 자국을 따라가니 벽에 붙어 떨고 있는 것이 있다. 창이 들어갔다.<br><br>남은 것 하나로 지금 있는 것을 셈하는 법. 껍질 하나에서 시간과 크기와 굳기가 한꺼번에 나왔다. 셈이 한 단 늘었다.`,
        ng:`재다가 허물이 바스러졌다. 마디를 다 못 셌다.<br><br>짐작으로 지금 크기를 말했다. 틀렸다. 훨씬 컸다.<br>쫓아갔다가 쫓겨 왔다. 다들 긁혔다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-6 }, wake:1 },
      { l:'② 허물을 덮어써 냄새를 감춘다.', k:'hide', dc:14,
        ok:`허물 조각을 등에 걸쳤다. 비리다.<br><br>통로 저쪽에서 다리 많은 것들이 지나갔다. 이쪽을 더듬이로 쓸었다. 같은 냄새다.<br>지나갔다.<br><br>허물은 벗은 것에게만 쓸모없다.`,
        ng:`걸치는데 허물 안쪽에 아직 무언가 남았다.<br><br>작은 것들이다. 허물에서 이쪽 목으로 기어 나온다.<br>털어 내느라 한참 춤을 췄다. 목덜미가 붉게 부었다.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-10, spirit:-8 } }
    ] },

  { at:'C', t:'방 — 쌓인 뼈',
    x:`구석에 뼈가 쌓여 있다. 아무렇게나 쌓은 게 아니다. 큰 것 아래, 작은 것 위.<br><br>
      뼈에 이 자국이 있다. 큰 뼈에는 작은 이, 작은 뼈에는 큰 이.<br>
      누가 무엇을 먹었는지가 뼈에 다 적혀 있다. 이쪽은 그걸 읽을 줄 안다.<br><br>
      맨 위 뼈가 제일 새것이다. 아직 하얗지 않다.`,
    o:[
      { l:'① 이 자국으로 먹은 것을 가린다.', k:'gaze', dc:14,
        ok:`큰 이 자국은 한 가지뿐이다. 다 같은 이다. 앞니가 하나 깨졌다.<br><br>이 방의 것들을 하나가 다 먹었다. 그것은 먹고 나면 자리를 옮기지 않는다. 뼈를 쌓는 데서 잔다.<br>잠은 배부를 때 깊다. 맨 위 뼈가 새것이다. 지금 배부르다.<br><br>일행이 숨을 죽이고 뼈 무더기 뒤로 돌았다. 깨진 앞니가 코를 골며 벌어져 있었다. 그 입은 다시 다물리지 않았다.`,
        ng:`이 자국을 세다 보니 한 가지가 아니다. 둘이다.<br><br>둘째 이는 아직 이 방에 없다. 뼈를 가져다 놓는 쪽이다.<br>뒤에서 뼈 하나가 툭 떨어졌다. 맨 위에. 새것이.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-12, spirit:-8 } },
      { l:'② 맨 아래 뼈들 사이에서 쓸 것을 고른다.', k:'luck', dc:13,
        ok:`맨 아래는 오래된 뼈들이다. 그 사이에 가죽 주머니가 있다. 먹힌 사냥꾼 것이다.<br><br>안에 약초가 말라 있다. 상처에 대는 것이다.<br>쓸 틈이 없었다.<br><br>이쪽이 쓴다.`,
        ng:`맨 아래를 들추자 무더기가 기울었다.<br><br>뼈가 쏟아졌다. 소리가 크다.<br>저쪽 어둠에서 깨는 소리가 났다. 다들 뛰었다. 넘어진 사람이 있었다.`,
        win:{ exp:12, item:'약초 뭉치' }, lose:{ hp:-10, mind:-6 } },
      { l:'③ 새 뼈에 붙은 고기를 따져 본다.', k:'heal', dc:14,
        ok:`새 뼈에 고기가 남았다. 먹다 만 것이다. 무엇을 먹다 말았나.<br><br>결이 굵고 기름이 없다. 짐승이다. 이 방 것이 아니라 바깥 짐승이다. 끌고 들어왔다.<br>자른 단면을 불에 그을렸다. 냄새가 바르다.<br><br>먹어도 된다. 아마.`,
        ng:`결을 보느라 코를 너무 가까이 댔다.<br><br>냄새가 머리에 들어왔다. 그 짐승이 무엇을 보며 죽었는지 냄새로 안다.<br>한참 토할 것 같았다.`,
        win:{ exp:12, item:'짐승 고기' }, lose:{ mind:-10, spirit:-6 } }
    ] },

  { at:'C', t:'방 — 자르면 느는 것',
    x:`바닥을 기는 것이 있다. 길고 무르다. 팔뚝만 하다.<br><br>
      일행 하나가 칼로 내리쳤다. 두 토막이 되었다. 두 토막이 따로 기어 왔다.<br>
      또 쳤다. 넷이 되었다.<br><br>
      책에서 이런 것을 읽었다. 물가에 사는 납작한 벌레다. 자르면 는다. 자르는 방향 하나만 빼고.`,
    o:[
      { l:'① 자를 방향을 따져 일행에게 알린다.', k:'gaze', dc:15,
        ok:`그 벌레는 가로로 자르면 둘이 된다. 세로로 자르면 머리가 둘인 하나가 된다. 머리가 둘인 것은 제 머리끼리 싸운다.<br><br>「세로로.」 일행이 칼을 돌려 쥐었다. 넷 중 하나를 길게 갈랐다. 갈라진 것이 제 몸을 물었다.<br>넷이 다 그렇게 되었다. 서로 물고 엉켜 굳었다.<br><br>오래전에 읽은 한 줄이 칼 방향이 되었다. 책의 벌레와 눈앞의 것이 달라도 다른 만큼만 고쳐 쓰면 된다. 그 고쳐 쓰는 셈이 빨라졌다.`,
        ng:`세로로 하라고 했다. 이것은 책의 벌레와 결이 반대였다.<br><br>세로로 갈린 것이 둘이 되었다. 머리가 둘씩.<br>여덟이 된 것들이 발목으로 기어올랐다. 떼어 내느라 다들 지쳤다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-14, mind:-8 }, wake:1 },
      { l:'② 자르지 말고 불로 몰아낸다.', k:'fix', dc:14,
        ok:`등불 기름을 바닥에 한 줄 부었다. 불을 붙였다.<br><br>무른 것들은 불을 못 넘는다. 넷이 한쪽에 몰렸다.<br>몰린 것들을 소금으로 덮었다. 오그라들었다.<br><br>자르지 않으면 늘지 않는다. 간단한 셈이다.`,
        ng:`기름이 모자랐다. 불줄이 중간에 끊겼다.<br><br>끊긴 틈으로 넷이 다 넘어왔다.<br>밟아도 안 죽는다. 밟을수록 는다. 다들 물러났다.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-10, mind:-8 } }
    ] },

  { at:'C', t:'방 — 물린 자국',
    x:`일행 하나가 물렸다. 정강이다. 무엇에 물렸는지 아무도 못 봤다.<br><br>
      자국이 남았다. 반달 모양 둘. 이가 위에 열넷, 아래에 열둘.<br>
      위아래 이 개수가 다른 짐승은 흔하지 않다. 그런 표를 본 적이 있다.<br><br>
      물린 사람의 다리가 차가워지기 시작한다.`,
    o:[
      { l:'① 이 자국을 표에 맞춰 무엇인지 가린다.', k:'gaze', dc:14,
        ok:`위 열넷, 아래 열둘. 송곳니 자리가 비었다. 독이 있는 것은 송곳니가 길다. 이건 없다.<br><br>독이 아니다. 차가운 건 겁이다. 이 짐승은 물고 나서 숨는다. 물린 쪽이 겁먹어 쓰러지면 돌아온다.<br>물린 사람에게 그렇게 말해 주었다. 그 사람 다리에 피가 돌았다.<br><br>천장 어둠에서 무언가 기다리다 실망한 소리가 났다. 일행 창이 그 소리 쪽으로 올라갔다.`,
        ng:`표가 기억나지 않는다. 비슷한 것이 셋이다. 하나는 독이 있다.<br><br>독이라고 말했다. 물린 사람이 쓰러졌다. 겁이 독보다 빨랐다.<br>천장에서 무언가 내려왔다. 쫓는 데 다들 다쳤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-8 } },
      { l:'② 상처를 씻고 약초로 싼다.', k:'heal', dc:13,
        ok:`물로 씻었다. 자국 둘레를 눌러 나쁜 피를 뺐다.<br><br>약초를 씹어 붙이고 천으로 감았다.<br>물린 사람이 고맙다고 했다. 다리가 따뜻해졌다.<br><br>무엇에 물렸든 씻는 건 같다.`,
        ng:`씻는데 자국이 하나 더 생긴다. 옆에. 같은 모양으로.<br><br>이쪽 손등에도.<br>무언가 아직 가까이 있다. 다들 등을 맞대고 앉아 밤을 새웠다.`,
        win:{ exp:14, hp:8 }, lose:{ hp:-10, spirit:-8 } },
      { l:'③ 물린 사람 곁에서 천장을 지켜본다.', k:'steady', dc:15,
        ok:`물린 사람 옆에 앉았다. 고개를 들고 천장만 봤다.<br><br>오래. 목이 아파도.<br>어둠 한 자리가 조금 내려왔다. 다시 올라갔다. 이쪽이 보고 있는 걸 알았다.<br><br>그것은 끝내 안 내려왔다. 보고 있는 동안은.`,
        ng:`보다가 눈이 감겼다. 잠깐.<br><br>뜨니 물린 사람 다리에 자국이 하나 늘었다.<br>이쪽은 아무것도 못 봤다. 그게 제일 싫다.`,
        win:{ exp:14, spirit:6 }, lose:{ mind:-10, spirit:-8 } }
    ] },

  { at:'C', t:'방 — 책에 없는 것',
    x:`어둠에서 그것이 나왔다. 처음 보는 모양이다.<br><br>
      아는 짐승을 다 떠올려 봤다. 아는 그림을 다 넘겨 봤다. 없다.<br>
      읽은 것이 하나도 소용없는 건 학자에게 처음 있는 일이다.<br><br>
      일행이 이쪽을 본다. 무엇이냐고.`,
    o:[
      { l:'① 처음부터 보고 적는다.', k:'gaze', dc:16,
        ok:`모르는 것은 적으면 된다. 첫 줄부터.<br><br>다리 수, 걷는 박자, 숨 쉬는 자리, 빛을 보면 하는 짓. 소리 내어 말하며 적었다. 일행이 들었다. 그것이 숨 쉴 때마다 옆구리 한 자리가 얇아진다. 적은 줄 가운데 그 줄이 제일 중요했다.<br>창이 그 자리에 들어갔다. 쓰러졌다.<br><br>적은 것을 다시 읽었다. 어느 책에도 없던 한 장이다. 이제는 있다. 읽기만 하던 손이 처음으로 남이 읽을 것을 썼다.`,
        ng:`적으려는데 손이 떨린다. 아는 말로 적을 수가 없다.<br><br>다리 수를 세다가 놓쳤다. 셀 때마다 다르다.<br>그것이 다가오는 걸 늦게 봤다. 일행이 이쪽을 끌어냈다.`,
        win:{ exp:24, dream:4 }, lose:{ hp:-14, mind:-10 }, wake:1 },
      { l:'② 아는 것 가운데 제일 가까운 것으로 짐작한다.', k:'sense', dc:14,
        ok:`다리가 많고 낮게 긴다. 아는 것 중에는 가재가 제일 가깝다.<br><br>가재는 꼬리로 뒤로 뛴다. 「뒤를 막아.」 일행 둘이 뒤로 돌았다.<br>그것이 뒤로 뛰었다. 막혔다.<br><br>틀린 책도 반은 맞는다.`,
        ng:`가재라고 했다. 그것은 앞으로 뛰었다.<br><br>앞에 이쪽이 있었다.<br>집게 같은 것에 팔이 집혔다. 일행이 떼어 냈다. 팔이 저리다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-6 } }
    ] }
]);

// ── 주술사 (마력)
kJob('hexer', 'C', [
  { at:'C1', t:'도축장 — 힘줄 매듭',
    x:`갈고리 레일 기둥마다 무언가 감겨 있다. 말린 힘줄이다. 매듭을 지었다.<br><br>
      주술사는 매듭을 읽는다. 이건 묶는 매듭이 아니다. 되돌리는 매듭이다. 풀린 것을 처음으로 돌려놓는다.<br>
      갈고리에 걸린 고기가 잘린 자리마다 다시 찬다. 매듭 하나를 지날 때마다.<br><br>
      레일 저쪽에서 칼 가는 소리가 난다. 줄은 멈추지 않는다.`,
    o:[
      { l:'① 매듭이 무엇을 되돌리는지 읽는다.', k:'gaze', dc:14,
        ok:`매듭 안쪽에 털이 한 가닥씩 끼어 있다. 소털이다.<br><br>되돌리는 건 고기가 아니다. 소다. 매듭마다 소 한 마리가 묶여서 다시, 또다시 잡힌다. 고기가 자라는 건 그 때문이다.<br>털 박힌 매듭만 골라 일행이 칼로 끊었다. 그 기둥의 고기는 더 자라지 않았다. 자르면 잘린 그대로였다.<br><br>그 갈고리 아래로 지나갔다. 칼 가는 소리가 멈췄다. 저쪽에서 무엇이 귀를 기울인다.`,
        ng:`읽다가 매듭 하나가 이쪽 손가락을 감았다.<br><br>힘줄이 조인다. 마른 것이 젖은 것처럼.<br>풀어내는 데 손톱이 하나 들렸다. 그 손톱이 매듭 안으로 빨려 들어갔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-8 } },
      { l:'② 마력으로 매듭을 거꾸로 맨다.', k:'gaze', dc:15, cost:{ mana:20 },
        ok:`매듭 하나를 쥐고 마력을 흘렸다. 풀지 않았다. 감긴 방향만 뒤집었다.<br><br>되돌리는 매듭이 거꾸로 돌면 앞당기는 매듭이 된다. 갈고리에 걸린 고기가 그 자리에서 마르고 검어졌다. 몇 해가 한꺼번에 지나간 것처럼.<br>레일 저쪽에서 칼 가는 소리가 끊기고 무거운 것이 비틀거렸다. 그것도 이 매듭에 묶여 있었다.<br><br>남이 맨 매듭을 풀지 않고 뒤집어 쓰는 법. 손가락 끝이 그 방향을 기억했다. 다음 매듭은 더 빨리 뒤집힐 것이다.`,
        ng:`뒤집는데 마력이 매듭에 먹혔다. 매듭이 한 바퀴 더 감겼다.<br><br>되돌리는 힘이 이쪽에 왔다. 아까 긁힌 상처가 다시 벌어졌다. 처음처럼.<br>아물었던 자리가 다 벌어지는 데 숨 한 번이 걸렸다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-8 }, wake:1 }
    ] },

  { at:'C1', t:'도축장 — 같은 무게',
    x:`작업장 한가운데 큰 저울이 있다. 고기를 올리는 쇠판이다.<br><br>
      바늘이 한 자리에 붙어 있다. 아무것도 안 올렸는데 무게가 있다.<br>
      저울은 오래된 저주 도구다. 무엇이 무엇과 같아야 한다고 정하니까.<br><br>
      쇠판 밑에 붉은 실로 글씨가 꿰매져 있다. 「잘린 만큼 돌아올 것」.`,
    o:[
      { l:'① 실의 땀을 세어 저울이 무엇을 재는지 읽는다.', k:'gaze', dc:14,
        ok:`땀이 마흔이다. 하루에 잡는 소가 마흔이라고 벽에 적혀 있었다.<br><br>저울은 고기를 재는 게 아니다. 도축장 전체를 잰다. 마흔 마리 무게가 늘 같아야 한다. 그래서 잘린 고기가 돌아온다.<br>쇠판에 일행의 짐을 올렸다. 무게가 넘쳤다. 바늘이 떨었다.<br><br>그동안 갈고리의 고기가 하나도 안 자랐다. 저울이 셈을 다시 하느라 바빴다.`,
        ng:`세다가 땀 하나가 이쪽 손가락을 찔렀다.<br><br>피 한 방울이 쇠판에 떨어졌다. 바늘이 그만큼 움직였다.<br>이쪽 무게가 저울에 올라갔다. 몸이 무겁다. 한참을 끌고 걸었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-10, spirit:-10 } },
      { l:'② 소금을 쇠판에 쏟는다.', k:'luck', dc:14,
        ok:`소금 주머니를 털어 쇠판에 쏟았다.<br><br>저울이 소금 무게를 어떻게 쳐야 할지 모른다. 바늘이 미친 듯 돌았다.<br>그사이 실 땀 몇이 저절로 풀렸다.<br><br>소금은 셈을 흐린다. 늘 소금을 들고 다니는 이유다.`,
        ng:`쏟은 소금이 쇠판에 닿자 녹았다. 물처럼.<br><br>소금이 다 녹는 동안 바늘은 꿈쩍도 안 했다.<br>저울은 소금 무게까지 쳐서 돌려받기로 했다. 갈고리 고기가 더 두꺼워졌다. 그걸 피하느라 다쳤다.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-12, mind:-6 } },
      { l:'③ 마력으로 저울 바늘을 붙들어 맨다.', k:'fix', dc:15, cost:{ mana:18 },
        ok:`바늘 끝에 손가락을 대고 마력을 감았다. 움직이지 말라고.<br><br>바늘이 굳었다. 저울이 셈을 못 한다. 셈 못 하는 저울은 아무것도 돌려주지 못한다.<br>일행이 그사이 갈고리 고기 사이에 숨어 있던 것을 찾아 끝냈다. 다시 붙지 않았다.<br><br>바늘은 지금도 그 자리다.`,
        ng:`바늘이 마력을 튕겨 냈다. 손가락이 저울판에 붙었다.<br><br>저울이 이쪽을 재기 시작했다. 바늘이 한 칸씩 기운다.<br>떼어 내는 데 살갗이 한 겹 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-14, spirit:-8 } }
    ] },

  { at:'C1', t:'도축장 — 백정의 앞치마',
    x:`벽 못에 앞치마가 걸려 있다. 크다. 사람 둘을 감쌀 만하다.<br><br>
      가죽이다. 주머니 둘레에 부적이 꿰매져 있다. 서툰 글씨인데 힘이 있다.<br>
      알 만하다. 앞치마 주인이 이걸 두르고 있는 동안은 칼이 안 들어간다.<br><br>
      레일 저쪽에서 무거운 발소리가 다가온다. 앞치마를 가지러.`,
    o:[
      { l:'① 부적 위에 거꾸로 된 한 획을 꿰매 넣는다.', k:'gaze', dc:15,
        doom:{ title:'앞치마 끈', what:'앞치마 끈에 감겨 끌려갑니다', dc:15, sec:55,
          text:`실을 꺼내 부적 한가운데에 한 획을 꿰맸다. 바늘이 가죽을 뚫는다. 세 땀.<br><br>넷째 땀에서 발소리가 문 앞에 왔다. 손이 앞치마를 걷어 갔다. 이쪽 손목에 감긴 끈째.<br>그것이 앞치마를 두른다. 끈을 등 뒤에서 맨다. 이쪽이 그 끈 안에 있다.<br><br>그것이 레일 쪽으로 걸어간다. 이쪽을 허리에 매단 채.`,
          dieText:`앞치마가 다시 벽 못에 걸렸다.<br><br>주머니 둘레 부적이 하나 늘었다. 서툰 글씨다. 바늘땀이 셋 반이다.<br>힘은 있다.` },
        ok:`세 땀 만에 꿰매고 실을 끊었다. 발소리가 문 앞에 오기 전에 물러났다.<br><br>그것이 들어와 앞치마를 둘렀다. 그 앞치마는 이제 칼을 막지 않는다. 거꾸로 된 한 획이 부적의 뜻을 뒤집었다.<br>일행의 칼이 앞치마째 들어갔다. 그것이 처음으로 소리를 냈다.<br><br>바늘은 챙겼다. 쓸 데가 또 있다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 마력을 먹여 앞치마를 무겁게 한다.', k:'fix', dc:14, cost:{ mana:18 },
        ok:`앞치마에 손바닥을 대고 마력을 밀어 넣었다. 무게를 담았다. 돌 한 짐만큼.<br><br>그것이 들어와 앞치마를 걸쳤다. 무릎이 꺾였다. 한 걸음마다 바닥이 운다.<br>느려진 것은 사냥감이다. 일행이 둘러쌌다.<br><br>앞치마는 끝까지 벗지 않았다. 그게 그것의 버릇이었다.`,
        ng:`무게를 담는데 앞치마가 마력을 마셨다. 끝도 없이.<br><br>손을 떼었을 때 팔에 힘이 없다. 앞치마는 그대로 가볍다.<br>그것이 들어와 둘러 입고 이쪽을 봤다. 다들 숨느라 다쳤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-10 } }
    ] },

  { at:'C2', t:'인형 공방 — 천장의 실',
    x:`공방 천장에서 실이 늘어져 있다. 수백 가닥. 끝마다 사기 인형이 매달렸다.<br><br>
      실은 무명이 아니다. 머리카락을 꼬았다. 주술사는 그걸 손끝으로 안다.<br>
      인형들이 실 끝에서 고개를 돌린다. 이가 맞부딪는 소리.<br><br>
      실 하나가 다른 것보다 굵다. 천장 구멍으로 곧장 올라간다.`,
    o:[
      { l:'① 굵은 실의 꼬임을 읽는다.', k:'gaze', dc:14,
        ok:`굵은 실은 다섯 가닥을 꼬았다. 인형 다섯이 그 한 줄에 매여 있다.<br><br>꼬임 방향이 반대인 자리가 하나 있다. 거기서 실이 바뀐다. 위층 손가락이 잡는 곳이다.<br>일행에게 그 자리만 잘라 달라고 했다. 잘랐다. 인형 다섯이 한꺼번에 바닥에 떨어져 깨졌다.<br><br>천장 위에서 무언가 손을 털었다.`,
        ng:`꼬임을 따라가다 눈이 실에 붙었다. 끝까지 따라가고 싶다.<br><br>고개가 저절로 천장 구멍 쪽으로 들렸다. 거기서 누가 내려다본다.<br>일행이 어깨를 잡아 돌렸다. 목이 한참 뻣뻣했다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-10, spirit:-8 } },
      { l:'② 마력으로 실 한 가닥을 이쪽 손가락에 옮겨 감는다.', k:'gaze', dc:15, cost:{ mana:20 },
        ok:`인형 하나의 실을 쥐었다. 마력을 흘려 실 끝을 이쪽 손가락에 감았다. 위층 손가락 대신.<br><br>인형이 이쪽 손가락을 따라 움직였다. 고개를 돌려 옆 인형의 목을 물었다. 사기가 깨졌다. 또 하나.<br>셋을 깨고 나서 실을 놓았다. 손가락 마디가 다 저렸다.<br><br>남의 실을 빼앗아 쥐는 감. 실 하나를 쥐어 봤으니 다음엔 둘을 쥘 것이다. 손가락이 벌써 그 모양으로 굽는다.`,
        ng:`감는 사이 위층에서 실을 당겼다. 이쪽 손가락째.<br><br>팔이 천장으로 들렸다. 발끝으로 섰다. 실이 손가락 마디를 파고든다.<br>일행이 실을 잘랐다. 손가락에 머리카락 자국이 둥글게 남았다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-14, spirit:-8 }, wake:1 }
    ] },

  { at:'C2', t:'인형 공방 — 이를 박은 까닭',
    x:`작업대에 만들다 만 인형 머리가 있다. 입 안에 이가 반쯤 박혔다.<br><br>
      이 뿌리마다 종이가 말려 있다. 아주 작게. 글씨가 있다.<br>
      그 글씨는 안다. 먹는 주술이다. 먹어야 움직이는 것에게 거는 것.<br><br>
      선반의 인형들이 입을 오물거린다. 배가 고프다.`,
    o:[
      { l:'① 종이 글씨를 끝까지 읽는다.', k:'gaze', dc:14,
        ok:`「먹은 만큼 걷는다. 굶으면 굳는다.」 그 밑에 한 줄 더. 「짠 것은 먹지 말 것」.<br><br>만든 이가 저 혼자 알려고 적은 줄이다. 짠 것을 먹으면 이 주술은 저절로 마른다.<br>소금을 한 줌씩 쥐고 인형 입에 밀어 넣었다. 셋째 인형부터 입 안에서 쩍 소리가 났다. 사기가 안에서부터 갈라졌다.<br><br>오물거리던 입들이 다물렸다.`,
        ng:`종이를 펴다 찢어졌다. 반만 남았다.<br><br>「먹은 만큼 걷는다.」 거기까지다.<br>인형 머리가 작업대 위에서 이쪽 손가락을 물었다. 박다 만 이로.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-6 } },
      { l:'② 먹을 것을 멀리 던져 인형들을 몰아낸다.', k:'luck', dc:13,
        ok:`말린 것 한 조각을 작업장 저쪽 구석으로 던졌다.<br><br>인형들이 실을 끌고 그쪽으로 몰렸다. 서로 밀치며. 사기끼리 부딪쳐 깨진다.<br>그사이 작업대 밑을 뒤졌다. 공방 사람들이 먹던 꿀단지가 있다.<br><br>먹는 주술은 먹는 것으로 다룬다.`,
        ng:`던진 것이 실에 걸려 바로 앞에 떨어졌다.<br><br>인형들이 전부 이쪽 발밑으로 몰렸다. 발목에 이가 박혔다.<br>떼어 내는 데 다들 손이 갔다.`,
        win:{ exp:12, item:'꿀 한 줌' }, lose:{ hp:-14, mind:-4 } }
    ] },

  { at:'C2', t:'인형 공방 — 짚 인형 하나',
    x:`사기 인형들 틈에 짚 인형이 하나 앉아 있다.<br><br>
      이 공방 물건이 아니다. 위층 인형사가 연습한 것이다. 짚은 사기보다 다루기 쉽다.<br>
      짚 인형 머리에 감긴 머리카락이 일행 하나의 것이다. 색도 길이도 같다.<br><br>
      그 일행이 아까부터 자꾸 위층 계단 쪽을 본다.`,
    o:[
      { l:'① 머리카락을 풀어내고 짚 인형을 거꾸로 맨다.', k:'gaze', dc:15,
        ok:`머리카락을 한 올씩 풀었다. 일행이 계단에서 눈을 뗐다.<br><br>빈 짚 인형에 이쪽 방식으로 매듭을 새로 지었다. 위층으로 이어진 실 끝을 짚 인형 목에 감았다. 그리고 손톱으로 가슴을 눌렀다.<br>위층에서 무언가 넘어지는 소리가 났다. 천장 실이 한꺼번에 출렁였다.<br><br>남이 만든 인형으로 만든 이를 친다. 처음 해 보는 게 아닌데, 이번엔 손이 먼저 알았다. 짚을 쥐는 순간 어디를 누를지 안다.`,
        ng:`풀다가 머리카락 한 올이 끊겼다.<br><br>일행이 비명을 질렀다. 머리 한쪽이 화끈하다고 한다.<br>짚 인형이 고개를 들었다. 계단 쪽으로 기어갔다. 붙잡는 데 다 같이 애썼다.`,
        win:{ exp:22, dream:3, spirit:5 }, lose:{ hp:-10, spirit:-12 }, wake:1 },
      { l:'② 짚 인형을 등불에 태운다.', k:'break', dc:14,
        ok:`등불 뚜껑을 열고 짚 인형을 넣었다.<br><br>타는 동안 일행이 머리를 감쌌다. 그리고 놓았다. 가볍다고 했다.<br>위층에서 짧은 기침 소리.<br><br>타 버린 짚은 다시 못 쓴다. 아무도.`,
        ng:`짚이 젖어 안 탄다. 연기만 난다.<br><br>연기가 일행 쪽으로 간다. 그 사람이 콜록거리다 주저앉았다.<br>연기는 계단 쪽으로 올라갔다. 위층에서 숨을 들이쉬는 소리.`,
        win:{ exp:14, spirit:6 }, lose:{ hp:-8, spirit:-10 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 거꾸로 건 축복',
    x:`거꾸로 매달린 제단 위에 글씨가 새겨져 있다. 축복하는 글이다.<br><br>
      축복도 주문이다. 다만 거꾸로 걸린 축복은 거꾸로 읽힌다.<br>
      「오래 머물라」가 거꾸로 서면 「내려오라」가 된다.<br><br>
      머리 위 먼 바닥에서 의자 하나가 떨어졌다. 아니, 이쪽으로 올라왔다.`,
    o:[
      { l:'① 획 하나를 보태 거꾸로 선 뜻을 바로 세운다.', k:'gaze', dc:15,
        ok:`숯으로 마지막 글자 끝에 한 획을 붙였다. 거꾸로 읽어도 같은 뜻이 되도록.<br><br>「머물라」가 거꾸로 서도 「머물라」다. 머리 위 의자들이 덜컥 멈췄다. 떨어지던 것이 제자리에 섰다.<br>종 같은 것들도 흔들림을 멈췄다. 그것들도 이 축복 밑에 있었다.<br><br>멈춘 사이 건넜다. 글자 하나가 주술 하나다.`,
        ng:`획을 붙이다 숯이 미끄러졌다. 획이 길어졌다.<br><br>뜻이 엉뚱하게 바뀌었다. 성당이 그 말을 들었다.<br>머리 위에서 무언가 이쪽 정수리를 향해 떨어졌다. 비켰는데 어깨를 맞았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-14, spirit:-8 } },
      { l:'② 마력으로 축복을 일행에게 돌려 건다.', k:'bond', dc:14, cost:{ mana:18 },
        ok:`제단 글씨에 손을 대고 마력을 흘렸다. 거꾸로 선 축복의 끝을 일행 다섯에게 감았다.<br><br>「오래 머물라」. 성당이 아니라 일행에게. 다섯 발이 천장 늑골에 붙었다. 미끄러질 수가 없다.<br>그렇게 가장 기운 자리를 건넜다.<br><br>건너자 풀었다. 축복도 오래 걸어 두면 저주가 된다.`,
        ng:`감는 끝이 다섯이 아니라 넷에만 갔다.<br><br>남은 하나가 미끄러졌다. 늑골 사이로.<br>모두 엎드려 붙잡았다. 끌어 올리는 데 다 지쳤다.`,
        win:{ exp:18, spirit:6 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 종의 혀',
    x:`종 같은 것 하나가 늑골 끝에 매달려 있다. 사람 셋 크기다.<br><br>
      안에 혀가 있다. 종의 추가 아니다. 진짜 혀다. 젖어 있다. 그것이 흔들리면 성당이 운다.<br>
      오래된 주술이 있다. 혀를 묶으면 말을 못 한다.<br><br>
      종이 숨을 들이쉰다. 다음 울음이 온다.`,
    o:[
      { l:'① 종 안으로 손을 넣어 혀에 매듭을 짓는다.', k:'gaze', dc:15,
        doom:{ title:'종 안', what:'종 안으로 빨려 들어갑니다', dc:15, sec:55,
          text:`팔을 넣었다. 혀가 미끄럽다. 실을 한 바퀴 감았다.<br><br>매듭을 조이려는데 종이 숨을 들이쉬었다. 팔이, 어깨가, 머리가 안으로 들어간다.<br>안은 따뜻하다. 혀가 이쪽 얼굴을 쓸어 맛을 본다.<br><br>밖에서 일행 목소리가 멀다. 종이 울기 시작한다. 이번엔 이쪽 목소리로.`,
          dieText:`성당이 운다. 한동안은 사람 목소리로.<br><br>종 하나가 다른 종들보다 조금 무겁게 흔들린다.<br>그 혀에는 실이 한 바퀴 감겨 있다. 매듭은 없다.` },
        ok:`혀가 밖으로 나온 틈을 기다렸다. 숨 들이쉬기 직전에.<br><br>실을 두 번 감고 바로 조였다. 매듭에 이쪽 침을 묻혔다. 묶인 혀는 묶은 쪽 말을 듣는다.<br>종이 숨을 들이쉬었다. 울지 못했다. 흔들리기만 했다. 흔들리는 종 밑으로 일행이 창을 넣었다.<br><br>성당이 한 군데 조용해졌다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 일행 셋이 종의 테를 붙잡아 흔들림을 멎게 한다.', k:'fix', dc:14,
        ok:`셋이 종 테를 붙잡고 다리를 늑골에 걸었다. 하나, 둘, 셋에 버텼다.<br><br>종이 흔들리지 못하면 혀가 닿을 데가 없다. 울음이 목에 걸렸다.<br>종이 숨을 몇 번 들이쉬다 지쳤다.<br><br>그 틈에 지나갔다. 손바닥에 종의 체온이 남았다.`,
        ng:`버티는데 종이 울었다. 테를 쥔 손으로 울음이 들어왔다.<br><br>셋 다 놓쳤다. 귀에서 쇠 맛이 났다.<br>한참 아무것도 안 들렸다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-10, mind:-10 } },
      { l:'③ 마력을 실에 먹여 멀리서 혀를 감는다.', k:'gaze', dc:15, cost:{ mana:22 },
        ok:`실 끝에 마력을 먹였다. 실이 뱀처럼 곧게 섰다.<br><br>종 입으로 실을 밀어 넣었다. 혀를 찾아 세 번 감았다. 멀리서 조였다.<br>종이 울려다 말았다. 혀가 실을 씹다 지쳐 늘어졌다.<br><br>손을 대지 않고 묶었다. 마력이 많이 빠졌다.`,
        ng:`실이 혀에 닿기 전에 혀가 실을 핥았다.<br><br>마력이 실을 타고 거꾸로 왔다. 입 안에 쇠 맛이 고였다.<br>한동안 말이 안 나왔다. 혀가 굳었다.`,
        win:{ exp:20, dream:3 }, lose:{ mind:-12, spirit:-8 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 이름을 부르는 노래',
    x:`머리 위 성가대석에서 노래가 쏟아진다. 입이 너무 많다.<br><br>
      가사가 들린다. 이름이다. 하나씩 부른다. 처음 듣는 이름들 사이에 일행 이름이 섞인다.<br>
      노래도 주문이다. 부른 이름을 끌어올리는 노래다.<br><br>
      일행 하나의 발이 늑골에서 조금 떴다.`,
    o:[
      { l:'① 노래의 매듭 자리에 틀린 음을 끼운다.', k:'gaze', dc:15,
        ok:`주문 노래에는 매듭이 있다. 같은 소리가 세 번 겹치는 자리.<br><br>그 자리를 기다렸다. 셋째 겹에 이쪽이 소리를 냈다. 반음 낮게.<br>노래가 꼬였다. 입들이 서로 다른 음을 찾느라 엉켰다. 뜬 발이 늑골에 다시 닿았다.<br><br>주문은 틀리게 따라 부르는 것으로도 흐트러진다. 일행이 이쪽 노래를 처음으로 칭찬했다.`,
        ng:`매듭 자리를 기다리다 박자를 놓쳤다.<br><br>엉뚱한 데서 낸 소리가 노래에 섞여 들어갔다. 이쪽 이름이 가사가 되었다.<br>이쪽 발이 떴다. 일행이 허리띠를 잡았다. 한참 매달려 있었다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-10, spirit:-10 } },
      { l:'② 일행 이름을 서로 바꿔 부르게 한다.', k:'bond', dc:14,
        ok:`다들 옆 사람 이름으로 불렀다. 큰 소리로. 바꿔서.<br><br>노래가 부르는 이름과 발밑의 사람이 안 맞는다. 끌어올릴 줄을 못 찾는다.<br>뜬 발이 내려왔다.<br><br>이름은 주인이 헷갈리면 줄이 엉킨다.`,
        ng:`바꿔 부르다 누가 제 이름에 대답했다.<br><br>노래가 그걸 잡았다. 그 사람이 허리까지 떴다.<br>끌어내리는 데 다들 팔이 빠질 뻔했다.`,
        win:{ exp:16, spirit:6 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C4', t:'포자 온실 — 정원사의 손톱',
    x:`정원사 옷을 입은 것들이 화단 사이를 걷는다. 걸음이 같다.<br><br>
      소매 끝으로 손이 나왔다. 손톱이 길게 자랐다. 사람 손톱이다. 그 밑에 허연 것이 차 있다.<br>
      주술사에게 손톱과 머리카락은 이름보다 정직하다. 몸의 일부니까.<br><br>
      화단 가장자리에 손톱 조각이 떨어져 있다. 하나가 버섯 줄기에 긁혀 떨어졌다.`,
    o:[
      { l:'① 손톱 조각으로 그것에게 매듭을 건다.', k:'gaze', dc:15,
        ok:`손톱 조각을 주웠다. 실에 감아 매듭을 셋 지었다. 마지막 매듭에 소금을 쳤다.<br><br>정원사 옷 하나가 걸음을 멈췄다. 같은 걸음 속에서 혼자 박자를 잃었다. 손가락부터 굳어 갔다.<br>일행이 굳은 것을 넘어뜨렸다. 옷 안에서 버섯 대가 부러지는 소리가 났다.<br><br>몸의 조각 하나로 몸 전체를 붙드는 법. 사람에게만 되는 줄 알았다. 사람이 아니게 된 것에게도 된다. 매듭 셋을 둘로 줄여도 되겠다고 손이 먼저 생각했다.`,
        ng:`매듭을 짓는데 손톱 조각 밑의 허연 것이 실을 타고 왔다.<br><br>이쪽 손가락으로. 손톱 밑으로.<br>손을 털고 또 털었다. 손톱 밑이 오래 가려웠다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-10, spirit:-10 }, wake:1 },
      { l:'② 걸음 박자를 보고 그 사이로 지난다.', k:'evade', dc:14,
        ok:`같은 걸음이면 같은 틈이 난다.<br><br>넷을 세고 하나에 지났다. 넷을 세고 하나에.<br>정원사 옷들이 이쪽을 모른 채 계속 걸었다.<br><br>걸음이 같다는 건 하나가 다 부리고 있다는 뜻이다. 저 안쪽 어딘가에서.`,
        ng:`넷째 박에 하나가 박자를 바꿨다.<br><br>이쪽 앞이다. 허연 손이 어깨를 짚었다.<br>뿌리쳤다. 어깨에 가루가 묻었다. 털어도 남았다.`,
        win:{ exp:14, dream:2 }, lose:{ hp:-12, mind:-6 } }
    ] },

  { at:'C4', t:'포자 온실 — 버섯이 덮은 부적',
    x:`온실 안쪽 문에 종이가 붙어 있다. 부적이다. 누가 안에서 붙였다.<br><br>
      글씨를 읽었다. 「나가지 못할 것」. 가두는 것이다.<br>
      종이 위로 버섯 실이 덮였다. 글씨 반이 먹혔다. 먹힌 자리마다 문틈이 조금씩 벌어진다.<br><br>
      틈 안쪽에서 무언가 숨을 쉰다. 단 냄새가 난다.`,
    o:[
      { l:'① 먹힌 글씨를 마저 읽어 무엇을 가뒀는지 안다.', k:'gaze', dc:14,
        ok:`남은 획으로 빈 획을 메웠다. 「나가지 못할 것 — 그 아이도」.<br><br>가둔 건 버섯이 아니다. 버섯이 처음 자란 몸이다. 정원사의 아이다. 그 아이가 지금 이 온실 한가운데에 있다.<br>일행에게 일렀다. 한가운데의 큰 것에게는 사람 모양이 남아 있을 거라고. 그 모양에 속지 말라고.<br><br>그 문은 열지 않고 돌아갔다.`,
        ng:`읽으려고 버섯 실을 걷었다. 실이 터지며 가루를 뿜었다.<br><br>눈이 따갑다. 한참 못 떴다.<br>그사이 문틈이 한 뼘 벌어졌다. 일행이 문을 등으로 막았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-10, mind:-8 } },
      { l:'② 마력으로 봉인을 덧쓴다.', k:'fix', dc:15, cost:{ mana:20 },
        ok:`부적 위에 손바닥을 대고 마력을 흘렸다. 먹힌 획마다 새 획을 덮었다.<br><br>버섯 실이 오그라들었다. 문틈이 닫혔다.<br>안쪽 숨소리가 한 번 크게 났다가 멀어졌다.<br><br>안에서 붙인 사람은 이 봉인에 제 숨까지 썼다. 이쪽은 마력만 썼다.`,
        ng:`덧쓰는데 버섯 실이 마력을 먹었다. 실이 굵어졌다.<br><br>부적이 이쪽 손바닥에 붙었다. 떼어 내자 종이가 찢어졌다.<br>문틈에서 허연 손가락 하나가 나와 문짝을 더듬었다. 다들 뛰었다.`,
        win:{ exp:20, dream:2, spirit:5 }, lose:{ hp:-12, spirit:-10 } }
    ] },

  { at:'C4', t:'포자 온실 — 발목의 실뿌리',
    x:`일행 하나가 걸음이 무겁다. 본인은 지쳐서라고 한다.<br><br>
      발목을 봤다. 신발 끈 사이로 허연 실이 들어가 있다. 땅에서 나온 실이다.<br>
      실은 온실 한가운데로 이어진다. 머리카락으로 거는 매듭과 똑같이 생겼다. 다만 이건 살아 있다.<br><br>
      실이 조금씩 당긴다. 그 사람이 한가운데 쪽으로 한 발 기울었다.`,
    o:[
      { l:'① 실을 따라가 한가운데의 매듭을 찾는다.', k:'gaze', dc:15,
        doom:{ title:'실뿌리', what:'실뿌리에 감겨 화단 속으로 끌려갑니다', dc:15, sec:55,
          text:`실을 손에 감으며 따라갔다. 화단 셋을 지나고 넷을 지났다.<br><br>실이 굵어진다. 이쪽 손목에 감긴 쪽이 더 굵다. 언제부터인지 이쪽이 감고 있는 게 아니라 감겨 있다.<br>발밑 흙이 열렸다. 허연 것이 무릎을 감싼다. 따뜻하고 부드럽다.<br><br>한가운데가 이쪽을 끌어당긴다. 매듭의 끝을 찾은 쪽이 매듭이 된다.`,
          dieText:`일행 하나의 걸음이 다시 가볍다.<br><br>실뿌리는 이제 다른 발목을 찾지 않는다.<br>온실 한가운데에 매듭 하나가 늘었다. 사람 모양이다.` },
        ok:`실을 감되 손목에는 안 감았다. 손가락 두 개에만 걸었다.<br><br>화단 넷을 지나 실이 굵어지는 자리에서 멈췄다. 거기 땅에 매듭이 있다. 허연 실이 스스로 묶은 매듭이다. 사람 매듭과 꼬는 방향이 반대다.<br>반대로 한 번 비틀었다. 매듭이 풀렸다. 뒤에서 일행이 앞으로 휘청 넘어졌다. 다리가 가볍다고 했다.<br><br>살아 있는 매듭도 매듭이다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 발목의 실을 소금으로 지져 떼어 낸다.', k:'heal', dc:14,
        ok:`신발 끈을 풀고 소금을 한 줌 문질렀다.<br><br>실이 오그라들며 살갗에서 떨어져 나갔다. 땅 쪽으로 도망갔다.<br>발목에 허연 자국이 둥글게 남았다. 아프다고 한다. 아픈 게 낫다.<br><br>남은 소금은 일행 신발 속에 조금씩 넣어 두었다.`,
        ng:`소금이 닿자 실이 더 깊이 파고들었다.<br><br>그 사람이 주저앉았다. 발목이 하얗게 부었다.<br>칼로 실을 긁어내는 데 한참 걸렸다. 둘 다 진이 빠졌다.`,
        win:{ exp:16, spirit:5 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C', t:'방 — 목줄의 이름',
    x:`어둠 속에서 큰 짐승이 걸어 나온다. 개를 닮았는데 다리가 길다. 목에 가죽 줄이 감겨 있다.<br><br>
      목줄에 글씨가 새겨져 있다. 이름이다.<br>
      누가 이것을 길렀다. 이름을 붙이고 줄을 맸다. 주술사에게 이름 붙은 짐승은 반쯤 묶인 짐승이다.<br><br>
      짐승이 이빨을 드러낸다. 일행이 창을 낮춘다.`,
    o:[
      { l:'① 목줄의 이름으로 짐승을 부른다.', k:'gaze', dc:15,
        ok:`이름을 불렀다. 낮게, 주인이 부르던 박자로. 목줄 닳은 자리를 보면 어디서 당겼는지 안다. 부르는 박자도 거기 있다.<br><br>짐승이 멈췄다. 고개를 기울였다. 오래 못 들은 이름이다.<br>그 한 번의 머뭇거림에 일행 창이 들어갔다. 짐승이 쓰러지면서도 이쪽을 봤다. 이름을 부른 쪽을.<br><br>이름 하나로 짐승 한 마리를 세웠다. 목줄을 거두었다. 부르는 박자를 찾는 일이 이제는 매듭 짓는 일만큼 손에 익었다.`,
        ng:`불렀는데 이름 끝 음을 틀렸다.<br><br>짐승이 그 틀린 소리를 주인 목소리가 아닌 걸로 알아들었다.<br>달려들었다. 앞발에 가슴을 밀려 넘어졌다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-6 }, wake:1 },
      { l:'② 다 같이 창을 겨누고 버틴다.', k:'steady', dc:14,
        ok:`창끝 다섯을 한 줄로 세웠다. 물러서지 않았다.<br><br>짐승이 창끝 앞에서 몇 번 머뭇거렸다. 돌아서려다 다시 왔다.<br>그때 창이 다 같이 나갔다.<br><br>쓰러진 짐승의 목줄에서 이름을 읽었다. 그 이름은 묻어 주었다.`,
        ng:`창끝이 흔들렸다. 누군가 뒤로 반 발 물러났다.<br><br>짐승이 그 틈으로 들어왔다. 둘이 넘어졌다.<br>겨우 끝냈을 때 다들 어딘가를 물렸다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C', t:'방 — 잡은 짐승의 고기',
    x:`방금 잡은 짐승이 식어 간다. 고기가 많다. 다들 배가 고프다.<br><br>
      칼을 대기 전에 먼저 본다. 이런 곳 짐승은 저주를 품고 산다. 먹으면 옮는 것이 있다.<br>
      가죽 안쪽에 검은 무늬가 있다. 핏줄 같기도 하고 글씨 같기도 하다.<br><br>
      무늬가 다리 쪽에는 없다.`,
    o:[
      { l:'① 무늬를 읽어 먹을 데를 가른다.', k:'gaze', dc:14,
        ok:`무늬는 심장에서 시작해 머리로 간다. 다리로는 안 간다.<br><br>저주는 피를 따라 위로 오른다. 뒷다리 살은 깨끗하다.<br>뒷다리만 떼어 냈다. 나머지는 소금을 쳐서 덮어 두었다.<br><br>그날 밤 다들 배불리 먹었다. 꿈도 안 꿨다.`,
        ng:`다리에 무늬가 없다고 봤는데 안쪽에 있었다.<br><br>한 점 먹고 나서 혀가 검어졌다.<br>밤새 누가 이쪽 이름을 거꾸로 부르는 꿈을 꿨다.`,
        win:{ exp:16, item:'짐승 고기' }, lose:{ hp:-8, spirit:-12 } },
      { l:'② 마력으로 고기에 든 저주를 뽑아낸다.', k:'gaze', dc:15, cost:{ mana:16 },
        ok:`고기에 손바닥을 대고 마력을 흘렸다. 검은 무늬를 한 줄로 모았다.<br><br>모인 무늬를 실에 옮겨 감았다. 실이 검게 젖었다. 그 실은 태웠다.<br>고기가 그냥 고기다. 김이 나고 붉다.<br><br>짐승을 잡는 데 창이 들고, 먹는 데 주술이 든다.`,
        ng:`모으는데 무늬가 이쪽 손바닥으로 넘어왔다.<br><br>손금 위로 검은 줄이 하나 생겼다. 안 지워진다.<br>고기는 못 먹었다. 손바닥이 오래 저렸다.`,
        win:{ exp:18, item:'짐승 고기', spirit:5 }, lose:{ hp:-10, spirit:-10 } },
      { l:'③ 고기에 손대지 않고 묻는다.', k:'steady', dc:13,
        ok:`아깝지만 묻었다. 흙을 두껍게 덮고 돌을 얹었다.<br><br>배는 고팠다. 저주는 안 옮았다.<br>묻은 자리에서 밤새 무언가 긁는 소리가 났다. 돌은 버텼다.<br><br>아침에 다들 말린 것을 조금씩 나눠 먹었다.`,
        ng:`묻는데 짐승 눈이 떠졌다. 한 번.<br><br>그 눈과 마주쳤다. 무늬가 눈으로 넘어오는 것 같았다.<br>돌을 얹고 돌아섰다. 머리가 오래 무거웠다.`,
        win:{ exp:12, spirit:6 }, lose:{ mind:-8, spirit:-10 } }
    ] },

  { at:'C', t:'방 — 다시 벌어지는 상처',
    x:`일행 하나의 팔 상처가 또 벌어졌다. 세 번째다.<br><br>
      싸맬 때마다 아물고, 조금 지나면 벌어진다. 아까 놓친 짐승에게 긁힌 자리다.<br>
      알 만하다. 그 짐승이 살아 있는 동안 상처는 그 짐승 것이다. 실처럼 이어져 있다.<br><br>
      어둠 저쪽에서 그것이 숨을 고른다. 기다리는 중이다.`,
    o:[
      { l:'① 상처에 이어진 실의 방향을 읽는다.', k:'gaze', dc:14,
        ok:`상처 위로 손을 펴서 실의 결을 더듬었다. 저쪽, 낮은 데.<br><br>짐승은 높은 데 있을 거라고 다들 생각했다. 실은 바닥을 기어간다. 그것도 바닥에 엎드려 있다.<br>일행이 바닥을 향해 창을 겨누고 다가갔다. 그것이 엎드린 채 뛰어올랐다. 창이 먼저 있었다.<br><br>상처가 그제야 제대로 아물기 시작했다.`,
        ng:`실 결을 더듬다 손바닥에 그 짐승의 숨이 느껴졌다.<br><br>가깝다. 너무.<br>그것이 먼저 왔다. 상처 난 사람을 다시 긁고 달아났다. 상처가 둘이 되었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
      { l:'② 마력으로 상처를 짐승 쪽으로 되돌려 보낸다.', k:'gaze', dc:15, cost:{ mana:22 },
        ok:`상처에 손을 얹고 실을 잡았다. 마력을 실어 반대쪽으로 밀었다.<br><br>상처가 닫혔다. 이번엔 안 벌어졌다. 어둠 저쪽에서 짐승이 짧게 울었다. 그것의 앞다리에 같은 모양의 상처가 열렸다.<br>절뚝이는 소리가 났다. 일행이 소리를 쫓아갔다.<br><br>남의 몸에 난 것을 원래 주인에게 돌려주는 법. 상처도 매듭이라는 걸 손이 알았다. 매듭이면 이쪽이 다룬다.`,
        ng:`미는데 실이 끊겼다. 반쯤 간 자리에서.<br><br>상처의 반이 이쪽 팔에 왔다. 똑같은 모양으로.<br>둘이 같은 상처를 하나씩 싸맸다.`,
        win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-16, spirit:-8 }, wake:1 }
    ] },

  { at:'C', t:'방 — 앞서 놓인 매듭 덫',
    x:`바닥에 고리가 놓여 있다. 매듭 진 줄이다. 짐승 덫이다.<br><br>
      누가 놓은 지 오래됐다. 줄이 바래고 매듭이 느슨하다.<br>
      이 매듭은 안다. 걸리면 조이는 것이 아니라 걸리면 못 떠나는 것이다. 짐승을 그 자리에 묶어 두는 덫.<br><br>
      통로 저쪽에서 다리 여럿 달린 것이 이리로 온다.`,
    o:[
      { l:'① 매듭을 다시 조여 덫을 살린다.', k:'gaze', dc:14,
        ok:`느슨한 매듭을 하나씩 조였다. 마지막 매듭에 침을 묻혔다. 이쪽 것이 되라고.<br><br>다리 여럿 달린 것이 고리를 밟았다. 다리 하나가 바닥에 붙었다. 빼려고 버둥거렸다. 붙은 다리가 하나 늘었다.<br>일행이 그것을 끝냈다. 덫은 아직 살아 있다.<br><br>덫을 놓은 사람은 다시 오지 못했다. 덫은 남아서 일했다.`,
        ng:`조이는데 매듭이 이쪽 손가락을 물었다. 덫은 짐승을 가리지 않는다.<br><br>그것이 다가오는데 손가락이 바닥에 붙어 있다.<br>일행이 줄을 잘랐다. 덫도 같이 죽었다. 그것과 맨손으로 싸웠다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
      { l:'② 덫은 그대로 두고 길을 덫 위로만 낸다.', k:'fix', dc:14,
        ok:`덫을 건드리지 않고 그 둘레에 돌을 쌓았다. 길이 덫 위로만 나게.<br><br>그것은 돌을 피해 덫 위로 왔다. 다리가 붙었다.<br>남이 놓은 덫에 길만 냈다.<br><br>덫 놓은 사람에게 미안할 것은 없다.`,
        ng:`돌을 쌓는 소리를 그것이 들었다.<br><br>돌을 넘어서 왔다. 덫 옆으로.<br>쌓은 돌이 무너져 발등을 찧었다.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-12, mind:-6 } }
    ] },

  { at:'C', t:'방 — 그림자에 박는 못',
    x:`천장을 기는 것이 있다. 빛을 피한다. 등불을 돌리면 그림자 속으로 미끄러진다.<br><br>
      일행 창이 몇 번이나 허공을 찔렀다. 빠르다.<br>
      그림자를 봤다. 몸은 빨라도 그림자는 몸을 따라야 한다. 그림자는 바닥에 있다.<br><br>
      주머니에 오래 들고 다닌 못이 하나 있다.`,
    o:[
      { l:'① 마력을 실은 못을 그림자 머리에 박는다.', k:'gaze', dc:15, cost:{ mana:20 },
        ok:`등불을 낮게 들어 그림자를 길게 늘였다. 그림자의 머리가 바닥 한가운데 왔다.<br><br>못에 마력을 담아 그림자 정수리에 박았다. 망치 대신 손바닥으로.<br>천장의 것이 멈췄다. 움직이려 해도 그림자가 안 따라온다. 그림자 없이는 못 간다.<br><br>창이 들어갔다. 못을 뽑아 다시 주머니에 넣었다. 그림자 어디가 머리인지 이제 등불 한 번 돌리면 안다.`,
        ng:`박는 순간 등불이 흔들렸다. 그림자가 비켜 갔다.<br><br>못이 바닥만 찍었다. 손바닥이 못 머리에 찔렸다.<br>천장의 것이 이쪽 머리 위로 떨어져 할퀴고 갔다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, spirit:-6 }, wake:1 },
      { l:'② 등불을 꺼서 그림자를 없앤다.', k:'hide', dc:14,
        ok:`등불을 껐다. 어둠 속에서 그림자는 없다.<br><br>천장의 것도 어디로 미끄러져야 할지 모른다. 빛이 있어야 피한다.<br>숨소리를 따라 일행 셋이 창을 올렸다. 하나가 맞았다.<br><br>불을 켜니 바닥에 떨어져 있었다.`,
        ng:`끄자 천장의 것이 기다렸다는 듯 내려왔다.<br><br>어둠은 그것의 것이다. 이쪽 것이 아니다.<br>등을 할퀴었다. 불을 다시 켜는 데 손이 떨렸다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C', t:'방 — 사냥꾼의 부적 주머니',
    x:`벽에 기대 앉은 채 굳은 사람이 있다. 사냥꾼 차림이다.<br><br>
      허리에 가죽 주머니. 안에 부적이 가득하다. 수십 장.<br>
      남의 부적은 함부로 안 쓴다. 대부분 소용없다. 사냥꾼이 굳은 걸 보면.<br><br>
      그래도 한두 장은 진짜일 수 있다.`,
    o:[
      { l:'① 진짜를 가려낸다.', k:'gaze', dc:14,
        ok:`한 장씩 폈다. 글씨는 다 그럴듯하다. 그러나 그럴듯한 건 다 가게에서 산 것이다.<br><br>한 장만 글씨가 서툴다. 제 손으로 쓴 것이다. 먹 대신 제 피로. 이것만 진짜다.<br>사냥꾼은 그걸 마지막까지 안 썼다. 제일 아까워서.<br><br>그 부적은 이쪽이 쓰기로 했다. 주머니 밑바닥에 말린 고기도 있었다.`,
        ng:`진짜를 골랐다고 생각했다. 펴는 순간 부적이 타 버렸다.<br><br>사냥꾼이 남긴 마지막 것이었다. 연기가 굳은 얼굴을 쓰다듬고 흩어졌다.<br>등 뒤가 오래 차가웠다.`,
        win:{ exp:16, item:'말린 고기', spirit:5 }, lose:{ spirit:-12, mind:-6 } },
      { l:'② 사냥꾼을 눕히고 주머니는 그대로 둔다.', k:'bond', dc:13,
        ok:`굳은 몸을 눕혔다. 무거웠다.<br><br>주머니는 품에 그대로 두었다. 그의 것이다.<br>눕히고 나니 등 뒤 벽에 칼로 그은 지도가 드러났다. 그가 기대서 가리고 있던 것이다.<br><br>그는 지도를 지키다 굳었다. 이제 이쪽이 읽는다.`,
        ng:`눕히는데 몸이 바스러졌다.<br><br>주머니에서 부적이 쏟아졌다. 전부 한꺼번에 타올랐다.<br>불을 끄느라 손을 데었다.`,
        win:{ exp:14, dream:2 }, lose:{ hp:-10, spirit:-8 } }
    ] },

  { at:'C', t:'방 — 이쪽을 노리는 눈',
    x:`목덜미가 따끔하다. 이쪽만.<br><br>
      알 만하다. 무언가 이쪽을 골라 보고 있다. 노리는 눈이다. 그 눈이 오래 머물면 몸이 먼저 지친다.<br>
      어둠 저쪽에 노란 눈 둘이 떠 있다. 깜빡이지 않는다.<br><br>
      일행은 아무것도 못 느낀다. 그것은 이쪽만 본다.`,
    o:[
      { l:'① 눈길을 매듭으로 받아 되돌린다.', k:'gaze', dc:15,
        ok:`손가락으로 공중에 매듭을 지었다. 눈길이 오는 길에.<br><br>눈길은 실과 같다. 매듭에 걸리면 돌아간다. 노란 눈이 한 번 깜빡였다. 처음으로.<br>그것이 제 눈길을 맞고 비틀거렸다. 일행이 그쪽으로 등불을 던지고 달려갔다.<br><br>목덜미가 식었다.`,
        ng:`매듭을 짓는데 손가락이 굳는다. 눈길이 먼저 왔다.<br><br>무릎이 꺾였다. 숨이 가쁘다.<br>일행이 이쪽을 가리고 섰다. 그것이 다른 데를 볼 때까지 오래 걸렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-12, spirit:-10 } },
      { l:'② 마력으로 눈길을 일행의 방패에 옮겨 맨다.', k:'fix', dc:14, cost:{ mana:16 },
        ok:`일행 하나의 방패에 손을 대고 마력을 감았다. 이쪽이 여기 있다고.<br><br>노란 눈이 방패를 노렸다. 방패는 지치지 않는다.<br>그것이 방패만 노리는 사이 다른 셋이 옆으로 돌아 들어갔다.<br><br>방패에는 그 뒤로 한동안 긁힌 자국이 늘었다. 아무도 안 긁었는데.`,
        ng:`옮겨 매는데 매듭이 반만 갔다.<br><br>눈길이 방패와 이쪽 사이를 오가며 둘 다 노렸다.<br>방패 든 사람도 같이 지쳤다. 둘이 기대 겨우 섰다.`,
        win:{ exp:18, spirit:6 }, lose:{ mind:-8, spirit:-10 } },
      { l:'③ 눈을 감고 버틴다.', k:'steady', dc:14,
        ok:`눈을 감았다. 보는 눈과 마주치지 않으면 반은 막는다.<br><br>목덜미가 계속 따끔했다. 견뎠다.<br>일행이 그사이 노란 눈 쪽으로 다가가 끝냈다.<br><br>눈을 떴을 때 주먹을 너무 오래 쥐어 손이 펴지지 않았다.`,
        ng:`감아도 보인다. 눈꺼풀 안쪽에 노란 것이 둘.<br><br>그것이 거기 있다. 눈꺼풀 안에.<br>눈을 떴다. 더 가까워져 있었다.`,
        win:{ exp:14, mind:5 }, lose:{ mind:-10, spirit:-10 } }
    ] },

  { at:'C', t:'방 — 한 매듭에 둘',
    x:`짐승 둘이 양쪽에서 온다. 한쪽은 비늘, 한쪽은 털이다.<br><br>
      일행은 다섯. 둘을 한꺼번에 받기에는 모자라다.<br>
      주술사는 짐승 둘의 걸음을 본다. 서로를 싫어하는 걸음이다. 마주치면 싸울 것들인데, 이쪽이 가운데 있어서 마주치지 않는다.<br><br>
      주머니에 실이 한 타래 있다.`,
    o:[
      { l:'① 털과 비늘을 한 매듭에 묶는다.', k:'gaze', dc:16,
        ok:`바닥에 떨어진 털 한 올과 비늘 한 조각을 주웠다. 실 하나로 둘을 감았다. 매듭 하나로 조였다.<br><br>짐승 둘이 한꺼번에 멈췄다. 서로를 봤다. 이쪽이 아니라.<br>둘이 엉켰다. 비늘과 털이 한데 굴렀다. 일행은 벽에 붙어 기다렸다. 남은 하나는 다리를 절었다. 그것만 끝내면 됐다.<br><br>매듭 하나에 하나씩 걸던 것을 하나에 둘을 걸었다. 둘을 묶으니 둘이 서로를 붙든다. 실을 감으며 셋도 되겠다고 생각했다.`,
        ng:`털을 집는 사이 비늘 쪽이 먼저 왔다.<br><br>매듭을 다 짓지 못했다. 반만 묶인 둘이 이쪽만 봤다.<br>둘을 한꺼번에 받았다. 다들 크게 다쳤다.`,
        win:{ exp:24, dream:4 }, lose:{ hp:-18, spirit:-8 }, wake:1 },
      { l:'② 한쪽을 막고 한쪽부터 친다.', k:'break', dc:15,
        ok:`셋이 털 쪽을 막고 둘이 비늘 쪽을 쳤다. 이쪽은 비늘 쪽이다.<br><br>비늘 틈을 찾아 일러 주었다. 목 밑, 비늘이 거꾸로 난 자리.<br>비늘 쪽이 쓰러지자 다섯이 다 털 쪽으로 돌았다.<br><br>둘은 버거웠다. 하나씩은 됐다.`,
        ng:`털 쪽을 막던 셋이 밀렸다.<br><br>털 쪽이 비늘 쪽 옆으로 왔다. 둘이 나란히.<br>다들 물러나다 넘어졌다. 겨우 벽 틈으로 빠졌다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] }
]);

// ── 퇴마사 (마력)
kJob('exorcist', 'C', [
  { at:'C1', t:'도축장 — 떠나지 못한 것',
    x:`갈고리마다 고기가 걸려 있다. 잘린 자리에 살이 다시 찬다. 천천히, 숨 쉬듯이.<br><br>
      일행은 고기가 산다고 한다. 이쪽 눈에는 고기 위에 앉은 것이 보인다. 흐릿하고 뿔이 있다.<br>
      잡힌 소다. 몸은 잘렸는데 몸에서 안 나갔다. 나갈 틈이 없었다. 줄이 한 번도 안 멈췄으니까.<br><br>
      붙어 있는 동안은 살이 계속 돋는다.`,
    o:[
      { l:'① 붙어 있는 것을 하나하나 짚어 센다.', k:'gaze', dc:14,
        ok:`갈고리를 따라 걸으며 셌다. 붙은 것이 있는 고기, 없는 고기.<br><br>마흔 중에 서른아홉에 붙어 있다. 하나만 비었다. 빈 고기는 자라지 않는다. 정말로 죽은 것이다.<br>일행에게 그 하나만 떼어 가자고 했다. 나머지는 손대지 말라고. 손대면 붙은 것이 손을 탄다.<br><br>빈 고기를 챙겼다. 차갑고 조용하다. 먹어도 된다.`,
        ng:`세다가 하나가 이쪽을 돌아봤다. 뿔 있는 흐릿한 것이.<br><br>갈고리에서 내려와 이쪽 어깨에 올라탔다. 무겁다. 소 한 마리만큼.<br>한참을 휘청이며 걸었다. 언제 내려갔는지도 모른다.`,
        win:{ exp:16, item:'짐승 고기' }, lose:{ hp:-12, spirit:-8 } },
      { l:'② 마력을 내려 고기에 앉은 것들을 한꺼번에 내보낸다.', k:'gaze', dc:15, cost:{ mana:20 },
        ok:`레일 기둥에 손바닥을 대고 마력을 흘렸다. 줄 전체로.<br><br>흐릿한 것들이 하나씩 고개를 들었다. 갈 곳을 몰랐다. 손으로 길을 가리켰다. 문 쪽, 바깥 쪽.<br>서른아홉이 줄지어 나갔다. 갈고리 고기가 그 자리에서 식었다. 잘린 대로 남았다.<br><br>하나씩 보내던 것을 줄째로 보냈다. 손바닥 한 번에 여럿이 따라 나갈 때 그 무게가 손목으로 왔다. 그 무게를 견디는 법이 몸에 남았다.`,
        ng:`마력이 줄을 다 못 돌았다. 중간에서 막혔다.<br><br>나가려던 것들이 막힌 자리에 몰렸다. 이쪽 손바닥 쪽으로.<br>손을 뗐을 때 팔이 소 울음처럼 떨렸다.`,
        win:{ exp:22, dream:3, spirit:5 }, lose:{ hp:-10, spirit:-12 }, wake:1 }
    ] },

  { at:'C1', t:'도축장 — 줄 선 것들',
    x:`우리 안에 무언가 줄을 서 있다. 소 모양이다. 흐릿하다. 차례를 기다린다.<br><br>
      줄 맨 앞은 도축대다. 줄은 줄지 않는다. 하나가 들어가면 뒤에 하나가 생긴다.<br>
      퇴마사는 줄 가운데를 본다. 소 모양들 사이에 소가 아닌 것이 하나 서 있다.<br><br>
      일행 하나와 같은 옷을 입었다. 그 일행은 지금 이쪽 옆에 없다.`,
    o:[
      { l:'① 줄 선 것들 사이에서 일행을 가려낸다.', k:'gaze', dc:14,
        ok:`흐릿한 것들은 발이 없다. 줄 선 것들 중 발이 바닥을 밟는 건 하나뿐이다.<br><br>그 하나에게 걸어갔다. 소 모양들이 비켜 주지 않았다. 차갑게 몸을 스쳤다.<br>일행의 어깨를 잡았다. 그 사람이 꿈에서 깬 듯 이쪽을 봤다. 언제부터 여기 있었는지 모른다고 했다.<br><br>그 사람이 빠진 자리는 아무도 채우지 않았다.`,
        ng:`가려내는 사이 줄이 한 칸 나아갔다.<br><br>그 사람이 도축대에 한 칸 가까워졌다. 다급하게 끌어냈다.<br>끌려 나오며 그 사람이 소처럼 울었다. 한참 지나서야 사람 소리를 냈다.`,
        win:{ exp:18, dream:2, spirit:5 }, lose:{ mind:-10, spirit:-10 } },
      { l:'② 이름을 크게 불러 줄 밖으로 불러낸다.', k:'bond', dc:14,
        ok:`그 사람 이름을 불렀다. 다섯이 한꺼번에.<br><br>소 모양들 사이에서 고개 하나가 돌아갔다. 사람 고개다.<br>그 사람이 줄 밖으로 걸어 나왔다. 걸음이 소처럼 무거웠다. 이쪽에 닿자 가벼워졌다.<br><br>줄은 아무 일도 없었다는 듯 계속 섰다.`,
        ng:`불렀는데 소 모양들이 다 같이 돌아봤다.<br><br>이름을 불린 것처럼. 전부.<br>그것들이 우리를 넘어 이쪽으로 몰려왔다. 차가운 것에 몇 번이나 밀려 넘어졌다.`,
        win:{ exp:14, spirit:6 }, lose:{ hp:-12, spirit:-8 } }
    ] },

  { at:'C1', t:'도축장 — 백정의 등',
    x:`레일 끝에서 그것이 일한다. 사람보다 크다. 앞치마를 두르고 큰 칼을 쥐었다.<br><br>
      칼질은 쉬지 않는다. 그런데 이쪽 눈에는 그 등이 보인다. 등에 무언가 업혀 있다. 작고 마른 것이 두 팔로 그 목을 감고 있다.<br>
      일하는 몸은 껍데기다. 부리는 건 등에 업힌 쪽이다.<br><br>
      일행은 큰 몸만 본다. 칼을 뽑는다.`,
    o:[
      { l:'① 다가가 업힌 것의 얼굴을 확인한다.', k:'gaze', dc:15,
        doom:{ title:'업힌 것', what:'백정의 갈고리에 걸려 끌려갑니다', dc:15, sec:55,
          text:`옆으로 돌아 다가갔다. 업힌 것의 옆얼굴이 보인다. 늙었다. 눈이 감겨 있다.<br><br>눈이 떠졌다. 이쪽을 봤다. 큰 몸이 칼을 놓고 갈고리를 들었다. 업힌 것이 시키는 대로.<br>갈고리가 이쪽 허리띠에 걸렸다. 레일 쪽으로 끌려간다. 발이 바닥을 긁는다.<br><br>업힌 것이 웃는다. 새 등을 찾은 얼굴이다.`,
          dieText:`레일 끝에서 그것이 일한다. 칼질은 쉬지 않는다.<br><br>등에 업힌 것이 둘이 되었다.<br>하나는 아직 눈을 감는 법을 모른다.` },
        ok:`옆얼굴까지만 봤다. 눈이 감겨 있을 때 물러났다.<br><br>늙고 마른 것이다. 등에서 떨어지면 오래 못 산다. 몸이 없으니까.<br>일행에게 큰 몸 말고 등을 노리라고 했다. 창 하나가 업힌 것의 팔을 꿰었다. 큰 몸이 그 자리에서 무너져 내렸다. 줄이 처음으로 멈췄다.<br><br>업힌 것은 바닥을 기어 다른 등을 찾았다. 소금 줄 너머에서 멈췄다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 마력을 담은 부적을 업힌 것의 등에 던진다.', k:'gaze', dc:15, cost:{ mana:20 },
        ok:`부적에 마력을 꾹 눌러 담았다. 접어서 던졌다.<br><br>업힌 것의 등에 붙었다. 그것이 비명을 질렀다. 팔이 풀렸다. 큰 몸에서 미끄러져 떨어졌다.<br>큰 몸은 칼을 쥔 채 멈췄다. 누가 시키지 않으면 아무것도 안 한다.<br><br>일행이 떨어진 것을 밟았다. 마른 나뭇가지 같은 소리가 났다.`,
        ng:`던진 부적이 큰 몸의 앞치마에 붙었다.<br><br>앞치마는 아무것도 아니다. 부적이 그냥 탔다.<br>업힌 것이 이쪽을 봤다. 큰 몸이 칼을 들고 왔다. 다들 피하느라 다쳤다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, spirit:-6 } },
      { l:'③ 큰 몸의 눈에 안 띄게 돌아 줄 밖으로 나간다.', k:'hide', dc:14,
        ok:`업힌 것은 앞을 못 본다. 큰 몸의 눈을 빌려 본다.<br><br>큰 몸의 등 쪽으로 돌면 둘 다 못 본다고 여겼다. 업힌 것은 눈을 감고 있었다.<br>그렇게 레일 끝을 빠져나갔다.<br><br>나와서 보니 그것이 아직도 칼질을 한다. 아무것도 없는 도축대에.`,
        ng:`등 뒤로 돌았는데 업힌 것의 눈이 떠 있었다.<br><br>그것은 등에서 뒤를 본다. 처음부터.<br>큰 몸이 돌아섰다. 칼끝이 이쪽 소매를 갈랐다. 팔도 조금.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C2', t:'인형 공방 — 든 것과 빈 것',
    x:`선반에 사기 인형이 빼곡하다. 다 똑같아 보인다.<br><br>
      손톱으로 하나를 두드렸다. 통, 하고 빈 소리가 난다. 옆 것을 두드렸다. 소리가 짧다. 안에 무엇이 있다.<br>
      이는 다 있다. 움직이는 건 안에 무엇이 든 것뿐이다. 빈 것은 그냥 그릇이다.<br><br>
      선반 끝에서 하나가 고개를 돌렸다. 소리 없이.`,
    o:[
      { l:'① 두드려 든 것만 가려 일행에게 알린다.', k:'gaze', dc:14,
        ok:`하나씩 두드렸다. 빈 것, 든 것, 빈 것, 빈 것, 든 것.<br><br>든 것에 숯으로 표시를 했다. 열넷이다. 일행은 그 열넷만 깨면 된다.<br>표시가 끝나자 열넷이 한꺼번에 일어섰다. 들킨 걸 안다. 일행이 먼저 쳤다.<br><br>빈 인형들은 끝까지 앉아 있었다. 그릇은 싸우지 않는다.`,
        ng:`두드리다 소리를 잘못 들었다. 든 것을 빈 것이라 했다.<br><br>일행이 그 앞을 지나다 발목을 물렸다.<br>사기 이가 살에 박혀 안 빠진다. 깨서 빼냈다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
      { l:'② 마력을 밀어 넣어 든 것을 몰아낸다.', k:'gaze', dc:15, cost:{ mana:20 },
        ok:`고개 돌린 인형의 정수리에 손바닥을 얹었다. 마력을 밀어 넣었다.<br><br>안에 든 것이 사기 안쪽을 긁으며 버텼다. 더 밀었다. 그것이 인형 입으로, 이 사이로 비집고 나와 흩어졌다.<br>인형이 그 자리에서 사기가 되었다. 그냥 그릇.<br><br>몸이 아니라 그릇에서 몰아냈다. 그릇이 단단할수록 손바닥을 더 오래 대야 한다. 그 오래를 버티는 법을 조금 알았다.`,
        ng:`밀어 넣는데 안에 든 것이 마력을 물었다. 이로.<br><br>손바닥이 인형 정수리에 붙었다. 사기가 차갑다.<br>떼어 냈을 때 손바닥 가운데에 이 자국이 둥글게 났다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-12, spirit:-10 }, wake:1 }
    ] },

  { at:'C2', t:'인형 공방 — 우는 인형',
    x:`구석에서 아이 우는 소리가 난다.<br><br>
      가 보니 작은 인형 하나다. 사기 볼에 눈물 자국이 그려져 있다. 소리는 그 입에서 난다.<br>
      일행 하나가 안아 주려 한다. 아이 목소리는 사람 손을 끈다.<br><br>
      인형 입이 울 때마다 조금씩 더 벌어진다.`,
    o:[
      { l:'① 울음 안에 든 것을 가린다.', k:'gaze', dc:14,
        ok:`울음을 끝까지 들었다. 아이는 울다 숨을 쉰다. 이건 숨을 안 쉰다. 같은 울음을 되풀이한다.<br><br>든 것은 아이가 아니다. 아이 울음을 흉내 내는 것이다. 들은 대로.<br>일행의 팔을 잡아 내렸다. 인형 입이 벌어지다 멈췄다. 안을 사람 손 대신 등불로 비췄다.<br><br>안은 이가 몇 줄이다. 소금을 뿌리고 천으로 싸서 묶었다.`,
        ng:`가리기 전에 일행이 안아 들었다.<br><br>울음이 그쳤다. 대신 그 사람 팔에서 소리가 났다.<br>인형을 떼어 내는 데 셋이 붙었다. 팔에 반달 자국이 줄지어 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
      { l:'② 귀를 막고 모두 등을 돌리게 한다.', k:'steady', dc:14,
        ok:`다 같이 등을 돌렸다. 귀를 막았다.<br><br>울음이 커졌다. 그리고 바뀌었다. 아이 목소리가 아니라 다른 목소리로.<br>아무도 돌아보지 않았다. 한참 뒤 울음이 그쳤다.<br><br>돌아봤을 때 인형은 구석에 없었다.`,
        ng:`등을 돌렸는데 울음이 이쪽 이름을 불렀다. 어머니 목소리로.<br><br>한 사람이 돌아봤다.<br>그 사람이 한참 울었다. 이유를 모른다고 했다.`,
        win:{ exp:14, spirit:6 }, lose:{ mind:-10, spirit:-10 } }
    ] },

  { at:'C2', t:'인형 공방 — 치수를 재는 실',
    x:`천장에서 실 몇 가닥이 내려와 일행 하나의 둘레를 맴돈다.<br><br>
      어깨에 닿았다 떨어지고, 팔 길이를 따라 내려갔다 올라간다. 재는 것이다.<br>
      위층에 있는 것이 새 몸을 찾고 있다. 이쪽 일행만 한 크기로.<br><br>
      그 사람은 실을 못 느낀다. 이쪽 눈에만 보인다.`,
    o:[
      { l:'① 실이 잰 자리마다 소금을 묻혀 치수를 흐린다.', k:'gaze', dc:15,
        ok:`실이 지난 자리를 따라 손끝으로 소금을 묻혔다. 어깨, 팔꿈치, 손목.<br><br>소금 묻은 자리는 실이 못 짚는다. 치수가 비었다. 위에서 실을 몇 번 내렸다 올렸다. 안 맞는다. 맞지 않는 몸에는 들어갈 수 없다.<br>실이 거둬 올라갔다. 위층에서 짜증 섞인 발 구르는 소리.<br><br>들어오기 전에 막는 것. 몸 밖에서, 실이 짚는 자리에서. 이쪽은 쫓아내기에 앞서 문을 닫는 손을 하나 얻었다.`,
        ng:`소금을 묻히는데 실 하나가 이쪽 손목을 쟀다.<br><br>둘이 되었다. 실이 두 사람을 오가며 잰다.<br>한참 뒤에야 실이 거둬 올라갔다. 둘 다 몸이 남의 것처럼 무거웠다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-10, spirit:-12 }, wake:1 },
      { l:'② 마력으로 그 사람 그림자를 바닥에 묶는다.', k:'fix', dc:14, cost:{ mana:18 },
        ok:`그 사람 발치 그림자에 마력으로 매듭을 지었다.<br><br>몸은 그림자를 따라간다. 그림자가 바닥에 묶이면 몸은 남의 것이 되기 어렵다.<br>실이 재고 또 재다가 포기했다. 몸이 바닥에 너무 단단하다.<br><br>나가면 풀어 줘야 한다. 잊지 않게 그 사람 손등에 소금으로 점을 찍었다.`,
        ng:`매듭을 짓는데 실이 그림자째 들어 올렸다.<br><br>그 사람이 발끝으로 섰다. 이쪽이 허리를 붙들었다.<br>실을 잘라 내는 데 다들 손이 베였다.`,
        win:{ exp:18, spirit:6 }, lose:{ hp:-12, spirit:-8 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 거꾸로 선 성수반',
    x:`기둥에 성수반이 붙어 있다. 거꾸로. 그런데 물이 안 쏟아진다.<br><br>
      물이 그릇 바닥에 붙어 위로 고여 있다. 아래로 떨어져야 할 것이 안 떨어진다.<br>
      퇴마사는 안다. 떨어져야 할 것이 안 떨어지면 무언가 붙들고 있다.<br><br>
      물속에 작은 그림자가 빙빙 돈다.`,
    o:[
      { l:'① 물을 붙든 것이 무엇인지 비춰 본다.', k:'gaze', dc:14,
        ok:`등불을 물 밑에 댔다. 물이 투명하다. 돌던 그림자가 등불을 피해 한쪽에 몰렸다.<br><br>성당이 뒤집힐 때 성수반에 손을 담그고 있던 것이다. 아이 손만 하다. 물이 쏟아지지 않게 아직 붙들고 있다.<br>「이제 놓아도 된다.」 하고 말했다. 그림자가 한 번 더 돌고 흩어졌다.<br><br>물이 쏟아졌다. 그릇을 대 받았다. 맑다. 이 성당에서 제일 깨끗한 물이다.`,
        ng:`비추자 그림자가 물 밖으로 뛰어나왔다. 이쪽 손등으로.<br><br>차갑다. 손등에 붙어서 안 떨어진다.<br>한참 문질렀다. 손등 살갗이 하얗게 일어났다.`,
        win:{ exp:16, item:'맑은 물', spirit:5 }, lose:{ hp:-8, spirit:-12 } },
      { l:'② 마력으로 붙든 것을 달래 물을 받아 낸다.', k:'heal', dc:14, cost:{ mana:16 },
        ok:`손바닥을 그릇 아래 대고 마력을 흘렸다. 붙든 것을 달래듯이.<br><br>물이 천천히 손바닥 위로 흘러내렸다. 차갑고 가볍다.<br>일행의 상처를 그 물로 씻었다. 잘 아문다.<br><br>그릇을 붙든 것은 물을 다 넘기고 나서야 사라졌다.`,
        ng:`물이 흘러내리다 멈췄다. 손바닥 위에서 동그랗게 뭉쳤다.<br><br>뭉친 물이 이쪽 손목을 타고 소매 안으로 기어들었다.<br>한기가 겨드랑이까지 올라왔다. 한참 떨었다.`,
        win:{ exp:16, hp:8, spirit:5 }, lose:{ hp:-12, spirit:-8 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 고해실',
    x:`머리 위에 고해실이 매달려 있다. 나무 상자다. 창살 너머로 목소리가 난다.<br><br>
      「말해 보시오. 무엇을 잘못했소.」<br>
      창살 너머를 봤다. 신부 옷이 걸려 있다. 옷만 걸려 있다. 목소리는 옷 안이 아니라 상자 자체에서 난다.<br><br>
      일행 하나가 무언가 털어놓으려 입술을 달싹인다.`,
    o:[
      { l:'① 창살에 귀를 대고 무엇이 듣는지 가린다.', k:'gaze', dc:15,
        doom:{ title:'고해', what:'창살 틈으로 빨려 들어갑니다', dc:15, sec:55,
          text:`귀를 댔다. 상자 안이 깊다. 상자보다 깊다.<br><br>「당신도 말해 보시오.」 목소리가 귀에 바로 붙었다. 이쪽 입이 저절로 열린다. 첫 잘못이 나온다. 둘째도.<br>말할수록 몸이 창살 쪽으로 기운다. 얼굴이, 어깨가 틈으로 들어간다. 틈은 사람이 들어갈 만큼 넓지 않다. 그래도 들어간다.<br><br>상자가 이쪽을 다 듣고 싶어 한다.`,
          dieText:`고해실에서 목소리가 난다.<br><br>「말해 보시오.」 목소리가 하나 더 붙었다.<br>둘째 목소리는 듣는 법을 아는 목소리다.` },
        ok:`귀를 대기 직전에 멈췄다. 한 뼘 앞에서 들었다.<br><br>상자는 잘못을 먹는다. 말한 만큼 몸이 가벼워지는 게 아니라 몸이 줄어든다. 말한 것을 가져간다.<br>일행 입을 손으로 막았다. 그리고 상자에 대고 거꾸로 말했다. 「들은 것을 내놓으시오.」<br><br>창살 틈에서 오래 묵은 목소리들이 한꺼번에 쏟아져 흩어졌다. 상자가 가벼워졌다. 빈 상자는 아무 말도 안 했다.`,
        win:{ exp:24, dream:3, spirit:5 } },
      { l:'② 일행의 입을 막고 지나간다.', k:'bond', dc:14,
        ok:`그 사람 입을 손바닥으로 막고 등을 밀었다.<br><br>상자가 몇 번 더 불렀다. 「말해 보시오.」 아무도 대답하지 않았다.<br>지나고 나서 그 사람이 말했다. 말하고 싶어 미칠 것 같았다고.<br><br>무엇을 말하려 했는지는 묻지 않았다.`,
        ng:`손으로 막기 전에 한마디가 나갔다.<br><br>그 사람이 휘청했다. 키가 한 뼘 줄어든 것처럼 보였다.<br>한참 동안 그 사람은 제 이름을 떠올리지 못했다.`,
        win:{ exp:16, spirit:6 }, lose:{ mind:-12, spirit:-8 } },
      { l:'③ 마력으로 창살에 봉인을 둘러 상자의 입을 막는다.', k:'fix', dc:15, cost:{ mana:20 },
        ok:`창살 네 귀퉁이에 마력을 눌러 담았다. 상자 입을 막았다.<br><br>목소리가 웅얼거림이 되었다. 들리지만 못 알아듣는다.<br>못 알아듣는 말에는 대답하지 않게 된다.<br><br>상자 밑을 지났다. 웅얼거림이 화를 냈다. 그래도 웅얼거림이었다.`,
        ng:`봉인을 두르는데 상자가 먼저 말했다. 이쪽 잘못 하나를.<br><br>이쪽도 잊고 있던 것이다. 손이 떨려 봉인이 안 섰다.<br>그 말이 오래 귀에 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-10, spirit:-12 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 입이 많은 성가대원',
    x:`성가대원 하나가 머리 위에서 거꾸로 노래한다. 목 아래로 입이 줄지어 났다.<br><br>
      입마다 다른 목소리다. 늙은 목소리, 아이 목소리, 쉰 목소리.<br>
      이쪽 눈에는 보인다. 입 하나에 하나씩 들어앉았다. 한 몸에 열둘.<br><br>
      노래가 커질 때마다 일행이 귀를 감싸고 비틀거린다.`,
    o:[
      { l:'① 입마다 든 것을 세어 하나씩 내보낸다.', k:'gaze', dc:15,
        ok:`목소리를 가렸다. 맨 위 입이 제일 늙었다. 그것이 노래를 이끈다. 나머지는 따라 부른다.<br><br>맨 아래 아이 목소리부터 불렀다. 「너는 나와라.」 그 입이 다물렸다. 다음 입. 다음.<br>따라 부르던 것들이 다 나가자 맨 위 늙은 목소리만 남았다. 혼자 부르는 노래는 힘이 없다. 일행의 창이 거기로 갔다.<br><br>한 몸에 든 여럿을 차례로 내보내는 일. 약한 것부터 내보내면 센 것이 혼자 남는다. 이쪽은 그 차례를 귀로 가리는 법을 하나 익혔다.`,
        ng:`세다가 목소리들이 섞였다. 몇이 든 건지 모른다.<br><br>엉뚱한 입을 불렀다. 그 입이 이쪽 이름을 노래했다.<br>귀에서 쇠 맛이 났다. 일행이 끌어냈다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-12, spirit:-10 }, wake:1 },
      { l:'② 마력을 실은 방울로 노래를 덮는다.', k:'steady', dc:14, cost:{ mana:16 },
        ok:`허리 방울에 마력을 담아 흔들었다. 맑은 소리가 노래 사이로 들어갔다.<br><br>노래가 방울 소리를 넘지 못했다. 입들이 박자를 잃고 엉켰다.<br>엉킨 틈에 일행이 귀를 펴고 건넜다.<br><br>방울은 금이 갔다. 그래도 울었다.`,
        ng:`방울 소리가 노래에 먹혔다. 노래의 한 음이 되었다.<br><br>방울이 노래를 따라 울었다. 멈추지 않는다.<br>방울을 손으로 감쌌다. 손안에서 오래 떨었다.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-10, spirit:-8 } }
    ] },

  { at:'C4', t:'포자 온실 — 정원사 옷 안',
    x:`정원사 옷을 입은 것이 화단 사이를 걷는다. 모자 아래 얼굴이 허옇게 부풀었다.<br><br>
      버섯이 사람을 입었다. 다들 그렇게 본다. 이쪽 눈에는 하나가 더 보인다.<br>
      옷 안 깊은 데, 버섯 사이에 사람이 웅크려 있다. 아직 다 안 먹혔다.<br><br>
      그 사람의 혼이 옷 안에서 이쪽을 본다.`,
    o:[
      { l:'① 옷 안에 남은 사람을 짚어 그 자리를 피해 치게 한다.', k:'gaze', dc:14,
        ok:`사람은 가슴께에 웅크렸다. 버섯은 등과 팔다리를 차지했다.<br><br>일행에게 등을 치라고 했다. 가슴은 피하라고. 창이 등에 들어갔다. 버섯이 무너지며 옷이 주저앉았다.<br>주저앉은 옷 안에서 혼이 빠져나왔다. 이쪽에 고개를 한 번 숙이고 갔다.<br><br>몸은 구하지 못했다. 혼은 갔다. 그것도 일이다.`,
        ng:`짚는데 웅크린 사람이 움직였다. 등 쪽으로.<br><br>창이 그 사람에게 갔다. 옷 안에서 사람 소리가 났다.<br>다들 한참 말이 없었다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-12, spirit:-10 } },
      { l:'② 마력으로 옷 안의 사람을 버섯에서 떼어 낸다.', k:'gaze', dc:16, cost:{ mana:24 },
        ok:`옷 가슴께에 손바닥을 댔다. 마력을 밀어 넣었다. 버섯이 아니라 사람 쪽을 잡았다.<br><br>당겼다. 버섯이 혼을 놓지 않으려 한다. 실처럼 엉킨 것을 하나씩 풀며 당겼다. 혼이 손바닥으로 넘어왔다. 따뜻하다.<br>혼이 빠진 옷은 그냥 버섯 덩어리가 되었다. 부리던 것이 없으니 무너졌다.<br><br>남은 사람을 먼저 꺼내면 입은 것은 무너진다. 몸 안에서 둘을 가르는 손. 이쪽 손바닥이 그 갈래를 처음 짚었다.`,
        ng:`당기는데 버섯 실이 마력을 타고 이쪽 팔로 왔다.<br><br>팔 안쪽이 간지럽다. 떼어 냈다. 손바닥에 허연 가루가 묻었다.<br>옷 안의 사람은 더 깊이 웅크렸다.`,
        win:{ exp:24, dream:3, spirit:5 }, lose:{ hp:-12, spirit:-12 }, wake:1 }
    ] },

  { at:'C4', t:'포자 온실 — 홀씨의 기도',
    x:`온실에 웅얼거림이 가득하다. 기도 소리 같다.<br><br>
      가만히 들으면 말이다. 「괜찮아. 숨 쉬어. 들이쉬어.」<br>
      버섯이 포자를 뿜을 때마다 그 말이 난다. 사람 목소리다. 먹힌 사람들의 목소리다.<br><br>
      일행이 저도 모르게 깊이 숨을 들이쉰다.`,
    o:[
      { l:'① 목소리마다 누구 것인지 가린다.', k:'gaze', dc:14,
        ok:`목소리를 하나씩 들었다. 정원사, 정원사의 아내, 배달하던 사람.<br><br>목소리 하나는 다른 것들보다 젊다. 그 목소리만 「들이쉬지 마」 하고 말한다. 다른 목소리들 사이에 묻혀서.<br>그 목소리가 들리는 쪽으로 갔다. 그쪽 화단만 포자가 없다.<br><br>먹히고도 말리는 사람이 있다.`,
        ng:`가리다 이쪽도 숨을 들이쉬었다. 깊이.<br><br>목 안이 달다. 기분이 좋다.<br>일행이 이쪽 뺨을 쳤다. 한참 뒤에야 단맛이 가셨다.`,
        win:{ exp:18, dream:2, spirit:5 }, lose:{ hp:-8, mind:-12 } },
      { l:'② 숨을 얕게 쉬며 버틴다.', k:'steady', dc:14,
        ok:`젖은 천을 입에 대고 얕게 쉬었다. 하나, 둘.<br><br>목소리들이 달랬다. 깊이 쉬라고. 안 쉬었다.<br>화단 셋을 지나자 목소리가 멀어졌다.<br><br>천을 뗐을 때 천 안쪽이 하얬다.`,
        ng:`얕게 쉬다 숨이 모자랐다. 한 번 크게 들이켰다.<br><br>그 한 번에 목소리가 하나 들어왔다. 머릿속에서 「괜찮아」 한다.<br>그 소리가 한참 안 나갔다.`,
        win:{ exp:14, mind:5 }, lose:{ mind:-10, spirit:-8 } }
    ] },

  { at:'C4', t:'포자 온실 — 무릎 꿇은 것들',
    x:`온실 한가운데로 가는 길에 무언가 무릎을 꿇고 있다. 정원사 옷 다섯.<br><br>
      다 한가운데를 향했다. 고개를 숙였다. 버섯이 등에서 피어 올라 한가운데의 큰 것으로 이어진다.<br>
      이쪽 눈에는 다섯 다 비었다. 아무도 안 남았다. 그런데 하나에만 혼이 하나 걸려 있다. 나가지 못하고.<br><br>
      그 혼이 이쪽을 부른다.`,
    o:[
      { l:'① 가까이 가서 걸린 혼을 풀어 준다.', k:'gaze', dc:15,
        doom:{ title:'무릎', what:'실뿌리가 무릎을 꿇려 끌어당깁니다', dc:15, sec:55,
          text:`다섯 사이로 들어갔다. 걸린 혼은 셋째 등에 있다. 손을 뻗었다.<br><br>무릎이 꺾였다. 저절로. 발밑에서 허연 실이 올라와 정강이를 감았다. 고개가 숙여진다. 한가운데 쪽으로.<br>걸린 혼이 이쪽을 본다. 미안한 얼굴이다. 이쪽을 부른 건 혼이 아니라 혼을 미끼로 쓴 쪽이었다.<br><br>여섯째 자리가 만들어진다.`,
          dieText:`온실 한가운데로 가는 길에 무언가 무릎을 꿇고 있다. 여섯.<br><br>다 한가운데를 향했다.<br>여섯째 등에 혼이 하나 걸려 있다. 다음 사람을 부르려고.` },
        ok:`다섯 사이로 들어가지 않았다. 바깥에서 손을 뻗을 만큼만 다가갔다.<br><br>걸린 혼에게 이름을 물었다. 대답했다. 그 이름을 불렀다. 실 끝이 혼에서 떨어졌다. 혼이 천장 유리 너머로 올라갔다.<br>미끼가 빠지자 다섯이 일제히 고개를 들었다. 쓸모가 없어졌다. 일행이 그 다섯을 차례로 넘어뜨렸다.<br><br>무릎 꿇은 것들은 일어서는 법을 몰랐다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 실뿌리를 소금으로 지져 다섯을 한가운데와 떼어 놓는다.', k:'fix', dc:14,
        ok:`다섯 등에서 한가운데로 이어진 실에 소금을 뿌렸다. 한 줄씩.<br><br>실이 오그라들며 떨어져 나갔다. 다섯이 앞으로 엎어졌다. 한가운데의 큰 것이 한 번 크게 숨을 쉬었다. 줄 다섯을 잃었다.<br>걸린 혼은 실이 떨어지자 저절로 풀렸다.<br><br>소금이 많이 들었다. 그만한 값이다.`,
        ng:`소금이 모자랐다. 셋만 떼어 냈다.<br><br>남은 둘이 일어섰다. 이쪽을 향해.<br>달아나다 둘 다 넘어졌다. 손바닥에 가루가 묻었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C', t:'방 — 두 겹 짐승',
    x:`일행이 짐승 하나를 몰아 쓰러뜨렸다. 크다. 등이 혹처럼 솟았다.<br><br>
      다들 숨을 돌린다. 이쪽은 숨을 못 돌린다. 쓰러진 몸에서 무언가 기어 나오고 있다. 흐릿하다. 눈에 보이는 건 이쪽뿐이다.<br>
      이런 데 짐승은 두 겹이다. 겉의 몸과 안에 든 것. 몸이 죽으면 안의 것은 새 몸을 찾는다.<br><br>
      제일 가까운 몸은 숨을 몰아쉬는 일행이다.`,
    o:[
      { l:'① 빠져나오는 것을 손으로 붙들어 내보낸다.', k:'gaze', dc:15,
        ok:`쓰러진 몸 위에 무릎을 대고 앉았다. 빠져나오는 것의 머리를 손바닥으로 눌렀다.<br><br>그것이 버둥거렸다. 일행 쪽으로 가려 했다. 붙든 채 「여기는 네 것이 없다」 하고 말했다. 갈 곳을 못 찾은 것은 바닥으로 스며 들어갔다. 깊이, 아주 깊이.<br>일어났을 때 일행은 아무것도 몰랐다. 그게 맞다.<br><br>몸에서 나가는 순간을 붙드는 것. 들어가 있는 것보다 나오는 것이 약하다. 그 순간을 기다리는 법을 배웠다. 사냥이 끝난 뒤가 이쪽 일의 시작이다.`,
        ng:`붙들려는데 손이 미끄러졌다. 흐릿한 것은 잡히지 않을 때가 있다.<br><br>그것이 일행에게로 갔다. 그 사람이 눈을 뒤집었다.<br>소금을 먹이고 등을 쳐서 내보냈다. 그 사람은 한참 짐승 소리를 냈다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-10, spirit:-12 }, wake:1 },
      { l:'② 소금으로 일행 둘레에 원을 친다.', k:'fix', dc:14,
        ok:`빠르게 일행 둘레에 소금을 둘렀다.<br><br>흐릿한 것이 원 둘레를 맴돌았다. 들어갈 몸이 다 원 안에 있다.<br>한참 맴돌다 멀어졌다. 새 몸을 찾아 어둠 속으로.<br><br>다음 짐승은 조금 더 셀 것이다. 그건 다음 일이다.`,
        ng:`원이 닫히기 전에 그것이 들어왔다.<br><br>일행 하나의 어깨에 앉았다. 그 사람 그림자가 짐승 모양으로 일그러졌다.<br>등을 쳐서 내보냈다. 둘 다 진이 빠졌다.`,
        win:{ exp:16, spirit:6 }, lose:{ mind:-8, spirit:-10 } }
    ] },

  { at:'C', t:'방 — 잡은 뒤의 그림자',
    x:`짐승을 잡고 그 자리를 떠났다.<br><br>
      등불 뒤로 그림자가 하나 더 따라온다. 네 발 그림자다. 아까 잡은 짐승 모양이다.<br>
      퇴마사는 그림자를 센다. 몸이 죽어도 그림자가 남으면 아직 다 안 죽은 것이다.<br><br>
      그림자가 조금씩 가까워진다. 일행 그림자에 겹치려 한다.`,
    o:[
      { l:'① 그림자가 무엇에 붙어 왔는지 짚는다.', k:'gaze', dc:14,
        ok:`그림자 끝을 따라갔다. 일행 하나의 짐에 닿는다.<br><br>짐을 열었다. 짐승 이빨 하나. 그 사람이 기념으로 뽑아 왔다.<br>이빨을 바닥에 놓고 소금을 덮었다. 그림자가 이빨 쪽으로 돌아가 눕더니 사라졌다.<br><br>기념품은 늘 무언가를 데려온다.`,
        ng:`짚으려는데 그림자가 일행 그림자에 겹쳤다.<br><br>그 사람이 네 발로 엎드렸다. 짖었다.<br>짐을 다 털어 이빨을 찾아내는 데 한참 걸렸다. 그동안 그 사람은 두 번 물었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-8 } },
      { l:'② 등불을 높이 들어 그림자를 짧게 한다.', k:'luck', dc:13,
        ok:`등불을 머리 위로 들었다. 그림자가 발밑으로 오그라들었다.<br><br>짧은 그림자는 겹칠 데가 없다. 네 발 그림자가 갈팡질팡했다.<br>그러다 바닥 틈으로 흘러 들어갔다.<br><br>팔이 아팠다. 그 길이 끝날 때까지 들고 갔다.`,
        ng:`등불을 드는데 팔이 떨렸다. 그림자가 흔들렸다.<br><br>흔들리는 그림자 사이로 네 발 그림자가 이쪽 그림자에 들어왔다.<br>발이 무겁다. 한참 짐승처럼 걸었다.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-8, spirit:-10 } }
    ] },

  { at:'C', t:'방 — 물린 뒤',
    x:`일행 하나가 아까 짐승에게 물렸다. 상처는 크지 않다.<br><br>
      그런데 그 사람 눈이 이상하다. 다른 사람 목덜미를 본다. 오래. 침을 삼킨다.<br>
      짐승의 허기가 이를 타고 옮아왔다. 물린 자리에 앉아 있다.<br><br>
      그 사람은 배가 고프다고만 한다.`,
    o:[
      { l:'① 허기가 앉은 자리를 찾아 짚는다.', k:'gaze', dc:14,
        ok:`상처 둘레를 봤다. 붉은 데가 넓어지는 쪽이 있다. 목 쪽이다. 허기는 입으로 가려 한다.<br><br>그 자리를 엄지로 눌렀다. 꾹. 그 사람이 비명을 질렀다. 비명 끝에 짐승 소리가 섞였다.<br>짐승 소리가 다 나오자 눈이 돌아왔다. 배가 고프긴 한데 사람 배고픔이라고 했다.<br><br>말린 것을 나눠 주었다. 먹는 게 사람 같다.`,
        ng:`짚기 전에 그 사람이 옆 사람 어깨를 물었다.<br><br>떼어 냈다. 둘이 다쳤다.<br>허기를 내보내는 데 다들 붙들고 있어야 했다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-8 } },
      { l:'② 마력으로 허기를 상처에서 뽑아낸다.', k:'gaze', dc:15, cost:{ mana:20 },
        ok:`상처 위에 손바닥을 얹고 마력을 내렸다. 허기를 잡았다. 실처럼 길다. 목 쪽으로 뻗어 가던 끝을 잡아 당겼다.<br><br>상처에서 검은 김이 피어올랐다. 김이 짐승 모양을 하다 흩어졌다.<br>그 사람이 다른 사람 목덜미에서 눈을 뗐다. 부끄러워했다.<br><br>사람이 사람이 아니게 되기 전, 물린 자리에서 잡아 꺼내는 것. 이쪽 손은 상처 위에서 무엇이 어느 쪽으로 뻗는지 먼저 안다.`,
        ng:`당기는데 허기가 이쪽 손바닥으로 넘어왔다.<br><br>배가 고프다. 아주. 옆 사람 손목이 맛있어 보인다.<br>이쪽 팔을 스스로 물고 버텼다. 한참 뒤에 지나갔다.`,
        win:{ exp:22, dream:3, spirit:5 }, lose:{ hp:-12, spirit:-12 }, wake:1 }
    ] },

  { at:'C', t:'방 — 소금 선의 안쪽',
    x:`바닥에 소금이 선으로 그어져 있다. 앞서 온 누가 그었다.<br><br>
      선 안쪽은 비었다. 선 바깥에 짐승 발자국이 빙빙 돈다. 그은 사람은 안쪽에서 버텼다.<br>
      소금 선은 양쪽을 다 봐야 한다. 안쪽이 안전하다. 보통은.<br><br>
      선 안쪽 바닥에 긁힌 자국이 있다. 안쪽에서 바깥으로.`,
    o:[
      { l:'① 긁힌 자국으로 무엇이 안에 갇혔는지 가린다.', k:'gaze', dc:14,
        ok:`자국이 안쪽에서 시작해 선 앞에서 멈춘다. 나가려다 못 나갔다.<br><br>소금 선은 막는다. 들어오는 것도, 나가는 것도. 그은 사람은 짐승을 막았다. 그리고 제 몸에 든 것을 같이 가뒀다. 그것이 안에서 사람을 다 먹고 아직 있다.<br>선 안으로 들어가지 않았다. 선 바깥을 돌아 지났다. 선 안에서 무언가 이쪽을 따라 돌았다.<br><br>나오지 못한다. 앞으로도.`,
        ng:`가리기 전에 일행 하나가 쉬려고 선 안으로 들어갔다.<br><br>그 사람이 금방 나왔다. 얼굴이 하얗다. 안에서 누가 귀에 대고 숨을 쉬었다고 했다.<br>그 숨소리가 그 사람 귀에서 오래 안 떠났다.`,
        win:{ exp:18, dream:2, spirit:5 }, lose:{ mind:-10, spirit:-10 } },
      { l:'② 소금 선을 이어 그어 바깥 짐승을 막는다.', k:'fix', dc:14,
        ok:`선이 한 군데 끊겨 있다. 바깥 발자국이 그 틈에서 몰린다.<br><br>새 소금으로 이었다. 바깥에 둥근 선을 하나 더 그었다. 두 겹이다.<br>그 사이에서 하룻밤을 쉬었다. 바깥에서 무언가 긁다 갔다.<br><br>안쪽 선 안에도 무언가 있었다. 두 겹이라 괜찮았다.`,
        ng:`잇는데 바깥 짐승이 틈으로 머리를 들이밀었다.<br><br>소금을 얼굴에 뿌렸다. 그것이 물러나며 이쪽 손을 할퀴었다.<br>선은 다 못 이었다. 밤새 번갈아 지켰다.`,
        win:{ exp:14, hp:6 }, lose:{ hp:-12, mind:-6 } }
    ] },

  { at:'C', t:'방 — 시체 위의 작은 것',
    x:`잡은 짐승의 몸 위에 작은 것이 앉아 있다. 쥐만 하다. 털이 없다.<br><br>
      짐승의 몸을 먹는 게 아니다. 몸에서 피어오르는 김을 먹는다. 빠져나가는 것을.<br>
      이쪽 눈에는 안다. 혼을 먹는 것이다. 다 먹으면 짐승 크기가 된다.<br><br>
      벌써 개만 하다.`,
    o:[
      { l:'① 그것이 무엇을 먹고 크는지 짚어 일행에게 알린다.', k:'gaze', dc:14,
        ok:`김이 나오는 자리가 짐승의 입이다. 작은 것이 거기 입을 대고 있다.<br><br>「입을 막아.」 일행이 짐승 입에 천을 쑤셔 넣었다. 김이 멎었다. 먹을 것이 없어진 작은 것이 이쪽을 돌아봤다. 배고픈 얼굴로.<br>개만 한 것은 아직 개만 하다. 창 셋이면 된다.<br><br>짐승의 혼은 천 틈으로 천천히 빠져나갔다. 아무도 안 먹고.`,
        ng:`짚는 사이 그것이 송아지만 해졌다.<br><br>일어섰다. 이쪽을 봤다. 먹던 것이 덜 끝났다.<br>쫓아내는 데 다들 다쳤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
      { l:'② 짐승 몸째 불에 던진다.', k:'break', dc:14,
        ok:`다 같이 짐승 몸을 끌어 등불 기름을 붓고 불을 붙였다.<br><br>불 속에서 김이 한꺼번에 올라갔다. 너무 빨라서 작은 것이 다 못 먹었다. 작은 것은 불을 싫어한다. 비켜났다.<br>비켜난 자리에서 창을 맞았다.<br><br>불이 꺼지고 다리 한쪽이 덜 탔다. 고기는 아마 괜찮다.`,
        ng:`불을 붙이는데 그것이 불길 위로 뛰어올랐다.<br><br>불을 묻힌 채 이쪽으로 왔다. 소매에 불이 붙었다.<br>굴러서 껐다. 팔이 데었다.`,
        win:{ exp:16, item:'짐승 고기' }, lose:{ hp:-16, mind:-4 } },
      { l:'③ 혼이 빠져나가는 길을 손으로 열어 준다.', k:'heal', dc:15,
        ok:`짐승 이마에 손을 얹었다. 문을 열 듯이 손바닥을 폈다.<br><br>혼이 한꺼번에 빠져나갔다. 작은 것이 입을 벌렸는데 이미 없다.<br>먹을 것을 놓친 작은 것이 쪼그라들었다. 쥐만 하게. 일행이 밟았다.<br><br>빨리 보내는 것도 지키는 것이다.`,
        ng:`문을 열었는데 혼이 이쪽 손을 타고 올라왔다. 짐승의 혼이.<br><br>네 발로 서고 싶다. 한참 그 마음과 싸웠다.<br>그사이 작은 것이 남은 걸 다 먹었다.`,
        win:{ exp:16, spirit:6 }, lose:{ mind:-10, spirit:-10 } }
    ] },

  { at:'C', t:'방 — 부적이 붙은 문',
    x:`통로 끝에 문이 있다. 부적이 다섯 장 붙어 있다. 가운데 한 장이 검게 탔다.<br><br>
      문 너머에서 숨소리가 난다. 크고 느리다. 여럿이다.<br>
      부적을 읽었다. 가둔 것이 아니다. 재운 것이다. 잠든 둥지 위에 붙인 것.<br><br>
      가운데 부적이 타 들어가며 숨소리가 조금씩 빨라진다.`,
    o:[
      { l:'① 문 너머 숨소리를 세어 몇이 깨는지 가린다.', k:'gaze', dc:14,
        ok:`숨소리를 셌다. 다섯이다. 넷은 느리고 하나만 빠르다.<br><br>깨는 건 하나다. 문을 열면 하나만 일어난다. 넷이 깨기 전에 하나를 끝내면 된다.<br>문을 열고 빠른 숨소리 쪽으로 곧장 갔다. 일행이 그 하나를 덮쳤다. 넷은 끝까지 안 깼다.<br><br>문을 닫았다. 남은 네 장으로 충분하다.`,
        ng:`세다 보니 숨소리가 계속 는다. 여섯, 일곱.<br><br>세는 소리가 문 너머로 들렸다. 숨소리 하나가 멎었다.<br>문이 안쪽에서 한 번 쿵 울렸다. 다들 달아났다. 달아나다 다쳤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-8 } },
      { l:'② 마력을 부어 탄 부적을 새로 쓴다.', k:'fix', dc:15, cost:{ mana:20 },
        ok:`손가락을 깨물어 새로 썼다. 획마다 마력을 눌러 담았다.<br><br>탄 자리에 붙였다. 문 너머 숨소리가 다시 느려졌다. 깊이 잠든다.<br>둥지는 깨우지 않았다. 다른 길로 돌았다.<br><br>모든 짐승을 다 잡을 필요는 없다.`,
        ng:`쓰는데 손가락 피가 문틈으로 빨려 들어갔다.<br><br>안의 숨소리가 냄새를 맡았다. 빨라졌다.<br>새 부적을 다 붙이기 전에 문이 덜컹였다. 다들 등으로 문을 막았다. 밤새.`,
        win:{ exp:18, spirit:6 }, lose:{ hp:-10, spirit:-12 } }
    ] },

  { at:'C', t:'방 — 따라오는 작은 혼',
    x:`일행 뒤를 작은 혼 하나가 따라온다. 아이만 하다. 흐릿하다.<br><br>
      해를 끼치지 않는다. 다만 가까이 오면 춥다. 따뜻한 데를 찾아 붙는다.<br>
      일행은 모른다. 다들 춥다고만 한다.<br><br>
      혼이 지나는 자리마다 짐승들이 고개를 든다. 차가운 걸 따라오는 것들이 있다.`,
    o:[
      { l:'① 혼에게 갈 곳을 일러 준다.', k:'bond', dc:14,
        ok:`혼 앞에 쪼그려 앉았다. 눈높이를 맞췄다.<br><br>「여기 있으면 짐승이 따라온다. 너도, 우리도.」 혼이 고개를 갸웃했다. 「저쪽으로 가면 따뜻하다.」 아무 근거 없이 위쪽을 가리켰다.<br>혼이 그쪽으로 갔다. 한 번 돌아보고.<br><br>일행이 그제야 덜 춥다고 했다. 짐승들도 고개를 내렸다.`,
        ng:`일러 주는데 혼이 이쪽 품으로 파고들었다. 제일 따뜻한 데라고.<br><br>가슴께가 얼음 같다. 손이 떨린다.<br>짐승 하나가 그 냉기를 따라와 이쪽 다리를 물었다.`,
        win:{ exp:16, spirit:6 }, lose:{ hp:-12, spirit:-8 } },
      { l:'② 혼이 왜 남았는지 본다.', k:'gaze', dc:15,
        ok:`혼을 오래 봤다. 손에 무언가 쥐었다. 흐릿한 빵 조각.<br><br>나눠 주려다 못 준 것이다. 주고 싶은 사람이 먼저 갔다.<br>말린 것 한 조각을 꺼내 혼 앞에 놓았다. 혼이 그 위에 제 빵을 얹었다. 그리고 갔다.<br><br>남은 건 이쪽 고기 한 조각이다. 조금 따뜻했다.`,
        ng:`오래 보다 혼이 이쪽을 봤다. 마주쳤다.<br><br>혼의 추위가 눈으로 들어왔다. 한동안 눈앞이 하얬다.<br>그사이 짐승이 다가왔다. 일행이 막았다. 다들 지쳤다.`,
        win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ mind:-10, spirit:-10 } }
    ] },

  { at:'C', t:'방 — 손바닥으로 짚는 자리',
    x:`일행 하나가 아까부터 말이 없다. 눈이 흐리다. 씌었다. 그건 이쪽도 안다.<br><br>
      문제는 어디에 들었는가다. 등이면 등을 치고, 배면 배를 누른다. 잘못 짚으면 더 깊이 숨는다.<br>
      겉으로는 안 보인다. 이번 것은 숨는 걸 잘한다.<br><br>
      그 사람의 손이 이쪽 목을 향해 천천히 올라온다.`,
    o:[
      { l:'① 손바닥으로 몸을 훑어 든 자리를 찾는다.', k:'gaze', dc:16,
        ok:`그 사람 손목을 잡아 내리고 다른 손바닥으로 몸을 훑었다. 이마, 목, 가슴, 배.<br><br>다 따뜻하다. 왼쪽 옆구리만 차다. 손바닥 한 장만큼. 거기 웅크렸다.<br>그 자리를 주먹으로 쳤다. 숨이 터지게. 그 사람 입에서 검은 김이 나오고 눈이 맑아졌다.<br><br>눈으로 보던 것을 손바닥으로 짚었다. 보이지 않는 것도 차가운 건 숨기지 못한다. 이쪽 손바닥이 이제 눈만큼 일한다.`,
        ng:`훑는데 그것이 자리를 옮겼다. 손바닥이 가는 데마다 비켜 갔다.<br><br>그 사람 손이 이쪽 목을 잡았다. 세다.<br>일행이 떼어 냈다. 목에 손자국이 오래 남았다.`,
        win:{ exp:24, dream:4 }, lose:{ hp:-14, spirit:-10 }, wake:1 },
      { l:'② 소금물을 먹여 토하게 한다.', k:'heal', dc:14,
        ok:`물통에 소금을 풀었다. 그 사람 입에 부었다. 싫다고 버둥거렸다. 붙들고 부었다.<br><br>토했다. 검은 것이 섞여 나왔다. 바닥에서 꿈틀대다 굳었다.<br>그 사람 눈이 돌아왔다. 입이 짜다고 했다.<br><br>무식한 방법이다. 듣는다.`,
        ng:`부었는데 그 사람이 다 뱉었다. 이쪽 얼굴에.<br><br>소금물이 눈에 들어갔다. 따갑다.<br>그사이 그 사람이 이쪽 팔을 물었다. 셋이 붙어 겨우 떼어 냈다.`,
        win:{ exp:16, spirit:5 }, lose:{ hp:-12, spirit:-8 } }
    ] }
]);

// ── 관상가 (내공)
kJob('physiog', 'C', [
  { at:'C1', t:'도축장 — 소머리들의 낯',
    x:`벽 선반에 소머리가 줄지어 놓였다. 다 눈을 뜨고 있다. 눈알이 아직 젖었다.<br><br>
      짐승 낯은 사람보다 읽기 쉽다. 감추지 않으니까. 마흔 개 낯이 다 겁에 질렸다. 잘린 뒤에도.<br>
      그런데 하나는 겁이 없다. 눈꺼풀이 편하다. 보고 있다.<br><br>
      그 하나가 이쪽 일행의 움직임을 따라 눈알을 굴린다.`,
    o:[
      { l:'① 겁 없는 낯이 누구의 눈인지 읽는다.', k:'gaze', dc:14,
        ok:`겁 없는 낯은 소 낯이 아니다. 소머리를 쓴 다른 낯이다. 눈가 주름이 사람처럼 접힌다.<br><br>그 눈이 보는 것을 레일 저쪽의 무언가도 본다. 저것이 이 도축장의 눈이다.<br>일행에게 손짓했다. 그 머리를 천으로 덮었다. 레일 저쪽에서 칼질 소리가 갈팡질팡했다.<br><br>눈 하나를 덮었을 뿐인데 도축장 전체가 더듬기 시작했다.`,
        ng:`읽는 사이 그 눈이 이쪽 눈과 맞았다.<br><br>마주친 낯은 서로를 읽는다. 저쪽이 더 빨랐다. 이쪽 겁을 읽었다.<br>레일 저쪽에서 칼질 소리가 이쪽으로 왔다. 다들 피하느라 다쳤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-8 } },
      { l:'② 내공을 눈에 모아 그 낯을 눌러 감긴다.', k:'gaze', dc:15, cost:{ qi:18 },
        ok:`내공을 눈에 모았다. 겁 없는 낯을 똑바로 봤다.<br><br>그 낯이 버텼다. 오래. 이쪽 눈이 시렸다. 그래도 안 내렸다.<br>그 낯이 먼저 눈꺼풀을 내렸다. 겁을 처음 배운 얼굴이 되었다. 다른 마흔 개와 같아졌다.<br><br>도축장의 눈이 감긴 동안 갈고리 줄 밑을 지났다.`,
        ng:`내공이 눈에서 흩어졌다. 눈물이 났다.<br><br>그 낯이 눈물을 읽었다. 눈꼬리를 올렸다. 웃는 소 낯은 처음 봤다.<br>칼질 소리가 다가왔다. 물러나다 다쳤다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C1', t:'도축장 — 백정의 탈',
    x:`레일 끝에서 칼질하는 것이 있다. 얼굴에 탈을 썼다. 소 낯가죽을 여러 장 꿰맨 탈이다.<br><br>
      낯가죽마다 표정이 다르다. 겁, 체념, 졸음.<br>
      관상가는 탈도 읽는다. 쓴 자가 고른 표정은 쓴 자를 닮는다.<br><br>
      낯가죽 하나만 눈을 깜빡인다.`,
    o:[
      { l:'① 깜빡이는 낯을 읽어 진짜 얼굴의 자리를 찾는다.', k:'gaze', dc:15,
        ok:`깜빡이는 낯은 왼쪽 볼에 있다. 탈 한가운데가 아니다. 진짜 얼굴은 탈 가운데 있지 않다. 비켜 있다.<br><br>깜빡이는 박자가 숨과 같다. 그 아래에 숨 쉬는 코가 있다. 「왼뺨.」 일행의 창이 탈 한가운데를 버리고 왼쪽으로 갔다. 그것이 처음으로 칼을 놓쳤다.<br><br>여러 낯이 겹친 데서 살아 있는 하나를 고르는 법. 깜빡임과 숨의 박자를 겹쳐 보면 된다. 낯을 하나씩 보던 눈이 이제 여럿을 한꺼번에 놓고 가른다.`,
        ng:`깜빡이는 낯을 찾았는데 둘이다. 하나는 미끼다.<br><br>엉뚱한 쪽을 일렀다. 창이 낯가죽만 찢었다.<br>그것이 칼을 휘둘렀다. 일행 둘이 다쳤다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 }, wake:1 },
      { l:'② 내공을 끌어올려 기세로 그것을 멈칫하게 한다.', k:'steady', dc:15, cost:{ qi:18 },
        ok:`단전에서 내공을 끌어올렸다. 한 번에 밀었다.<br><br>탈의 낯가죽들이 일제히 겁을 냈다. 짐승 낯은 기세에 먼저 진다. 쓴 것도 같이 흔들렸다.<br>칼이 반 박자 늦었다. 일행이 그 반 박자에 들어갔다.<br><br>탈이 하나 찢어졌다. 그 아래도 탈이었다.`,
        ng:`기세를 밀었는데 탈의 낯가죽들이 무표정했다. 겁을 다 써 버린 낯이다.<br><br>안 먹혔다. 칼이 이쪽으로 왔다.<br>비켜서다 옆구리를 베였다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-6 } }
    ] },

  { at:'C1', t:'도축장 — 갈고리에 걸린 사람',
    x:`갈고리 하나에 사람이 걸려 있다. 옷깃이 꿰였다. 발이 허공에 뜬다.<br><br>
      「살려 주시오. 내려 주시오.」 목소리가 갈라졌다.<br>
      얼굴을 봤다. 볼이 붉다. 너무 붉다. 오래 매달린 사람은 하얘진다.<br><br>
      귀 끝이 조금씩 두꺼워진다. 살이 차오르듯이.`,
    o:[
      { l:'① 가까이 가서 그 얼굴의 귀와 인중을 확인한다.', k:'gaze', dc:15,
        doom:{ title:'걸린 사람', what:'걸린 것에게 붙잡혀 레일로 끌려 올라갑니다', dc:15, sec:55,
          text:`다가갔다. 귀를 봤다. 귀가 아니다. 귓바퀴 자리에 살이 겹겹이 자란다. 인중이 없다. 매끈하다.<br><br>알아본 순간 그것이 이쪽 손목을 잡았다. 손바닥이 따뜻하고 젖었다.<br>갈고리가 레일을 따라 올라간다. 그것이 매달린 채 이쪽을 끌어 올린다. 발이 바닥에서 뜬다.<br><br>「살려 주시오.」 그것이 이쪽 목소리로 말한다.`,
          dieText:`갈고리 하나에 사람이 걸려 있다.<br><br>볼이 붉다. 인중이 반듯하다. 상이 좋다.<br>「살려 주시오.」 목소리가 아직 갈라지지 않았다.` },
        ok:`세 걸음 밖에서 멈췄다. 거기서도 보인다.<br><br>인중이 없다. 사람 얼굴에서 인중이 없는 건 없다. 고기가 사람 얼굴을 흉내 내다 빠뜨렸다.<br>일행의 팔을 잡아 내렸다. 갈고리 아래로 아무도 안 갔다. 걸린 것이 목소리를 멈추고 이쪽을 오래 봤다.<br><br>자란 살은 얼굴을 다 배우지 못한다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 갈고리 줄 반대편으로 비켜 지난다.', k:'evade', dc:14,
        ok:`걸린 것의 눈이 따라오지 못하게 기둥 뒤로 붙었다.<br><br>목소리가 이쪽을 찾았다. 「거기 누구요.」 대답하지 않았다.<br>줄 반대편 끝까지 갔다. 거기서 돌아봤다. 걸린 것이 고개를 반대로 꺾어 이쪽을 보고 있었다.<br><br>목은 사람처럼 돌지 않는다. 그건 알았다.`,
        ng:`비켜 가는데 갈고리 줄이 움직였다. 걸린 것이 이쪽으로 흘러왔다.<br><br>손이 뻗어 와 머리채를 잡았다.<br>잘라 내고 빠져나왔다. 머리카락이 한 줌 갈고리에 남았다.`,
        win:{ exp:14, dream:2 }, lose:{ hp:-14, spirit:-8 } }
    ] },

  { at:'C2', t:'인형 공방 — 그려 넣은 낯',
    x:`사기 인형마다 얼굴이 그려져 있다. 붓으로 눈썹, 눈, 입술.<br><br>
      그린 이는 솜씨가 좋다. 낯마다 사람이 있다. 본을 떠서 그렸다.<br>
      그림도 읽힌다. 그린 이의 눈에 비친 사람이 거기 남는다.<br><br>
      열 개 낯 가운데 하나만 겁에 질려 있다. 붓질이 떨렸다.`,
    o:[
      { l:'① 떨린 낯이 무엇을 보며 그려졌는지 읽는다.', k:'gaze', dc:14,
        ok:`겁에 질린 낯의 눈이 위를 본다. 그려질 때 본도 그린 이도 위를 봤다.<br><br>천장이다. 마지막으로 그린 날, 천장에서 무언가 내려왔다. 그린 이는 그걸 보면서 마지막 붓질을 했다.<br>다른 인형들은 다 웃는다. 겁에 질린 인형만 진짜 얼굴이다. 그 낯이 보는 쪽, 천장 실이 굵은 자리를 일행에게 일렀다.<br><br>실이 내려오기 전에 다들 비켜 섰다.`,
        ng:`읽는 사이 웃는 낯들이 이쪽으로 고개를 돌렸다.<br><br>그려진 웃음이 그대로 다가온다. 이가 그림 아래서 드러났다.<br>뒷걸음질 치다 선반을 쓰러뜨렸다. 깨진 사기에 다리가 베였다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-8 } },
      { l:'② 겁에 질린 인형을 품에 안고 간다.', k:'bond', dc:14,
        ok:`겁에 질린 인형을 안았다. 깨지 않았다.<br><br>그 인형은 이가 없다. 그린 이가 마지막 날 다 못 박았다.<br>품에 안긴 낯이 조금 풀렸다. 그림인데.<br><br>나중에 그 인형 등에 숨겨진 칸을 찾았다. 그린 이의 꿀 종지가 있었다.`,
        ng:`안는 순간 인형이 무거워졌다. 사람만큼.<br><br>품에서 버둥거렸다. 이 없는 입으로 이쪽 어깨를 물었다. 아프지 않은데 끔찍했다.<br>내려놓고 한참 손을 비볐다.`,
        win:{ exp:14, item:'꿀 한 줌' }, lose:{ spirit:-10, mind:-6 } }
    ] },

  { at:'C2', t:'인형 공방 — 웃는 이',
    x:`인형들이 웃는다. 입술을 벌려 이를 보인다. 진짜 이다.<br><br>
      그린 웃음과 박은 이가 안 맞는다. 그린 웃음은 다 같은데 이를 드러내는 폭이 다르다.<br>
      웃음의 폭은 사람마다 다르다. 이를 박은 사람의 웃음이 인형에 옮았다.<br><br>
      웃음이 넓어지는 인형이 있다. 물기 직전의 낯이다.`,
    o:[
      { l:'① 웃음의 폭으로 다음에 무는 것을 짚는다.', k:'gaze', dc:15,
        ok:`웃음을 셌다. 송곳니까지 보이는 것, 어금니까지 보이는 것. 어금니까지 보이는 것이 셋이다.<br><br>짐승은 물기 전에 입이 벌어진다. 인형도 짐승처럼 먹는다. 셋을 일렀다. 일행 창이 셋의 입에 먼저 들어갔다. 사기가 깨지고 이가 쏟아졌다.<br>나머지 인형들의 웃음이 좁아졌다.<br><br>얼굴이 아닌 것에서 얼굴을 읽었다. 그려진 것과 박힌 것 사이의 어긋남이 낯이다. 이쪽 눈은 이제 낯이 없는 데서도 낯을 찾는다.`,
        ng:`세다가 하나를 놓쳤다. 넷이었다.<br><br>넷째가 이쪽 손등을 물었다. 사기 이가 박혔다.<br>깨서 빼냈다. 손등에 웃음 모양 자국이 남았다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-14, mind:-6 }, wake:1 },
      { l:'② 내공으로 몸을 가볍게 해 선반 사이를 빠진다.', k:'evade', dc:14, cost:{ qi:16 },
        ok:`내공을 끌어올려 발을 가볍게 했다. 소리 없이 선반 사이를 지났다.<br><br>인형들은 소리를 듣고 고개를 돈다. 소리가 없으니 웃음만 넓어졌다 좁아졌다 했다.<br>끝까지 빠져나갔다. 뒤에서 인형들이 서로를 물었다. 배고파서.<br><br>남의 배고픔은 남이 처리한다.`,
        ng:`내공이 흔들렸다. 발끝이 선반에 닿았다.<br><br>사기가 울렸다. 전부 이쪽을 봤다. 전부 웃었다.<br>뛰었다. 발목에 셋이 매달렸다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C2', t:'인형 공방 — 천장 구멍의 손',
    x:`공방 천장에 구멍이 있다. 위층으로 통한다. 실이 다 거기서 내려온다.<br><br>
      구멍 가장자리에 손 둘이 보인다. 손가락이 길다. 실을 쥐고 놀린다. 얼굴은 안 보인다.<br>
      얼굴이 없으면 손을 본다. 손도 상이다. 손가락 마디가 굵은 쪽이 많이 쓰는 쪽이다.<br><br>
      실이 내려온다. 인형 열둘이 일어선다.`,
    o:[
      { l:'① 손을 읽어 어느 실이 정말 부리는 실인지 가린다.', k:'gaze', dc:14,
        ok:`오른손은 여러 실을 쥐었는데 마디가 가늘다. 보여 주는 손이다.<br><br>왼손은 실 하나만 쥐었다. 마디가 굵다. 그 실이 다른 실들의 매듭으로 간다. 정말 부리는 손이다.<br>「왼손 실.」 일행 하나가 그 실을 잘랐다. 인형 열둘이 한꺼번에 주저앉았다.<br><br>위층에서 왼손이 주먹을 쥐었다.`,
        ng:`오른손이 바쁘니 그쪽이라 봤다.<br><br>오른손 실을 잘랐다. 인형 하나가 주저앉았다. 나머지 열하나는 그대로다.<br>열하나를 받아 내느라 다들 다쳤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
      { l:'② 내공을 손끝에 모아 실의 떨림을 짚는다.', k:'sense', dc:15, cost:{ qi:18 },
        ok:`내공을 손끝에 모아 가까운 실 하나를 가볍게 짚었다.<br><br>실이 떤다. 위층 손의 맥이 실을 타고 온다. 맥이 빨라지는 순간이 실을 당기는 순간이다.<br>맥이 빨라질 때마다 「온다」 하고 일렀다. 일행이 그때마다 비켰다. 인형들은 허공만 물었다.<br><br>얼굴 대신 맥을 읽었다. 손끝이 낯을 대신했다.`,
        ng:`짚는 순간 위층 손이 이쪽 맥을 읽었다.<br><br>실이 손끝에 감겼다. 당긴다. 팔이 천장으로 들렸다.<br>잘라 내고 떨어졌다. 어깨가 결린다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-12, spirit:-8 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 거꾸로 걸린 성인상',
    x:`기둥마다 성인상이 거꾸로 매달렸다. 돌로 깎은 낯이다.<br><br>
      낯이 다 이쪽을 본다. 거꾸로 걸렸는데 눈은 바로 떴다. 아래를 보게 깎은 것이 아니다. 고개를 돌렸다.<br>
      돌의 표정은 안 바뀐다. 바뀌었다면 깎은 뒤에 무언가 들어앉았다.<br><br>
      상 하나의 입꼬리에서 돌가루가 떨어진다. 움직였다.`,
    o:[
      { l:'① 표정이 바뀐 상을 가린다.', k:'gaze', dc:14,
        ok:`깎은 표정은 고르다. 정이 지난 자리가 매끈하다. 바뀐 표정은 금이 간다.<br><br>입꼬리에 금이 간 상이 셋이다. 그 셋 밑을 피해 걸었다.<br>지나고 나서 뒤에서 돌 셋이 떨어졌다. 이쪽이 지날 자리를 노렸던 셋이다.<br><br>돌로 된 낯도 마음먹으면 금이 간다.`,
        ng:`가리다 거꾸로 된 낯이 헷갈렸다. 입꼬리가 올라간 건지 내려간 건지.<br><br>틀린 상을 믿었다. 그 밑을 지나는데 돌이 떨어졌다.<br>어깨를 스쳤다. 팔이 한참 안 올라갔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-4 } },
      { l:'② 고개를 숙이고 상과 눈을 맞추지 않는다.', k:'steady', dc:14,
        ok:`고개를 숙였다. 다들 따라 했다.<br><br>눈을 안 맞추면 돌은 노릴 자리를 모른다. 사람 낯을 보고 노린다.<br>숙인 채 늑골을 따라 걸었다. 목이 아팠다.<br><br>머리 위에서 돌들이 서로 소곤거렸다. 아무것도 안 떨어졌다.`,
        ng:`숙였는데 일행 하나가 고개를 들었다. 소리가 나서.<br><br>그 사람 머리 위로 돌이 떨어졌다. 이쪽이 밀쳐 냈다.<br>둘 다 늑골에 부딪혔다.`,
        win:{ exp:14, spirit:6 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 입이 많은 낯',
    x:`성가대원 하나가 거꾸로 매달려 노래한다. 얼굴 하나에 입이 여럿이다. 볼에, 턱에, 이마에.<br><br>
      모든 입이 노래한다. 그런데 관상가가 보기에 원래 입은 하나다. 인중 아래, 코와 턱 사이.<br>
      원래 입은 노래를 안 한다. 다물려 있다.<br><br>
      노래가 커질 때마다 늑골이 떤다.`,
    o:[
      { l:'① 원래 입을 가려 그 입을 열게 한다.', k:'gaze', dc:15,
        ok:`인중 아래 입을 봤다. 다물려 있는데 입술이 떨린다. 하고 싶은 말이 있다.<br><br>다른 입들은 원래 입을 누르고 노래한다. 원래 입이 열리면 노래가 무너진다. 그 입을 향해 「말해 보시오」 하고 불렀다.<br>원래 입이 열렸다. 「그만.」 한 마디. 다른 입들이 일제히 멎었다. 성가대원이 늘어졌다.<br><br>많은 입 가운데 하나를 고르는 법. 인중과 턱의 자리는 무엇이 덧붙어도 안 바뀐다. 얼굴이 아무리 망가져도 처음의 자리는 남는다. 이쪽 눈은 그 처음을 먼저 찾는다.`,
        ng:`원래 입을 찾는데 입들이 자리를 옮긴다.<br><br>인중 아래에 있던 입이 이마로 갔다. 어느 게 처음인지 모르겠다.<br>노래가 귀를 찢었다. 다들 엎드렸다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-12, spirit:-8 }, wake:1 },
      { l:'② 내공으로 귀를 감싸고 다른 입들을 친다.', k:'break', dc:15, cost:{ qi:20 },
        ok:`내공을 끌어올려 귀를 감쌌다. 노래가 멀어졌다.<br><br>창을 들고 이마 입부터 찔렀다. 그다음 볼. 턱.<br>입이 하나씩 다물렸다. 마지막에 원래 입만 남았다. 그 입이 숨을 쉬었다. 고맙다는 숨.<br><br>내공이 많이 들었다. 귀는 멀쩡하다.`,
        ng:`내공이 노래에 흔들렸다. 귀 한쪽이 열렸다.<br><br>그쪽으로 노래가 쏟아졌다. 창이 빗나갔다.<br>한참 한쪽 귀가 안 들렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-10, mind:-12 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 거꾸로 선 일행',
    x:`늑골 위를 걷는 동안 일행 얼굴이 이상하게 보인다. 거꾸로 선 성당 탓이다. 피가 머리로 몰려 다들 볼이 붉다.<br><br>
      그래도 낯은 읽힌다. 다섯 다 지쳤다. 겁이 났다. 그게 맞다.<br>
      그런데 하나는 볼이 안 붉다. 거꾸로 서도 피가 안 몰린다.<br><br>
      그 사람이 앞장서겠다고 한다.`,
    o:[
      { l:'① 피가 안 도는 낯의 나머지를 읽는다.', k:'gaze', dc:15,
        ok:`그 사람 귀를 봤다. 귓불이 위로 처졌다. 거꾸로 선 성당에서 아래로 처진 것이다. 이 사람은 처음부터 거꾸로 서 있었다.<br><br>성당과 같은 쪽이다. 성당 쪽 것이다.<br>「앞장서지 마시오.」 그것이 웃었다. 일행 얼굴로. 그리고 늑골 사이로 거꾸로 떨어져, 아니, 올라갔다.<br><br>진짜 그 사람은 뒤쪽 늑골에 매달려 있었다. 끌어 올렸다.`,
        ng:`읽는 사이 그 사람이 앞장섰다.<br><br>이쪽이 뒤따랐다. 그 사람이 늑골 사이 판을 밟았다. 판이 깨졌다. 그 사람은 안 떨어졌다. 이쪽이 떨어질 뻔했다.<br>일행이 붙잡았다. 정강이가 깨졌다.`,
        win:{ exp:20, dream:2, spirit:5 }, lose:{ hp:-14, spirit:-8 } },
      { l:'② 손을 잡게 하고 체온을 센다.', k:'bond', dc:14,
        ok:`다섯이 손을 잡았다. 따뜻한 손, 따뜻한 손, 따뜻한 손.<br><br>넷째 손이 차다. 이쪽 왼쪽이다. 그 손을 놓고 그 사람을 맨 뒤로 보냈다. 거기서 그것은 할 일이 없다.<br>성당을 나설 때 그 손은 이미 없었다. 뒤쪽 늑골에 진짜 넷째가 기다리고 있었다.<br><br>얼굴은 흉내 내도 체온은 못 낸다.`,
        ng:`손을 잡게 했는데 다 따뜻하다.<br><br>그것은 손까지 흉내 냈다. 아무도 못 가렸다.<br>그날 성당에서 일행 하나가 늑골을 헛디뎠다. 겨우 붙잡았다.`,
        win:{ exp:14, spirit:6 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C4', t:'포자 온실 — 귀 끝의 흰 솜털',
    x:`온실을 지날수록 다들 기침을 한다. 포자다.<br><br>
      일행 낯빛을 본다. 들이마신 것은 먼저 낯빛에 핀다. 뺨이 아니라 귀 끝이다.<br>
      한 사람 귀 끝이 하얗다. 솜털처럼 보송보송하다.<br><br>
      그 사람은 기분이 좋다고 한다. 숨이 달다고.`,
    o:[
      { l:'① 낯빛으로 포자가 어디까지 들었는지 가린다.', k:'gaze', dc:14,
        ok:`귀 끝, 콧방울, 눈 밑. 하얀 것이 귀 끝에만 있다. 아직 귀까지다.<br><br>귀 끝에 들면 아직 밖이다. 콧방울에 들면 숨으로 들어간다. 눈 밑에 들면 늦다.<br>귀 끝을 소금물로 문질러 씻었다. 하얀 솜털이 떨어졌다. 그 사람이 기분이 덜 좋다고 했다. 다행이다.<br><br>다른 넷도 차례로 봤다. 콧방울이 하얀 사람은 없다.`,
        ng:`귀 끝만 봤다. 콧방울을 늦게 봤다.<br><br>콧방울도 하얗다. 이미 숨으로 들었다.<br>그 사람이 웃기 시작했다. 멈추게 하는 데 다들 진이 빠졌다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-10, mind:-10 } },
      { l:'② 내공으로 그 사람의 기를 돌려 포자를 밀어낸다.', k:'heal', dc:15, cost:{ qi:20 },
        ok:`그 사람 등에 손바닥을 대고 내공을 흘렸다. 귀 끝 쪽으로 기를 몰았다.<br><br>기가 지나는 길에 하얀 것이 밀려 나온다. 귀 끝에서 솜털이 피었다가 떨어졌다. 다시 피었다. 다시 떨어졌다.<br>세 번째에 더는 안 피었다. 그 사람 귀가 붉어졌다.<br><br>낯빛에 핀 것을 낯빛이 나오는 자리로 거꾸로 밀어낸다. 보이는 데로 들어온 것은 보이는 데로 나간다. 읽기만 하던 낯빛을 처음으로 고쳤다.`,
        ng:`내공이 들어가자 포자가 기를 타고 번졌다. 귀 끝에서 콧방울로.<br><br>멈췄다. 그 사람이 하얗게 웃었다.<br>소금물로 한참을 씻겼다. 이쪽 손바닥도 하얘졌다.`,
        win:{ exp:22, dream:3, spirit:5 }, lose:{ hp:-12, spirit:-10 }, wake:1 }
    ] },

  { at:'C4', t:'포자 온실 — 버섯 갓의 낯',
    x:`화단 가장자리에 버섯이 돋았다. 갓이 손바닥만 하다.<br><br>
      갓 무늬가 얼굴 같다. 눈 둘, 입 하나. 버섯마다 표정이 다르다.<br>
      관상가는 웃음이 났다. 버섯 관상은 처음이다. 그런데 보다 보니 웃을 일이 아니다. 낯마다 상이 있다.<br><br>
      한 무리만 낯이 순하다.`,
    o:[
      { l:'① 순한 낯의 버섯을 고른다.', k:'gaze', dc:14,
        ok:`순한 낯은 눈매가 처졌다. 사납지 않다. 독이 없는 것이다. 무늬는 독을 따라 선다.<br><br>사나운 낯은 눈꼬리가 위로 찢어졌다. 그건 건드리지 않았다.<br>순한 것만 한 줌 땄다. 갓 뒤가 깨끗하다. 실이 안 붙었다.<br><br>버섯도 낯대로 산다.`,
        ng:`순한 낯이라고 땄는데 뒤집으니 갓 안쪽에도 낯이 있다. 사납다.<br><br>앞낯과 뒷낯이 다르다. 손이 저렸다.<br>버리고 한참 손을 씻었다.`,
        win:{ exp:14, item:'야생 버섯' }, lose:{ hp:-10, mind:-8 } },
      { l:'② 낯 없는 버섯을 찾는다.', k:'luck', dc:14,
        ok:`낯이 있는 버섯은 무언가 먹고 자란 것이다. 낯은 먹은 것에서 온다.<br><br>화단 구석, 쇠 물통 그늘에 낯 없는 버섯이 몇 있다. 그냥 버섯이다.<br>그 옆에 산나물도 났다. 버섯 실이 안 닿는 데라서.<br><br>낯 없는 것이 제일 안전하다.`,
        ng:`낯 없는 버섯을 찾아 구석에 손을 넣었다.<br><br>손가락에 무언가 닿았다. 낯 없는 버섯 밑에 낯이 있었다. 사람 낯이.<br>손을 빼고 한참 아무 말도 못 했다.`,
        win:{ exp:12, item:'산나물' }, lose:{ spirit:-12, mind:-6 } }
    ] },

  { at:'C4', t:'포자 온실 — 한가운데의 낯들',
    x:`온실 한가운데 큰 것이 자랐다. 물탱크를 감싸고 천장까지 닿는다.<br><br>
      겉에 얼굴들이 박혀 있다. 정원사들의 낯이다. 수십 개. 다 눈을 감았다.<br>
      관상가는 낯을 그냥 못 지나간다. 저 많은 낯 가운데 하나라도 아직 살아 있을지 모른다.<br><br>
      가운데 낯 하나가 눈을 반쯤 뜨고 있다.`,
    o:[
      { l:'① 다가가 반쯤 뜬 눈의 낯을 끝까지 읽는다.', k:'gaze', dc:15,
        doom:{ title:'한가운데의 낯', what:'큰 것의 겉으로 빨려 들어갑니다', dc:15, sec:55,
          text:`가까이 갔다. 반쯤 뜬 눈. 인당이 맑다. 산 사람 낯이다. 그렇게 보였다.<br><br>읽는 사이 그 눈이 다 떠졌다. 눈동자가 허옇다. 미끼의 낯이다. 둘레의 낯들이 일제히 눈을 떴다.<br>발밑에서 실이 솟아 다리를 감았다. 등이 큰 것의 겉에 닿았다. 부드럽다. 몸이 그 안으로 가라앉는다.<br><br>이쪽 얼굴이 겉에 자리를 잡는다. 눈이 감긴다.`,
          dieText:`온실 한가운데 큰 것의 겉에 얼굴들이 박혀 있다.<br><br>수십 개. 하나가 늘었다. 상이 좋다.<br>그 낯은 눈을 반쯤 뜨고 있다.` },
        ok:`열 걸음 밖에서 읽었다. 거기까지만.<br><br>반쯤 뜬 눈 아래 눈 밑이 허옇다. 눈 밑에 들면 늦다. 저 낯은 이미 큰 것이다. 이쪽을 부르려고 뜬 눈이다.<br>일행에게 저 낯을 보지 말라고 했다. 그리고 그 낯이 박힌 자리 아래, 줄기가 갈라지는 데를 가리켰다. 다른 낯들이 다 그쪽에서 실을 받는다.<br><br>나중에 칠 자리를 그렇게 찾았다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 내공을 단단히 두르고 눈을 피한 채 지난다.', k:'steady', dc:15, cost:{ qi:20 },
        ok:`내공을 온몸에 둘렀다. 숨을 고르게 했다.<br><br>큰 것 옆을 지나는 동안 낯들이 이쪽을 불렀다. 낯을 보라고. 보지 않았다. 발끝만 봤다.<br>몸을 감싼 내공이 실을 튕겨 냈다. 다리에 감기려던 것들이 떨어졌다.<br><br>지나고 나서 숨을 쉬었다. 길게.`,
        ng:`내공이 흩어지는 틈에 낯 하나와 눈이 맞았다.<br><br>무릎이 풀렸다. 실이 정강이를 감았다. 일행이 끌어냈다.<br>정강이에 허연 자국이 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-10 } }
    ] },

  { at:'C', t:'방 — 짐승의 눈꼬리',
    x:`어둠에서 짐승 하나가 몸을 낮췄다. 늑대보다 크다. 눈이 노랗다.<br><br>
      일행 창 다섯이 그것을 겨눈다. 그것은 다섯을 하나씩 본다.<br>
      눈꼬리를 본다. 뛰기 전에 짐승은 눈이 먼저 간다. 노리는 쪽으로.<br><br>
      눈꼬리가 아주 조금 떨린다.`,
    o:[
      { l:'① 눈꼬리가 가는 쪽을 읽어 뛸 때를 알린다.', k:'gaze', dc:15,
        ok:`눈이 넷째 사람에게 간다. 가장 지친 사람이다. 눈꼬리가 떨리다 멎었다. 멎으면 뛴다.<br><br>「넷째, 지금.」 넷째가 반 걸음 물러섰고 다른 넷의 창이 넷째 앞으로 모였다. 짐승이 뛰었다. 창 넷 위로.<br>짐승이 쓰러지고 나서야 다들 숨을 쉬었다.<br><br>낯이 정하는 것을 낯보다 먼저 읽었다. 눈꼬리가 떨리다 멎는 그 한순간. 이제 그 순간을 셈으로 안다. 하나, 둘에 멎으면 셋에 온다.`,
        ng:`눈꼬리를 보는데 짐승이 눈을 감았다.<br><br>감은 눈으로 뛰었다. 읽을 낯이 없었다.<br>넷째가 넘어졌다. 다 같이 덮쳐 겨우 떼어 냈다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 }, wake:1 },
      { l:'② 짐승과 눈을 맞추고 버틴다.', k:'steady', dc:15,
        ok:`앞으로 나섰다. 짐승 눈을 똑바로 봤다.<br><br>짐승이 이쪽만 봤다. 다른 넷은 잊었다. 그 넷이 옆으로 돌았다.<br>짐승이 이쪽을 향해 뛰는 순간 옆에서 창이 들어갔다.<br><br>무서웠다. 얼굴에 안 드러냈다.`,
        ng:`눈을 맞추는데 얼굴에 겁이 드러났다.<br><br>짐승이 그걸 읽었다. 이쪽에게 왔다. 빨랐다.<br>어깨를 물렸다. 넷이 떼어 냈다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-18, spirit:-6 } }
    ] },

  { at:'C', t:'방 — 앞서는 사람의 낯빛',
    x:`일행 하나가 앞장선다. 아까 짐승 하나를 혼자 잡았다. 그 뒤로 걸음이 빠르다.<br><br>
      낯빛을 본다. 눈동자가 크다. 콧방울이 벌렁인다. 살기가 너무 올랐다.<br>
      살기가 오른 사냥꾼은 사냥감을 너무 빨리 쫓는다. 그러다 사냥감이 놓은 덫을 밟는다.<br><br>
      앞쪽 어둠에서 다친 짐승 우는 소리가 난다. 그 사람이 그쪽으로 뛰려 한다.`,
    o:[
      { l:'① 그 사람의 낯빛을 짚어 붙잡는다.', k:'gaze', dc:14,
        ok:`어깨를 잡고 돌려세웠다. 「눈이 너무 크오.」<br><br>그 사람이 멈칫했다. 제 얼굴을 만졌다. 숨을 쉬었다. 콧방울이 가라앉았다.<br>다 같이 천천히 다가갔다. 우는 소리가 나는 자리 앞에 구덩이가 있다. 우는 건 짐승이 아니라 구덩이 밑에서 짐승 흉내를 내는 것이었다.<br><br>구덩이를 돌아갔다. 그 사람이 고맙다는 말은 안 했다. 얼굴이 했다.`,
        ng:`붙잡았는데 그 사람이 뿌리쳤다. 살기가 이쪽에게도 튀었다.<br><br>둘이 엉켜 넘어졌다. 그 사이 우는 소리가 가까이 왔다.<br>구덩이 가장자리에서 겨우 멈췄다. 둘 다 긁혔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-8 } },
      { l:'② 말없이 그 사람 옆에 붙어 걷는다.', k:'bond', dc:14,
        ok:`아무 말 없이 그 사람 옆에 붙었다. 걸음을 맞췄다. 조금 느리게.<br><br>그 사람 걸음이 저도 모르게 이쪽을 따라 느려졌다.<br>느린 걸음이라 구덩이를 봤다. 둘이 같이 봤다.<br><br>낯빛은 옆 사람 걸음으로도 바뀐다.`,
        ng:`붙어 걸었는데 그 사람이 이쪽을 앞질렀다.<br><br>구덩이 가장자리를 밟았다. 이쪽이 허리를 잡았다.<br>둘이 같이 미끄러지다 겨우 멈췄다.`,
        win:{ exp:14, spirit:6 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C', t:'방 — 낯 없는 것',
    x:`그것에게는 얼굴이 없다. 머리 자리가 둥글고 매끈하다. 눈도 입도 없다.<br><br>
      관상가는 처음으로 막막하다. 읽을 낯이 없다.<br>
      그것이 일행 사이를 천천히 돈다. 어디를 노리는지 아무도 모른다.<br><br>
      낯이 없으면 무엇을 보아야 하는가.`,
    o:[
      { l:'① 낯 대신 몸의 상을 읽는다.', k:'gaze', dc:16,
        ok:`낯이 아니라 어깨를 봤다. 사람은 노리는 쪽으로 어깨가 먼저 간다. 짐승도 그렇다.<br><br>그것의 왼쪽 어깨가 조금 내려앉았다. 둘째 사람 쪽이다. 걸음이 그쪽에서만 짧아진다. 「둘째, 왼쪽.」 둘째가 비켰다. 그것이 허공을 쳤다. 친 팔이 다 펴진 순간 창 셋이 들어갔다.<br><br>얼굴이 없어도 상은 있다. 어깨, 걸음, 무릎. 몸 전체가 하나의 낯이다. 낯을 읽던 눈이 몸을 읽는 눈으로 넓어졌다.`,
        ng:`몸을 읽으려는데 그것의 몸이 고르다. 어디도 기울지 않는다.<br><br>그것이 아무 예고 없이 이쪽을 쳤다. 가슴이 막혔다.<br>숨을 되찾는 데 오래 걸렸다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-8 }, wake:1 },
      { l:'② 내공을 펼쳐 기척으로 다가올 때를 안다.', k:'sense', dc:15, cost:{ qi:18 },
        ok:`눈을 감고 내공을 펼쳤다. 기척이 물결처럼 온다.<br><br>그것이 다가오는 쪽 물결이 진하다. 「셋째 뒤.」 셋째가 돌아서며 창을 냈다. 그것의 둥근 머리에 박혔다.<br>낯이 없으니 보지 않고 느꼈다.<br><br>눈을 떴을 때 그것이 쓰러져 있었다.`,
        ng:`내공을 펼쳤는데 그것에게는 기척도 없다.<br><br>아무것도 안 느껴진다. 그게 제일 무섭다.<br>그것이 이쪽 옆을 스쳤다. 팔이 베였다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-14, spirit:-8 } }
    ] },

  { at:'C', t:'방 — 죽은 척하는 낯',
    x:`잡은 짐승이 쓰러져 있다. 일행이 고기를 떼러 다가간다.<br><br>
      낯을 본다. 죽은 낯은 풀린다. 입꼬리도 눈꺼풀도 제 무게대로 처진다.<br>
      이 짐승은 입꼬리가 조금 당겨져 있다. 힘이 들어갔다.<br><br>
      칼을 든 일행이 그 머리맡에 쪼그려 앉는다.`,
    o:[
      { l:'① 다가가 눈꺼풀을 들춰 확인한다.', k:'gaze', dc:15,
        doom:{ title:'죽은 척', what:'짐승이 물고 어둠으로 끌고 갑니다', dc:15, sec:55,
          text:`일행을 밀어내고 이쪽이 쪼그렸다. 눈꺼풀을 엄지로 들췄다.<br><br>눈동자가 이쪽을 보고 있었다. 처음부터.<br>짐승이 일어나며 이쪽 팔을 물었다. 놓지 않는다. 그대로 뒷걸음질 친다. 어둠 쪽으로. 이쪽이 끌려간다.<br><br>당겨진 입꼬리는 웃음이었다.`,
          dieText:`어둠 속에서 짐승이 다시 쓰러져 있다.<br><br>입꼬리가 조금 당겨져 있다.<br>그 옆에 또 하나가 쓰러져 있다. 그쪽 입꼬리는 다 풀렸다.` },
        ok:`쪼그리지 않았다. 선 채로 입꼬리를 봤다. 당겨져 있다. 오른쪽만.<br><br>오른쪽 송곳니를 드러내려고 힘을 모은 낯이다. 「물러나.」 일행이 물러났다. 짐승이 입을 열고 뛰어올랐다. 아무도 없는 자리를 물었다.<br>창이 그 벌린 입으로 들어갔다. 이번엔 입꼬리가 풀렸다.<br><br>고기는 그 뒤에 뗐다.`,
        win:{ exp:24, dream:3, item:'짐승 고기' } },
      { l:'② 멀찍이서 창으로 찔러 확인한다.', k:'break', dc:14,
        ok:`다가가지 말라고 하고 창끝으로 옆구리를 찔렀다.<br><br>짐승이 벌떡 일어났다. 창이 이미 꽂혀 있다. 일어선 김에 깊이 들어갔다.<br>다시 쓰러졌다. 입꼬리가 풀렸다. 이번엔 진짜다.<br><br>창 하나 길이가 목숨 하나 값이다.`,
        ng:`찔렀는데 창이 미끄러졌다. 짐승이 일어났다.<br><br>창을 놓고 물러났다. 짐승이 머리맡의 일행에게 갔다.<br>그 사람 다리를 물었다. 다 같이 덮쳐 끝냈다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C', t:'방 — 손금 없는 손',
    x:`벽 틈에서 손이 나와 있다. 사람 손처럼 생겼다. 손바닥을 위로.<br><br>
      손금을 본다. 손금이 없다. 하나도.<br>
      손금은 살면서 생긴다. 손금이 없는 손은 막 태어난 손이다.<br><br>
      막 태어난 것은 배가 고프다.`,
    o:[
      { l:'① 손의 나머지 상을 읽어 무엇의 손인지 안다.', k:'gaze', dc:14,
        ok:`손톱이 없다. 마디가 하나 더 많다. 손목이 벽 안으로 너무 길게 이어진다.<br><br>사람 손이 아니다. 손 모양을 배운 것이다. 이쪽 손을 보고 따라 만든다. 그래서 손금이 없다. 손금은 못 따라 한다.<br>일행에게 벽에 손을 대지 말라고 했다. 대면 그 손이 배운다.<br><br>손이 벽 안으로 거둬들어갔다. 배울 게 없었다.`,
        ng:`읽는 사이 손이 이쪽 손을 따라 손가락을 폈다. 똑같이.<br><br>그리고 이쪽 손을 잡았다. 악수하듯이. 세게.<br>빼내는 데 손등이 벽에 갈렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-8 } },
      { l:'② 내공을 손날에 실어 그 손을 내리친다.', k:'break', dc:15, cost:{ qi:18 },
        ok:`내공을 손날에 모았다. 손목을 내리쳤다.<br><br>손이 벽 안으로 튕겨 들어갔다. 벽 안에서 작은 비명이 길게 났다.<br>다시 안 나왔다. 배우기도 전에 배운 것이 하나 있다. 이쪽은 아프다는 것.<br><br>손날이 얼얼했다.`,
        ng:`내리치는데 손이 먼저 손날을 잡았다.<br><br>내공이 그 손으로 빨려 갔다. 팔이 저리다.<br>손이 한 뼘 더 길게 벽 밖으로 나왔다. 다들 물러섰다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C', t:'방 — 쉬어야 할 낯',
    x:`사냥이 길었다. 다들 괜찮다고 한다.<br><br>
      다섯 낯을 차례로 본다. 눈 밑, 입술, 귓불.<br>
      둘은 괜찮다. 하나는 눈 밑이 검다. 하나는 입술이 마르고 갈라졌다. 하나는 귓불이 하얗다.<br><br>
      다음 짐승이 어둠 저쪽에서 숨을 고른다.`,
    o:[
      { l:'① 낯빛대로 자리를 다시 짠다.', k:'gaze', dc:14,
        ok:`눈 밑이 검은 사람은 잠이 모자라다. 맨 뒤에 둔다. 졸면 앞사람이 깨운다.<br><br>입술이 마른 사람은 물이 모자라다. 물통을 넘겼다. 귓불이 하얀 사람은 피가 모자라다. 가운데 둔다. 다치면 바로 싸맨다.<br>괜찮은 둘을 앞에 세웠다.<br><br>짐승이 왔을 때 앞의 둘이 받았다. 아무도 쓰러지지 않았다.`,
        ng:`짜는 사이 짐승이 먼저 왔다.<br><br>귓불 하얀 사람이 앞에 있었다. 받다가 쓰러졌다.<br>다들 그 사람을 끌고 물러났다.`,
        win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-14, mind:-6 } },
      { l:'② 제일 지친 사람과 자리를 바꿔 앞에 선다.', k:'steady', dc:14,
        ok:`귓불 하얀 사람을 뒤로 보내고 그 자리에 섰다.<br><br>제 낯은 제가 못 본다. 그래도 아직은 괜찮다고 믿었다.<br>짐승을 받았다. 버텼다. 일행이 옆에서 끝냈다.<br><br>나중에 물에 비친 이쪽 귓불이 조금 하얬다.`,
        ng:`이쪽도 지쳤다. 그걸 몰랐다.<br><br>짐승을 받다 무릎이 꺾였다.<br>일행이 이쪽을 끌고 물러났다.`,
        win:{ exp:14, spirit:6 }, lose:{ hp:-16, spirit:-6 } },
      { l:'③ 내공을 나눠 가장 하얀 사람의 기를 돋운다.', k:'heal', dc:14, cost:{ qi:16 },
        ok:`귓불 하얀 사람 손을 잡고 내공을 흘렸다.<br><br>귓불이 붉어졌다. 입술에도 핏기가 돌았다.<br>그 사람이 창을 다시 쥐었다. 손에 힘이 있다.<br><br>이쪽 귓불은 대신 조금 하얘졌다. 그 정도는 괜찮다.`,
        ng:`내공을 흘리는데 그 사람 기가 너무 비었다. 이쪽 것이 바닥까지 빨려 갔다.<br><br>둘 다 하얘졌다.<br>짐승이 왔을 때 둘 다 뒤에 있어야 했다.`,
        win:{ exp:16, hp:8, spirit:5 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C', t:'방 — 겁을 흉내 내는 낯',
    x:`어둠 속에 사람이 웅크려 있다. 겁에 질린 얼굴이다. 「도와주시오.」<br><br>
      겁은 많이 봤다. 겁은 눈에서 시작한다. 눈동자가 이리저리 흔들린다. 나갈 데를 찾느라.<br>
      이 얼굴은 겁에 질렸는데 눈동자가 안 흔들린다. 한 곳만 본다. 이쪽 목.<br><br>
      일행 하나가 손을 내민다.`,
    o:[
      { l:'① 겁의 생김새를 하나씩 맞춰 거짓을 가린다.', k:'gaze', dc:15,
        ok:`눈썹은 겁이다. 입은 겁이다. 이마 주름도 겁이다. 눈만 아니다.<br><br>겁 많은 낯을 여럿 보고 흉내 낸 것이다. 눈은 흉내 낼 수 없었다. 배고픈 눈이니까. 내민 손을 잡아 내렸다. 웅크린 것이 겁에 질린 얼굴 그대로 이쪽으로 뛰었다. 일행 창이 먼저 있었다.<br><br>표정 하나하나를 따로 떼어 맞춰 보는 법. 하나만 어긋나도 전부가 거짓이다. 얼굴을 한 덩어리로 보던 버릇을 버리고 조각으로 가르는 눈을 얻었다.`,
        ng:`맞춰 보는 사이 일행이 손을 잡았다.<br><br>웅크린 것이 그 손을 놓지 않았다. 당겼다. 어둠 쪽으로.<br>다 같이 매달려 떼어 냈다. 손목에 이 자국이 났다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-14, spirit:-8 }, wake:1 },
      { l:'② 등불을 끄고 다 같이 물러난다.', k:'hide', dc:14,
        ok:`등불을 껐다. 얼굴이 안 보이면 흉내 낼 낯도 없다.<br><br>어둠 속에서 「도와주시오」가 몇 번 더 들렸다. 점점 덜 사람 같아졌다.<br>더듬어 물러났다. 그것은 낯을 볼 수 없어 쫓아오지 못했다.<br><br>멀리 가서 불을 켰다. 다섯이었다.`,
        ng:`등불을 끄자 그것이 기다렸다는 듯 다가왔다. 어둠은 그것의 것이다.<br><br>목덜미에 숨이 닿았다.<br>불을 다시 켰다. 바로 앞이었다. 다 같이 쳐서 겨우 쫓았다.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C', t:'방 — 읽히는 낯',
    x:`사냥이 이어질수록 짐승들이 이쪽을 먼저 노린다.<br><br>
      이유는 안다. 짐승도 낯을 읽는다. 이쪽 낯에 「안다」가 쓰여 있다. 아는 낯은 위협이다.<br>
      앞의 어둠에 큰 것이 기다린다. 이쪽 낯을 보고 있다.<br><br>
      읽는 쪽이 읽히고 있다.`,
    o:[
      { l:'① 낯을 비우고 큰 것을 읽는다.', k:'gaze', dc:16,
        ok:`이마의 힘을 뺐다. 눈가의 힘을 뺐다. 입꼬리를 제 무게대로 두었다. 아무것도 모르는 낯.<br><br>큰 것이 이쪽을 지나쳐 다른 데를 봤다. 그사이 그것을 다 읽었다. 숨, 어깨, 눈꼬리. 왼쪽 뒷다리를 아낀다. 다쳤다.<br>「왼쪽 뒤.」 일행이 그리로 갔다. 큰 것이 무너졌다.<br><br>남의 낯을 읽는 만큼 제 낯을 감추는 법. 읽히지 않는 낯으로 읽는다. 이쪽 얼굴은 이제 이쪽이 정한다.`,
        ng:`낯을 비우려는데 비울수록 무엇을 감추는지 드러났다.<br><br>큰 것이 이쪽만 봤다. 곧장 왔다.<br>일행이 막았다. 둘이 크게 다쳤다.`,
        win:{ exp:24, dream:4 }, lose:{ hp:-16, mind:-8 }, wake:1 },
      { l:'② 내공으로 기세를 일으켜 일부러 이쪽에 눈을 끈다.', k:'steady', dc:15, cost:{ qi:22 },
        ok:`내공을 끌어올려 기세를 한껏 밀었다. 여기 있다고.<br><br>큰 것이 이쪽만 봤다. 이쪽이 미끼가 되었다. 나머지 넷이 어둠을 돌아 옆으로 갔다.<br>큰 것이 이쪽을 향해 뛰는 순간 옆에서 창이 들어갔다.<br><br>읽히는 낯은 미끼로 쓴다.`,
        ng:`기세가 너무 셌다. 큰 것이 겁을 먹었다.<br><br>겁먹은 짐승은 미친다. 사방으로 날뛰었다.<br>다들 다쳤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-8 } }
    ] }
]);

// ── 탐정 (자원 없음)
kJob('detective', 'C', [
  { at:'C1', t:'도축장 — 멈춘 자리',
    x:`갈고리 레일 아래 바닥에 기름 자국이 고르게 떨어져 있다. 줄이 지나며 흘린 것이다.<br><br>
      자국 사이가 한 뼘씩이다. 줄은 늘 같은 빠르기로 간다.<br>
      탐정은 고른 것 사이에서 고르지 않은 것을 찾는다. 한 자리에만 기름이 둥글게 고였다.<br><br>
      줄이 거기서 한 번 멈췄다. 오래.`,
    o:[
      { l:'① 줄이 멈췄던 까닭을 맞춰 본다.', k:'gaze', dc:14,
        ok:`고인 자리 바로 위 갈고리가 휘었다. 무거운 것이 걸렸다. 너무 무거워서 줄이 섰다.<br><br>고인 자리 옆 바닥에 커다란 발자국이 있다. 칼질하는 것의 발이다. 줄이 서면 그것이 직접 와서 걸린 것을 내렸다. 그때만 그것은 레일 끝을 떠난다.<br>일행 하나에게 휜 갈고리에 매달리게 했다. 줄이 섰다. 그것이 왔다. 기다리던 넷이 옆에서 덮쳤다.<br><br>자국 하나로 그것이 언제 어디로 오는지를 정했다. 지난 일을 맞추는 것으로 다음 일을 부를 수 있다. 증거가 덫이 되었다.`,
        ng:`맞추다 보니 고인 자리가 둘이다. 하나는 새것이다.<br><br>새것이 방금 생겼다. 이쪽이 서 있는 자리 위다.<br>올려다봤을 때 갈고리가 내려오고 있었다. 비켰는데 어깨를 찍혔다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 }, wake:1 },
      { l:'② 기름 자국을 따라 줄이 끝나는 데를 찾는다.', k:'sense', dc:14,
        ok:`자국을 따라갔다. 레일 끝에 작은 방이 있다. 기름통과 소금 포대가 쌓였다.<br><br>줄이 끝나는 데는 늘 무언가 쌓인다.<br>소금 덩이 하나를 챙겼다. 기름통 뒤에서 무언가 숨을 죽였다.<br><br>모른 척 나왔다.`,
        ng:`따라가다 기름에 미끄러졌다. 레일 아래로.<br><br>머리 위로 갈고리 줄이 지나간다. 엎드려 기다렸다.<br>마지막 갈고리가 등을 긁고 갔다.`,
        win:{ exp:14, item:'소금 덩이' }, lose:{ hp:-12, mind:-6 } }
    ] },

  { at:'C1', t:'도축장 — 출근 카드',
    x:`문 옆에 출근 카드가 꽂혀 있다. 마흔 장.<br><br>
      들어온 시각이 찍혔다. 나간 시각 칸은 다 비었다. 한 장만 빼고.<br>
      탐정은 그 한 장을 뽑았다. 들어온 날은 다른 카드와 같다. 나간 시각은 들어온 지 세 시간 뒤다.<br><br>
      세 시간 뒤면 종이 울린 때다.`,
    o:[
      { l:'① 나간 사람의 길을 맞춰 본다.', k:'gaze', dc:14,
        ok:`카드 뒷면에 흙이 묻었다. 도축장 바닥은 타일이다. 흙은 마당에만 있다.<br><br>그 사람은 정문으로 안 나갔다. 마당으로 나갔다. 마당 쪽 벽에 개구멍이 있을 것이다.<br>종이 울릴 때 모두 줄을 섰다. 그 사람만 줄을 안 서고 마당으로 갔다.<br><br>개구멍이 있었다. 그 옆에 버려진 앞치마. 주머니에 말린 고기. 도망치는 사람은 짐을 버린다.`,
        ng:`맞추다 카드 하나가 저절로 찍혔다. 찰칵.<br><br>나간 시각이 아니다. 들어온 시각이다. 이쪽 일행 수만큼.<br>그 뒤로 내내 종소리를 기다리게 되었다. 신경이 곤두섰다.`,
        win:{ exp:18, item:'말린 고기' }, lose:{ mind:-10, spirit:-8 } },
      { l:'② 비어 있는 카드 꽂이를 살핀다.', k:'luck', dc:13,
        ok:`마흔 칸 옆에 빈 칸이 다섯 있다. 새 카드가 놓였다. 이름 칸이 비었다.<br><br>이쪽 일행 수다. 누가 준비해 두었다.<br>다섯 장을 다 뽑아 찢었다. 찢은 카드 밑에 약초 한 묶음이 끼어 있었다. 첫날 받는 구급품이다.<br><br>출근은 안 하기로 했다. 약초만 받았다.`,
        ng:`빈 칸을 들여다보는데 카드가 한 장 저절로 꽂혔다.<br><br>이름 칸에 이쪽 글씨로 무언가 적혀 있다.<br>뽑으려는데 안 빠진다. 손가락만 베였다.`,
        win:{ exp:12, item:'약초 뭉치' }, lose:{ hp:-8, spirit:-10 } }
    ] },

  { at:'C1', t:'도축장 — 같은 귀표',
    x:`갈고리마다 고기에 귀표가 붙어 있다. 소 귀에 다는 쇠 표다.<br><br>
      번호가 다 같다. 0417. 마흔 개 모두.<br>
      같은 번호는 하나를 뜻한다. 마흔 마리가 아니다. 한 마리가 마흔 번 걸렸다.<br><br>
      그러면 처음 걸린 한 마리가 어딘가 있다.`,
    o:[
      { l:'① 0417의 처음 자리를 찾아 가서 확인한다.', k:'gaze', dc:15,
        doom:{ title:'0417', what:'처음 걸린 것에게 붙잡혀 레일로 끌려갑니다', dc:15, sec:55,
          text:`귀표의 녹을 비교했다. 제일 녹슨 것을 찾아갔다. 레일 맨 처음, 기둥 뒤 어두운 갈고리.<br><br>처음 걸린 것은 소가 아니다. 소 모양으로 살을 기운 것이다. 마흔 번 잘려도 안 죽는 것. 마흔 고기가 다 이것에서 자랐다.<br>그것이 고개를 들었다. 귀표가 짤랑였다. 갈고리째 내려와 이쪽 허리를 감았다. 레일이 움직인다. 이쪽이 줄에 걸린다.<br><br>귀표 하나가 새로 찍힌다. 0417.`,
          dieText:`갈고리마다 고기에 귀표가 붙어 있다.<br><br>번호가 다 같다. 0417. 마흔한 개.<br>하나는 귀가 사람 모양이다.` },
        ok:`녹을 비교해 처음 것을 찾았다. 가지는 않았다. 기둥 너머로 등불만 비췄다.<br><br>기둥 뒤 갈고리에 기운 살덩이가 매달렸다. 귀표가 제일 녹슬었다. 마흔 고기가 이것에서 자랐다. 처음을 끝내면 뒤는 다 끝난다.<br>일행 셋이 창을 길게 들고 기둥 양쪽에서 한꺼번에 찔렀다. 살덩이가 울었다. 레일의 고기 마흔 덩이가 한꺼번에 식었다.<br><br>사건은 늘 처음 것 하나에서 번진다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 귀표를 다 떼어 번호를 지운다.', k:'fix', dc:14,
        ok:`고기마다 귀표를 떼어 냈다. 마흔 개를 자루에 넣었다.<br><br>번호가 없는 고기는 어디서 자라야 할지 모른다. 돋던 살이 멈췄다.<br>기둥 뒤에서 무언가 제 귀를 더듬는 소리가 났다.<br><br>자루는 무거웠다. 버리지 않고 들고 나왔다. 증거다.`,
        ng:`떼는데 귀표가 살에 박혔다. 떼면 살이 같이 뜯긴다.<br><br>뜯긴 자리가 이쪽 손가락을 물었다.<br>열두 개쯤 떼고 손이 다 갈렸다. 멈췄다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } },
      { l:'③ 고기 하나를 떼어 들고 빠져나간다.', k:'luck', dc:14,
        ok:`갈고리 하나에서 고기를 떼었다. 번호가 다 같다면 아무 데서나 떼도 같다.<br><br>멀리 가져가자 살이 더 안 자랐다. 처음 것에서 멀어지면 그냥 고기다.<br>불에 그을렸다. 냄새가 바르다.<br><br>마흔 번 잡힌 소의 한 점이다. 맛은 소다.`,
        ng:`떼어 든 고기가 손에서 꿈틀거렸다. 처음 것 쪽으로 가려 한다.<br><br>놓쳤다. 고기가 바닥을 기어갔다.<br>쫓다가 갈고리 줄 밑에 들어갔다. 어깨가 찍혔다.`,
        win:{ exp:14, item:'짐승 고기' }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C2', t:'인형 공방 — 이 대조',
    x:`공방 벽에 종이가 붙어 있다. 사람 찾는 전단이다. 열두 장.<br><br>
      그림 속 사람들이 웃는다. 이가 보인다. 하나는 앞니가 벌어졌고 하나는 송곳니가 덧났다.<br>
      선반 위 인형들도 웃는다. 이가 보인다.<br><br>
      탐정은 그림과 인형을 번갈아 본다.`,
    o:[
      { l:'① 이 모양을 하나씩 맞춰 본다.', k:'gaze', dc:15,
        ok:`앞니 벌어진 인형, 송곳니 덧난 인형. 하나씩 전단 옆에 세웠다. 열둘이 다 맞았다.<br><br>그런데 전단은 열두 장인데 인형 이는 열세 벌이다. 마지막 인형의 이는 전단에 없다. 그 이는 사람 이가 아니다. 이 공방을 차린 것의 이다. 제 이를 제 인형에 박았다.<br>그 인형을 일행이 깼다. 위층에서 무언가 입을 감싸 쥐는 소리가 났다.<br><br>맞는 것 열둘보다 남는 하나가 더 많이 말한다. 셈이 맞을 때도 남는 것을 먼저 찾는 버릇이 들었다. 그 버릇이 오늘 범인의 이를 찾았다.`,
        ng:`맞추는데 전단 그림이 바뀐다. 웃음이 넓어진다.<br><br>그림 속 이가 인형 이를 닮아 간다. 아니, 인형 이가 그림을 닮아 간다.<br>무엇이 먼저인지 헷갈렸다. 그사이 인형 하나가 이쪽 소매를 물었다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-12, mind:-10 }, wake:1 },
      { l:'② 전단 뒷면을 본다.', k:'sense', dc:14,
        ok:`뒷면에 연필 글씨가 있다. 공방 사람이 쓴 것이다. 「위층 계단 셋째 칸 밟지 말 것.」<br><br>누가 전단을 붙이며 몰래 남겼다. 알고도 말 못 했다.<br>계단에 갔다. 셋째 칸 밑에 실이 팽팽하다. 밟으면 위층에 종이 울린다.<br><br>셋째 칸을 건너뛰었다.`,
        ng:`전단을 떼자 벽에 구멍이 있다. 전단이 가리고 있었다.<br><br>구멍 안에서 사기 손가락이 나와 이쪽 손을 잡았다.<br>뿌리치다 손등이 긁혔다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-6 } }
    ] },

  { at:'C2', t:'인형 공방 — 실이 잘린 인형',
    x:`바닥에 인형 하나가 쓰러져 있다. 실이 잘렸다.<br><br>
      다른 인형들은 다 실에 매달려 있다. 이것만 바닥이다.<br>
      실 끝을 봤다. 잘린 면이 반듯하다. 이로 끊으면 실이 일어난다. 이건 가위다.<br><br>
      이 공방에서 가위를 쓰는 건 사람뿐이다.`,
    o:[
      { l:'① 잘린 실과 둘레로 누가 잘랐는지 맞춘다.', k:'gaze', dc:14,
        ok:`실 높이가 낮다. 키 작은 사람이 잘랐다. 아이거나, 웅크린 어른이거나.<br><br>인형 둘레 먼지에 무릎 자국이 있다. 무릎 꿇고 잘랐다. 그리고 작업대 밑으로 기어갔다.<br>작업대 밑을 봤다. 아무도 없다. 가위와 빈 물통과 먹다 만 꿀 종지가 있다. 누가 여기서 살았다. 오래.<br><br>그 사람은 지금 없다. 꿀은 반만 덜어 왔다. 다시 올지 모른다.`,
        ng:`맞추는 동안 쓰러진 인형이 실 없이 일어섰다.<br><br>실이 필요 없는 인형이었다. 잘린 게 아니라 끊고 나온 것이다.<br>그것이 이쪽 발목을 물었다.`,
        win:{ exp:16, item:'꿀 한 줌' }, lose:{ hp:-14, mind:-6 } },
      { l:'② 가위의 주인이 숨을 만한 데를 몰래 살핀다.', k:'hide', dc:14,
        ok:`소리 없이 작업대와 장 사이를 살폈다. 장 뒤에 틈이 있다.<br><br>틈 안에 사람 하나가 웅크려 있다. 숨을 참고 있다. 손에 가위.<br>손가락을 입에 대 보였다. 그 사람이 고개를 끄덕였다. 위층 계단 쪽을 가위로 가리켰다. 그리고 손가락 셋을 보였다. 인형사 곁에 큰 인형이 셋.<br><br>그 사람은 따라 나오지 않았다. 아직 할 일이 있다고 했다.`,
        ng:`살피다 장을 건드렸다. 장 위 인형들이 흔들렸다.<br><br>틈 안의 사람이 놀라 가위를 휘둘렀다. 이쪽 팔이 베였다.<br>그 사람은 더 깊이 숨었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-6 } }
    ] },

  { at:'C2', t:'인형 공방 — 계단의 먼지',
    x:`위층으로 가는 계단에 먼지가 소복하다.<br><br>
      발자국이 없다. 올라간 발자국도 내려온 발자국도. 대신 가는 줄 자국이 계단마다 끌렸다.<br>
      위층에 있는 것은 내려오지 않는다. 실로 다 한다.<br><br>
      그러면 먹을 것은 누가 올리나.`,
    o:[
      { l:'① 줄 자국으로 위층 살림을 맞춘다.', k:'gaze', dc:14,
        ok:`줄 자국이 넷이다. 무게가 다르다. 셋은 가볍고 하나는 깊게 파였다.<br><br>가벼운 셋은 인형이다. 깊은 하나는 인형이 끌고 올라간 것이다. 무거운 것. 하루에 한 번. 줄 자국 위 먼지 두께로 셌다.<br>마지막 깊은 자국에 먼지가 사흘째 쌓였다. 위층은 사흘을 굶었다. 굶은 것은 굼뜨거나 사납다.<br><br>일행에게 둘 다 대비하라고 했다. 실 자를 칼과 소금을.`,
        ng:`맞추다 계단을 한 칸 올랐다. 먼지에 발자국이 찍혔다.<br><br>위층 문이 삐걱 열렸다. 줄이 하나 내려와 그 발자국을 쓸었다. 확인하듯이.<br>숨을 참고 기다렸다. 줄이 이쪽 신발 끝을 만졌다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-10, spirit:-8 } },
      { l:'② 계단을 밟지 않고 난간을 타고 오른다.', k:'evade', dc:15,
        ok:`계단을 밟지 않고 난간을 타고 올랐다.<br><br>먼지에 아무것도 안 남았다. 위층은 이쪽이 오는 걸 모른다.<br>위층 문틈으로 안을 봤다. 실을 쥔 긴 손가락들. 그 둘레에 큰 인형이 셋.<br><br>본 것을 일행에게 전했다. 내려올 때도 난간으로 왔다.`,
        ng:`난간이 썩었다. 중간에서 부러졌다.<br><br>계단에 떨어졌다. 먼지가 일었다. 소리도.<br>위층에서 실이 쏟아져 내려왔다. 굴러 내려오며 피했다. 무릎이 깨졌다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-4 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 떨어지지 않은 것',
    x:`성당이 뒤집혔을 때 떨어진 것과 안 떨어진 것이 있다.<br><br>
      의자는 못 박혀서 안 떨어졌다. 촛대도. 제단도. 그런데 기도서는 다 떨어졌다. 머리 위 먼 바닥이 아니라 발밑 천장에 쌓였다.<br>
      떨어진 것을 하나씩 본다. 펼쳐진 쪽이 다 같다.<br><br>
      성당이 뒤집힌 순간, 다들 같은 쪽을 펴고 있었다.`,
    o:[
      { l:'① 펼쳐진 쪽으로 뒤집힌 순간을 맞춘다.', k:'gaze', dc:15,
        ok:`펼친 쪽은 저녁 기도 마지막 장이다. 맨 아래 줄. 「그리 되소서」 하고 끝나는 데.<br><br>모두 마지막 한 마디를 하려는 순간 뒤집혔다. 그 한 마디가 끝나지 못했다. 성당 안 종 같은 것들이 아직도 그 한 마디를 기다리며 숨을 쉰다.<br>일행 다섯이 같이 그 말을 했다. 끝맺었다. 종 같은 것들이 일제히 멎었다. 하나씩 떨어져 내렸다. 머리 위로.<br><br>물건이 놓인 모양에서 그 순간 사람들이 무엇을 하고 있었는지를 세웠다. 지난 시각을 물건으로 되짚는 손을 얻었다. 끝나지 않은 일은 끝내 주면 된다.`,
        ng:`펼친 쪽이 다 다르다. 떨어지며 넘어갔다.<br><br>맞추는 사이 종 같은 것 하나가 내려왔다. 기도서 더미를 덮었다. 이쪽 손도.<br>손을 빼냈다. 손등이 얼음처럼 차다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-12, spirit:-8 }, wake:1 },
      { l:'② 떨어진 것들 사이에서 쓸 것을 찾는다.', k:'luck', dc:13,
        ok:`기도서 더미 사이에 바구니가 있다. 제단에 올리던 빵을 담던 것이다.<br><br>빵은 굳었다. 병은 깨졌다. 대신 바구니 바닥에 꿀단지가 있다. 빵에 바르던 것이다.<br>뒤집혀도 꿀은 안 쏟아졌다. 굳어서.<br><br>한 줌 덜었다.`,
        ng:`더미를 뒤지는데 기도서 하나가 저절로 넘어갔다.<br><br>펼친 쪽이 이쪽을 향해 멈췄다. 읽히지 않는 글씨다.<br>눈을 떼는 데 한참 걸렸다. 머리가 지끈거린다.`,
        win:{ exp:12, item:'꿀 한 줌' }, lose:{ mind:-10, spirit:-6 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 종지기의 밧줄',
    x:`종탑으로 가는 밧줄이 늘어져 있다. 거꾸로 선 성당이라 밧줄이 위로 뻗었다.<br><br>
      밧줄에 손때가 묻어 반질반질한 자리가 있다. 종지기가 잡던 자리다. 높이가 둘이다.<br>
      손때를 본다. 두 높이 사이가 팔 하나 길이다. 한 사람이 두 손으로 잡았다.<br><br>
      그런데 세 번째 손때가 있다. 훨씬 높은 데. 사람 손이 닿을 수 없는 데.`,
    o:[
      { l:'① 세 번째 손때가 무엇인지 맞춘다.', k:'gaze', dc:15,
        ok:`세 번째 손때는 넓다. 손가락이 없다. 손바닥만 닿았다. 젖은 손바닥이다. 아직 마르지 않았다.<br><br>종 같은 것들 중 하나가 이 밧줄로 다른 종들을 친다. 사람 대신 종지기를 한다. 그것을 끝내면 종들이 박자를 잃는다.<br>밧줄을 잡아당겼다. 높은 데서 무언가 끌려 내려왔다. 일행 창이 기다렸다.<br><br>손때는 거짓말을 안 한다. 쥔 것은 쥔 자리를 남긴다.`,
        ng:`맞추다 밧줄이 저절로 당겨졌다. 위로.<br><br>종이 울렸다. 바로 머리 위에서. 이쪽이 밧줄 아래 서 있었다.<br>한동안 아무것도 안 들렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-10, mind:-12 } },
      { l:'② 밧줄을 잘라 종을 멈춘다.', k:'break', dc:14,
        ok:`칼로 밧줄을 잘랐다. 위쪽 끝이 어둠 속으로 빨려 올라갔다.<br><br>종이 멈췄다. 칠 수가 없다.<br>높은 데서 무언가 실망한 소리를 냈다.<br><br>증거는 남지 않았다. 대신 조용해졌다.`,
        ng:`자르는데 밧줄이 칼을 끌고 올라갔다. 이쪽 손째.<br><br>발이 떴다. 놓았다. 떨어졌다. 늑골에 등을 찧었다.<br>칼은 위로 갔다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-4 } },
      { l:'③ 종이 울리는 박자를 세어 틈에 지난다.', k:'steady', dc:14,
        ok:`종소리를 셌다. 여덟에 한 번 쉰다. 종지기가 숨을 고르는 박자다.<br><br>쉬는 틈마다 일행을 하나씩 건너보냈다. 다섯 번 쉬는 동안 다섯이 건넜다.<br>이쪽이 마지막이었다.<br><br>박자는 사람 것이었다. 사람을 흉내 내는 것은 사람처럼 지친다.`,
        ng:`일곱에서 쉬었다. 박자가 바뀌었다.<br><br>건너던 사람이 종소리 한가운데서 멈췄다. 귀를 감싸고 쓰러졌다.<br>끌어오느라 다들 귀가 먹먹해졌다.`,
        win:{ exp:14, mind:5 }, lose:{ hp:-8, mind:-10 } }
    ] },

  { at:'C3', t:'거꾸로 선 성당 — 성가대 명단',
    x:`성가대석에 명단이 걸려 있다. 열두 이름.<br><br>
      노래가 들린다. 입이 너무 많다. 셀 수 있을 만큼 들으면 마흔은 넘는다.<br>
      셈이 안 맞는 걸 그냥 못 넘긴다. 열둘이 마흔 소리를 낸다.<br><br>
      명단 아래에 신도석 자리표가 붙어 있다. 서른 자리.`,
    o:[
      { l:'① 명단과 자리표를 맞춰 남는 소리를 가린다.', k:'gaze', dc:15,
        ok:`열둘에 서른을 더하면 마흔둘. 소리를 다시 셌다. 마흔하나.<br><br>신도들이 다 성가대에 들어갔다. 입으로. 하나만 안 들어갔다. 자리표에서 그 자리를 찾았다. 맨 뒷줄 끝. 문에서 제일 가까운 자리.<br>그 사람은 뒤집히기 전에 나갔다. 나간 문이 있다는 뜻이다. 맨 뒷줄 끝 뒤 벽을 더듬었다. 문틀이 거꾸로 걸려 있었다.<br><br>마흔하나는 노래하고, 하나는 길을 남겼다.`,
        ng:`세다가 소리 하나가 이쪽 옆에서 났다.<br><br>일행 하나의 목에서. 그 사람도 모르게 따라 부른다.<br>입을 막고 흔들어 깨웠다. 셈은 다 날아갔다.`,
        win:{ exp:20, dream:2, spirit:5 }, lose:{ mind:-12, spirit:-8 } },
      { l:'② 소리가 몰리는 쪽을 피해 숨어 지난다.', k:'hide', dc:14,
        ok:`소리는 성가대석 쪽으로 몰린다. 그 반대편 기둥 그늘을 따라 걸었다.<br><br>입이 많은 것은 귀도 많다. 그래서 숨소리까지 죽였다.<br>기둥 그늘이 끝나는 데까지 갔다.<br><br>노래는 한 번도 이쪽을 향하지 않았다.`,
        ng:`숨어 가는데 노래가 멎었다. 한꺼번에.<br><br>조용한 데서 이쪽 발소리만 났다. 마흔하나의 고개가 이쪽으로 돌았다.<br>뛰었다. 늑골에 무릎을 찧었다.`,
        win:{ exp:14, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C4', t:'포자 온실 — 안에서 잠긴 문',
    x:`온실 문은 안에서 잠겼다. 빗장이 안쪽에 걸렸다. 유리에 손자국이 안쪽에서 찍혔다.<br><br>
      누가 스스로 갇혔다. 밖으로 버섯이 나가지 못하게.<br>
      잠근 사람은 아직 안에 있다. 열쇠가 바깥에 없으니까.<br><br>
      정원사 옷을 입은 것들이 안에서 걷는다. 다섯.`,
    o:[
      { l:'① 다섯 가운데 문을 잠근 사람을 가린다.', k:'gaze', dc:15,
        ok:`다섯의 허리를 봤다. 넷은 빈 허리다. 하나만 허리띠에 쇠고리가 달렸다. 열쇠 꾸러미 자리다.<br><br>그 하나는 다른 넷보다 옷이 낡았다. 제일 오래 일했다. 정원장이다. 걸음도 하나만 다르다. 문 쪽으로 가다 돌아서고, 가다 돌아선다. 아직 문을 지킨다.<br>정원장만 남기고 나머지 넷을 먼저 쳤다. 정원장은 끝까지 문 앞에 서 있었다. 마지막에 일행이 그 허리에서 열쇠를 빌렸다. 고개 숙여.<br><br>작은 차이 몇 가지로 다섯 중 하나의 이름을 세웠다. 허리띠, 옷의 낡음, 걸음. 얼굴을 몰라도 사람을 가리는 법을 하나 더 얻었다.`,
        ng:`가리다 보니 다섯 다 허리에 쇠고리가 있다. 다 정원장 흉내다.<br><br>엉뚱한 하나를 쳤다. 나머지 넷이 한꺼번에 돌아섰다.<br>다들 유리벽에 밀려 다쳤다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-14, mind:-8 }, wake:1 },
      { l:'② 유리의 손자국을 따라 빗장 자리를 짚는다.', k:'sense', dc:14,
        ok:`손자국이 높이 둘이다. 하나는 빗장 높이, 하나는 그보다 위.<br><br>위쪽 손자국 자리 유리가 얇다. 누가 거기 대고 오래 숨을 쉬었다. 김이 서려 있다. 금도 갔다.<br>그 유리를 깨고 손을 넣어 빗장을 올렸다. 소리가 작았다.<br><br>안의 것들은 문 쪽을 보지 않았다.`,
        ng:`유리를 깼는데 소리가 컸다.<br><br>안의 다섯이 일제히 문 쪽을 봤다. 같은 걸음으로 왔다.<br>손을 빼다 유리에 팔이 그였다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C4', t:'포자 온실 — 온도 기록',
    x:`보일러실 벽에 온도 기록표가 있다. 매시간 적었다.<br><br>
      처음엔 고르다. 어느 날부터 밤마다 온도가 오른다. 아무도 안 땠는데.<br>
      숫자를 따라간다. 숫자가 오르는 시각마다 기록 옆에 짧은 줄이 있다. 「소리 남」.<br><br>
      보일러 밑에서 무언가 숨을 쉰다. 따뜻한 숨.`,
    o:[
      { l:'① 온도가 오른 시각과 소리를 맞춰 무엇이 데우는지 가린다.', k:'gaze', dc:14,
        ok:`소리가 난 시각마다 꼭 한 시간 뒤 온도가 오른다. 데우는 것은 보일러가 아니다. 보일러 밑의 것이다.<br><br>그것은 숨을 쉬어 데운다. 버섯이 좋아하게. 밤에만 깬다. 지금은 낮이다. 기록표 끝 시각을 보면 다음 깰 때까지 세 시간 남았다.<br>일행이 보일러 밑에 창을 넣었다. 자던 것이 깨기 전에. 온실 온도가 내려가기 시작했다.<br><br>숫자 줄이 범인의 잠버릇이었다.`,
        ng:`맞추다 시각을 하나 잘못 읽었다.<br><br>지금이 깰 시각이었다. 보일러 밑에서 숨이 거칠어졌다.<br>보일러실 문까지 뛰었다. 뜨거운 숨이 등을 덮쳤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
      { l:'② 보일러 밸브를 잠가 온실을 식힌다.', k:'fix', dc:14,
        ok:`밸브를 찾아 잠갔다. 녹슬었지만 돌아갔다.<br><br>관을 타고 가던 더운물이 멎었다. 온실이 천천히 식는다. 버섯이 움츠러든다.<br>보일러 밑의 것이 숨을 몰아쉬었다. 혼자서는 다 못 데운다.<br><br>밸브 옆에 정원사 물통이 걸려 있었다. 맑은 물이다.`,
        ng:`밸브를 돌리는데 관이 터졌다. 뜨거운 김이 손을 덮쳤다.<br><br>손등이 벌겋게 일었다.<br>보일러 밑의 것이 그 소리에 깼다. 다들 물러났다.`,
        win:{ exp:14, item:'맑은 물' }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C4', t:'포자 온실 — 마지막 정원사의 발자국',
    x:`포자 가루가 바닥에 고르게 앉았다. 그 위에 발자국이 한 줄 났다.<br><br>
      정원사 장화다. 한 사람. 온실 한가운데로 간다. 돌아온 발자국은 없다.<br>
      보폭을 쟀다. 처음엔 넓고, 갈수록 좁다. 끝에서는 발을 끈다.<br><br>
      지쳤거나, 끌려갔거나.`,
    o:[
      { l:'① 발자국을 끝까지 따라가 확인한다.', k:'sense', dc:15,
        doom:{ title:'끄는 발', what:'포자 더미에 묻혀 한가운데로 끌려갑니다', dc:15, sec:55,
          text:`따라갔다. 보폭이 좁아진다. 이쪽 보폭도 좁아진다. 다리가 무겁다.<br><br>발자국 끝에 장화가 서 있다. 사람은 없다. 장화 안에서 허연 실이 자라 바닥으로 이어졌다.<br>이쪽 발목에도 실이 닿아 있다. 언제부터인지 모른다. 실이 당긴다. 발을 끈다. 저 앞의 장화처럼.<br><br>발자국이 한 줄 더 난다. 돌아오는 발자국은 없다.`,
          dieText:`포자 가루가 바닥에 고르게 앉았다. 그 위에 발자국이 두 줄 났다.<br><br>정원사 장화와 다른 신발. 한가운데로 간다.<br>다음에 온 탐정은 보폭을 잴 것이다.` },
        ok:`반쯤에서 멈췄다. 보폭이 좁아지는 자리다.<br><br>그 자리에서 발자국 옆 가루가 조금 들떠 있다. 바닥 밑에 실이 깔렸다. 정원사는 지친 게 아니다. 그 자리부터 실이 발을 끌었다.<br>일행에게 그 줄 밖으로 크게 돌게 했다. 들뜬 가루를 밟지 않게.<br><br>발자국 끝의 장화는 나중에 멀리서 보았다. 서 있었다. 사람 없이.`,
        win:{ exp:24, dream:3 } },
      { l:'② 발자국이 시작한 자리에서 정원사가 남긴 것을 찾는다.', k:'gaze', dc:14,
        ok:`발자국이 시작하는 데는 도구 창고 앞이다. 처음 보폭이 넓다. 무언가 들고 갔다.<br><br>창고 안에 들고 가려던 것의 짝이 남았다. 약초를 말린 자루다. 하나를 들고 한가운데로 갔다. 무엇을 하려 했는지는 모른다. 짐작은 한다. 태우려 했다.<br>남은 자루를 챙겼다.<br><br>정원사가 못 한 것을 다음 사람이 한다.`,
        ng:`창고에 들어가는데 문 뒤에 장화 한 켤레가 서 있었다.<br><br>신은 사람 없이. 장화가 한 걸음 걸었다.<br>문을 닫고 등으로 막았다. 장화가 문을 오래 찼다.`,
        win:{ exp:16, item:'약초 뭉치' }, lose:{ hp:-10, spirit:-10 } }
    ] },

  { at:'C', t:'방 — 이빨 자국의 폭',
    x:`통로 바닥에 뼈가 흩어져 있다. 짐승 뼈다. 이빨 자국이 났다.<br><br>
      일행은 무서워한다. 탐정은 자를 꺼낸다.<br>
      이빨 자국 사이 폭을 잰다. 송곳니와 송곳니 사이. 그것이 턱의 폭이다. 턱의 폭은 머리의 폭이다.<br><br>
      머리의 폭을 알면 몸의 크기가 나온다.`,
    o:[
      { l:'① 자국으로 그것의 크기와 사는 자리를 맞춘다.', k:'gaze', dc:15,
        ok:`송곳니 사이가 두 뼘. 머리가 크다. 몸은 말만 하다.<br><br>그런데 자국이 다 뼈 위쪽에만 있다. 위에서 물었다. 그것은 바닥을 안 긴다. 높은 데 매달려 있다가 떨어지며 문다. 이 통로에서 그만한 것이 매달릴 데는 천장의 대들보 하나뿐이다.<br>일행에게 대들보 밑을 지나기 전에 창을 위로 세우게 했다. 그것이 떨어졌다. 창 위로.<br><br>뼈 하나에서 크기, 크기에서 버릇, 버릇에서 자리. 증거를 이어 붙이는 줄이 한 마디 길어졌다. 그것을 보지 않고 그것을 잡았다.`,
        ng:`재다가 자국이 셋째 뼈부터 달라졌다. 더 넓다.<br><br>둘이다. 큰 것과 더 큰 것. 셈이 엉켰다.<br>대들보 밑을 지날 때 하나만 대비했다. 다른 하나가 떨어졌다. 둘이 깔렸다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-18, mind:-6 }, wake:1 },
      { l:'② 뼈 무더기에 섞인 쓸 것을 찾는다.', k:'luck', dc:13,
        ok:`뼈 사이에 사냥꾼 가방이 있다. 끈이 이빨에 끊겼다.<br><br>안에 소금 덩이. 고기 절일 때 쓰던 것이다.<br>사냥꾼은 고기를 절일 틈이 없었다.<br><br>소금은 이쪽이 쓴다.`,
        ng:`뼈를 들추는데 뼈가 따뜻하다. 방금 것이다.<br><br>천장에서 무언가 침을 흘렸다. 이쪽 목덜미에.<br>뛰었다. 등 뒤에서 무언가 떨어지는 소리. 아슬아슬했다. 무릎이 깨졌다.`,
        win:{ exp:12, item:'소금 덩이' }, lose:{ hp:-12, spirit:-6 } }
    ] },

  { at:'C', t:'방 — 사냥꾼의 마지막 장',
    x:`벽에 기댄 사냥꾼 곁에 수첩이 떨어져 있다.<br><br>
      날마다 적었다. 잡은 것, 본 것, 잃은 것. 글씨가 반듯하다.<br>
      마지막 장도 반듯하다. 「여기서 쉰다. 이 방은 안전하다.」<br><br>
      마지막 장을 다시 본다. 다른 장보다 글씨가 반듯하다. 너무.`,
    o:[
      { l:'① 마지막 장의 글씨를 앞 장들과 맞춰 본다.', k:'gaze', dc:14,
        ok:`앞 장들은 반듯해도 끝이 흐른다. 사람 손은 지치면 흐른다. 마지막 장은 끝까지 안 흐른다. 지친 사람의 글씨가 아니다.<br><br>사냥꾼 글씨를 흉내 낸 것이다. 다음에 올 사람이 이 방에서 쉬게 하려고. 그러면 이 방에서 기다리는 것이 있다.<br>쉬지 않았다. 일행이 방 구석구석에 창끝을 넣어 보았다. 넷째 구석에서 무언가 비명을 지르며 튀어나왔다. 이미 창에 꿰인 채로.<br><br>글씨는 손을 가린다.`,
        ng:`반듯한 게 다행이라 여겼다. 다들 앉았다.<br><br>앉은 지 얼마 안 돼 구석이 움직였다.<br>일어서다 다들 엉켰다. 무언가 둘을 물고 갔다가 놓고 갔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 수첩 앞 장에서 쓸 만한 것을 찾는다.', k:'sense', dc:14,
        ok:`앞 장 하나에 지도가 있다. 「물 — 서쪽 벽 아래 틈」.<br><br>그 장은 사냥꾼 손이다. 끝이 흐른다. 믿어도 된다.<br>서쪽 벽 아래 틈에서 물이 배어 나왔다. 맑다.<br><br>마지막 장은 찢어 버렸다.`,
        ng:`앞 장을 넘기다 마지막 장이 다시 펼쳐졌다. 저절로.<br><br>「여기서 쉰다.」 그 글씨에 눈이 붙었다. 쉬고 싶다.<br>일행이 어깨를 흔들 때까지 앉아 있었다. 다리가 굳었다.`,
        win:{ exp:14, item:'맑은 물' }, lose:{ mind:-10, spirit:-6 } }
    ] },

  { at:'C', t:'방 — 신선한 미끼',
    x:`통로 한가운데 덫이 있다. 쇠 이빨 덫이다. 한가운데 고기가 놓였다.<br><br>
      고기가 신선하다. 피가 아직 흐른다. 방금 놓았다.<br>
      미끼가 신선하면 덫 놓은 자가 가깝다.<br><br>
      그런데 이 덫은 짐승을 잡기엔 너무 낮다. 사람 발목 높이다.`,
    o:[
      { l:'① 덫의 높이와 미끼로 덫 놓은 자를 맞춘다.', k:'gaze', dc:15,
        ok:`짐승 덫은 짐승 다리 높이에 놓는다. 이건 사람 발목 높이다. 사람을 잡는 덫이다.<br><br>미끼도 사람 미끼다. 짐승 고기를 쓴 건 사람이 배고프니까. 덫 놓은 것은 사람을 알고, 사람이 무엇을 주울지 안다.<br>통로 양옆 그늘을 봤다. 한쪽 그늘이 너무 짙다. 거기 웅크린 것을 일행이 먼저 쳤다.<br><br>사냥하는 것도 사냥을 당한다.`,
        ng:`맞추는 동안 일행 하나가 고기에 손을 뻗었다.<br><br>덫이 물었다. 손목이다. 그늘에서 무언가 나왔다.<br>덫을 벌리고 그것을 쫓는 데 다들 다쳤다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 막대로 덫을 먼저 터뜨린다.', k:'fix', dc:13,
        ok:`긴 막대로 덫 한가운데를 눌렀다. 쇠 이빨이 철컥 닫혔다.<br><br>그늘에서 무언가 움찔했다. 소리를 듣고 왔다가 덫이 빈 걸 보고 멈칫했다.<br>멈칫한 순간 일행이 쳤다.<br><br>고기는 덫에 물린 채 남았다. 빼서 챙겼다.`,
        ng:`막대가 짧았다. 덫이 닫히며 막대를 튕겼다.<br><br>막대 끝이 이쪽 얼굴을 쳤다.<br>그늘에서 무언가 웃는 소리가 났다.`,
        win:{ exp:14, item:'짐승 고기' }, lose:{ hp:-12, mind:-6 } },
      { l:'③ 덫 놓은 자가 돌아올 길목에 숨어 기다린다.', k:'hide', dc:15,
        ok:`덫 옆 그늘에 다들 숨었다. 숨을 죽였다.<br><br>한참 뒤 무언가 왔다. 덫을 확인하러. 덫이 비었다. 고개를 갸웃했다.<br>그 갸웃한 목을 일행 창이 꿰었다.<br><br>덫을 놓는 자는 덫을 확인하러 꼭 온다.`,
        ng:`숨었는데 그것이 오지 않았다.<br><br>대신 등 뒤에서 왔다. 숨은 자리를 먼저 알았다. 이쪽처럼 생각한다.<br>뒤를 물렸다. 겨우 떼어 냈다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-6 } }
    ] },

  { at:'C', t:'방 — 두 벌의 발자국',
    x:`진흙 바닥에 발자국이 두 벌이다. 하나는 사람, 하나는 큰 짐승.<br><br>
      사람 발자국이 앞서고 짐승 발자국이 따른다. 쫓긴 것으로 보인다.<br>
      겹친 자리를 본다. 둘이 겹치면 나중에 찍힌 것이 위에 있다.<br><br>
      사람 발자국이 짐승 발자국 위에 찍혀 있다.`,
    o:[
      { l:'① 겹친 순서로 무엇이 무엇을 쫓았는지 다시 세운다.', k:'gaze', dc:15,
        ok:`사람 발이 짐승 발 위다. 사람이 나중에 지났다. 짐승이 앞서고 사람이 따랐다.<br><br>그런데 사람 발자국의 깊이가 짐승만큼 깊다. 사람 무게가 아니다. 짐승이 사람 발로 걸었다. 앞서 간 짐승 발자국은 미끼다. 따르는 쪽이 진짜다.<br>뒤를 봤다. 사람 발자국이 이쪽 일행 뒤로도 이어져 있었다. 일행이 돌아서 창을 냈다. 어둠에서 사람 걸음을 흉내 내던 것이 꿰였다.<br><br>먼저와 나중을 뒤집으면 이야기가 뒤집힌다. 흔적의 순서를 의심하는 눈을 하나 더 얻었다. 쫓긴 쪽이 쫓는 쪽일 수 있다.`,
        ng:`순서를 가리는 사이 뒤에서 발소리가 났다. 사람 발소리다.<br><br>돌아봤을 때 사람 모양이 아니었다.<br>덮쳐 왔다. 둘이 다쳤다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-8 }, wake:1 },
      { l:'② 발자국을 지우며 다른 길로 간다.', k:'hide', dc:14,
        ok:`옷자락으로 발자국을 쓸며 옆 통로로 들어갔다.<br><br>무엇이 무엇을 쫓든, 이쪽은 쫓기지 않으면 된다.<br>한참 뒤 원래 통로에서 발소리가 지나갔다. 사람 걸음인데 너무 무거웠다.<br><br>지나갈 때까지 아무도 숨을 안 쉬었다.`,
        ng:`쓸어도 진흙에 다시 찍혔다. 이쪽 발자국이.<br><br>그 발자국을 따라 무거운 발소리가 왔다.<br>뛰었다. 진흙에 넘어졌다.`,
        win:{ exp:14, spirit:5 }, lose:{ hp:-12, mind:-6 } }
    ] },

  { at:'C', t:'방 — 상처의 방향',
    x:`일행 하나가 다쳤다. 어깨에 긴 상처. 무엇에 당했는지 아무도 못 봤다.<br><br>
      「옆에서 왔다.」 다친 사람이 말한다.<br>
      상처를 본다. 시작이 깊고 끝이 얕다. 위에서 아래로 그어졌다.<br><br>
      옆에서 그으면 상처는 옆으로 난다.`,
    o:[
      { l:'① 상처의 방향으로 그것의 자리를 짚는다.', k:'gaze', dc:14,
        ok:`위에서 아래다. 끝이 등 쪽으로 휘었다. 뒤 위에서 왔다.<br><br>다친 사람은 옆을 봤다. 옆에서 소리가 났으니까. 그것은 옆에 소리를 던지고 위에서 내려왔다.<br>등불을 들어 뒤쪽 천장을 비췄다. 천장 틈에 무언가 납작하게 붙어 있다. 일행이 창을 올렸다.<br><br>말은 틀려도 상처는 안 틀린다.`,
        ng:`상처를 보는 사이 옆에서 소리가 났다.<br><br>다들 옆을 봤다. 이쪽도.<br>위에서 무언가 내려와 이쪽 등을 그었다. 같은 모양으로.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 상처를 씻고 싸맨다.', k:'heal', dc:13,
        ok:`물로 씻었다. 깊은 데를 눌러 피를 멎게 했다. 약초를 붙였다.<br><br>싸매며 상처 끝을 봤다. 상처 안에 작은 비늘 조각이 박혀 있다. 빼서 챙겼다.<br>증거다. 나중에 쓸 데가 있다.<br><br>다친 사람이 일어섰다. 어깨가 덜 아프다고 했다.`,
        ng:`씻는데 상처가 다시 벌어졌다. 비늘 조각이 안에서 긁는다.<br><br>빼려다 깊이 밀어 넣었다. 그 사람이 비명을 질렀다.<br>한참 걸려 빼냈다. 둘 다 진이 빠졌다.`,
        win:{ exp:14, hp:8 }, lose:{ hp:-12, mind:-6 } }
    ] },

  { at:'C', t:'방 — 셋뿐인 시체',
    x:`짐승 넷을 잡았다. 다들 그렇게 기억한다.<br><br>
      쓰러진 자리에 시체가 셋이다.<br>
      넷째가 쓰러진 자리를 기억한다. 벽 쪽이었다. 벽 쪽 바닥에 쓰러진 자국이 있다. 몸은 없다.<br><br>
      자국에서 끌린 자리가 시체 더미 쪽으로 이어진다.`,
    o:[
      { l:'① 시체 더미를 하나씩 뒤집어 확인한다.', k:'gaze', dc:15,
        doom:{ title:'넷째', what:'시체 더미 속에서 붙잡혀 끌려 들어갑니다', dc:15, sec:55,
          text:`첫째를 뒤집었다. 죽었다. 둘째도. 셋째를 뒤집으려 손을 넣었다.<br><br>셋째 밑에서 손이 나왔다. 넷째가 셋째 밑에 들어가 있었다. 죽은 것 밑이 제일 안전하다는 걸 아는 것이다.<br>그것이 이쪽 손목을 물고 당겼다. 더미 밑으로. 셋의 무게가 이쪽 위로 무너진다.<br><br>시체가 넷이 될 참이다. 셈은 맞게 된다.`,
          dieText:`짐승 넷을 잡았다. 다들 그렇게 기억한다.<br><br>쓰러진 자리에 시체가 넷이다. 셈이 맞는다.<br>하나는 짐승이 아니다.` },
        ok:`더미에 손을 넣지 않았다. 끌린 자국이 더미 아래로 들어간다. 위로가 아니다.<br><br>「셋째 밑.」 일행이 창으로 더미를 통째로 찔렀다. 셋째 밑에서 비명이 났다. 넷째가 셋째를 밀치고 튀어나왔다. 이미 꿰인 채로.<br>시체가 넷이 되었다. 셈이 맞았다.<br><br>셈이 안 맞으면 맞을 때까지 의심한다. 그게 일이다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 끌린 자국 둘레를 지키며 기다린다.', k:'steady', dc:15,
        ok:`다들 더미를 둘러싸고 창을 낮췄다. 아무도 손을 안 댔다.<br><br>오래 기다렸다. 숨어 있는 것은 언젠가 숨을 쉰다.<br>셋째 시체가 조금 들썩였다. 그 순간 창 다섯이 들어갔다.<br><br>기다림이 길었다. 다리가 저렸다. 셈은 맞았다.`,
        ng:`기다리다 누가 지쳐 한 걸음 물러났다.<br><br>그 틈으로 넷째가 튀어나와 어둠으로 달아났다.<br>쫓다가 다들 다쳤다. 셈은 끝내 안 맞았다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-8 } }
    ] },

  { at:'C', t:'방 — 엇갈리는 말',
    x:`어둠 속에서 비명이 났다. 일행 하나가 짐승에게 끌려가다 놓였다.<br><br>
      「다들 같이 있었소?」 다들 그렇다고 한다. 그런데 셋째가 말한다. 「넷째는 그때 뒤에 없었소.」 넷째는 있었다고 한다.<br>
      두 말 중 하나를 고르지 않는다. 둘 다 맞을 수 있는 경위를 찾는다.<br><br>
      넷째 목소리가 아까보다 조금 낮다.`,
    o:[
      { l:'① 그때 각자 어디 있었는지 하나씩 되짚는다.', k:'gaze', dc:15,
        ok:`한 사람씩 물었다. 비명이 났을 때 등불이 어느 쪽에 있었는지, 무엇을 쥐고 있었는지.<br><br>다섯 말이 하나로 맞는다. 넷째만 빼고. 넷째는 그때 등불이 왼쪽이었다고 한다. 등불은 오른쪽이었다. 넷째는 그 자리에 없었으니 모른다.<br>셋째 말이 맞다. 그때 넷째 자리에 있던 것이 지금 넷째 목소리로 말한다. 일행이 천천히 둘러쌌다. 그것이 목소리를 버리고 짐승 소리를 냈다.<br><br>엇갈리는 말을 버리지 않고 겹쳐 놓으면 그 사이에 빈자리가 생긴다. 빈자리에 누가 서 있었는지 묻는 것. 묻는 말이 한 겹 깊어졌다.`,
        ng:`되짚다 다들 말이 엇갈렸다. 지쳐서 다 기억이 흐리다.<br><br>넷째가 이쪽 등 뒤로 돌았다. 아무도 몰랐다.<br>목덜미를 물렸다. 셋이 떼어 냈다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, spirit:-8 }, wake:1 },
      { l:'② 다 같이 서로의 손목을 한 줄로 묶는다.', k:'bond', dc:14,
        ok:`줄을 꺼내 다섯의 손목을 한 줄로 묶었다.<br><br>사람이면 묶인다. 묶인 채 같이 걷는다.<br>넷째가 묶이기 싫다고 했다. 처음 듣는 말투였다. 다들 알아챘다.<br><br>그것은 묶이기 전에 어둠으로 뛰었다. 진짜 넷째는 뒤쪽 바닥에 쓰러져 있었다. 숨은 쉬었다.`,
        ng:`묶는데 넷째가 순순히 묶였다.<br><br>묶인 채로 걸었다. 그것이 묶인 줄을 타고 옆 사람 손목을 물었다.<br>줄을 풀고 떼어 내는 데 다들 다쳤다.`,
        win:{ exp:16, spirit:6 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C', t:'방 — 늘어놓은 단서',
    x:`사냥이 길었다. 그것은 아직 잡히지 않았다. 세 번 나타나 세 번 하나씩 물고 놓았다.<br><br>
      그동안 주운 것을 바닥에 늘어놓는다. 비늘 한 조각, 젖은 털 한 줌, 물린 자국 모양을 그린 종이, 그것이 나타난 시각.<br>
      따로 보면 아무것도 아니다.<br><br>
      나란히 놓으면 무언가 된다.`,
    o:[
      { l:'① 단서를 한 줄로 이어 그것이 다음에 올 자리를 정한다.', k:'gaze', dc:16,
        ok:`비늘은 마른 데 것이다. 털은 젖었다. 마른 몸에 젖은 털. 그것은 물을 건너온다. 매번.<br><br>세 번 나타난 시각 사이가 같다. 물을 한 번 건너는 데 걸리는 시간이다. 이 근방에 물은 하나다. 다음 시각에 그것은 그 물을 건넌다.<br>물가에 일행이 엎드렸다. 시각이 왔다. 그것이 물에서 올라오는 순간 창 다섯이 들어갔다.<br><br>따로 주운 것을 한 줄로 세우면 그 줄 끝에 다음 일이 놓인다. 지난 일을 맞추던 손으로 처음 앞일을 맞췄다.`,
        ng:`이어 보는데 하나가 안 맞는다. 젖은 털이 그것의 털이 아니었다.<br><br>엉뚱한 물가에서 기다렸다. 그것은 다른 데서 왔다.<br>일행 하나를 또 물었다. 이번엔 깊었다.`,
        win:{ exp:24, dream:4 }, lose:{ hp:-18, mind:-8 }, wake:1 },
      { l:'② 단서를 덮어 두고 일행을 쉬게 한다.', k:'steady', dc:14,
        ok:`단서는 내일 봐도 된다. 다들 너무 지쳤다.<br><br>둥글게 앉혀 번갈아 쉬게 했다. 이쪽은 첫 번을 섰다.<br>그것은 그날 밤 오지 않았다. 지친 사람들이 쉬는 동안 그것도 쉬었다.<br><br>아침에 단서를 다시 늘어놓았다. 맑은 머리로 보니 하나가 눈에 띄었다.`,
        ng:`쉬게 했는데 이쪽만 못 쉬었다. 단서가 머릿속에서 돌았다.<br><br>새벽에 졸았다. 그 틈에 그것이 왔다.<br>일행 하나가 물렸다. 단서가 하나 늘었다.`,
        win:{ exp:14, hp:8, mind:5 }, lose:{ hp:-12, mind:-8 } }
    ] }
]);
